type Result = NerfGame["result"];

// Replay compatibility version, stamped on every new match. Bump it whenever
// an engine constant that feeds the deterministic replay changes (draft
// cadence, boon/card pools, offer rolling): a stored game recorded under
// different constants replays into a different stream of offers, so its
// recorded picks no longer line up and moveByUci fails mid-replay. On load,
// a started match whose stored replayVersion differs from this constant is
// ended gracefully as a draw ("server update interrupted this game") through
// the normal end flow: never silently deleted, never soft-locked.
// Version history:
//   1 (implicit) - matches stored before the field existed. They carry no
//     version to compare, so replay FAILURE is their trigger: if their
//     replay still succeeds under the current constants they play on
//     untouched; if it fails they get the same graceful draw ending.
//   2 - draft cadence moved from 10 to 6 and the nerf-mode boon pool
//     changed. From here on, a version MISMATCH is the trigger for started
//     draft games (their replay is known-desynced even when it happens not
//     to throw).
//   3 - hexes and items joined the pools: nerf mode now drafts opponent
//     hexes (60/40 weighted bucket roll inside rollOffer consumes an extra
//     RNG draw per card), items joined both modes, and the opening nerf
//     deal is capped at tier 2.
//   4 - crazyhouse-style inventory: a new tier-3 pooled card (Supply Drop)
//     grants a piece to a pocket that is dropped on a later turn. The new
//     card shifts the tier-3 pool, so in-flight offers roll differently.
//   5 - mutual king capture is now a DRAW (checkLossConditions): a king-capture
//     where the winner's king is also hanging replays as a draw, not a win, so
//     an in-flight game decided pre-bump must not resume post-bump.
//   6 - Chess Diff became a paused-game 1+0 sub-game (bs.diff): the cast no
//     longer grants the caster a mythic and the board transform, turn, and
//     grant timing all changed, so a game where the card resolved pre-bump
//     replays into a completely different state post-bump.
//   7 - several engine changes to the deterministic stream, shipped together.
//     (a) Buff-effect randomness (api.rng) moved off the per-player nerf RNG —
//     which only the server had, the root cause of the random-removal desyncs
//     — onto a stateless RNG seeded from the synced public state (ply + board
//     signature + acting color), so a random effect replayed pre-bump lands on
//     different squares post-bump. (b) Banking at the top tier now deals a
//     TWO-card apex offer, each slot tier 9 with a 10% mythic upgrade (it used
//     to guarantee a single tier-10), consuming different RNG draws; apex
//     rerolls changed the same way. (c) Living God moved from the tier-8 pool
//     to the tier-9 apex band, shifting the tier-8 pool. (d) The gambling
//     cards' payouts changed their draw counts (Roulette and the Wheel's
//     removal wedge spin twice, Jackpot's gate is now a coin flip).
//   8 - Chess Diff now uses STANDARD chess rules: the sub-game is decided by
//     checkmate/stalemate (not king capture) and no piece may move into check,
//     and the draft cadence is re-armed past the diff's plies on resume. A diff
//     recorded pre-bump (king-capture line, backlogged cadence) replays into a
//     different resolution and offer timing post-bump.
//   9 - open-handed era rule changes. (a) The v5 mutual-king-capture draw was
//     REMOVED: the first king captured ends the game with the capturer winning
//     outright, so a game decided by the draw rule pre-bump replays to a win
//     post-bump. (b) The buff/draft reveal cards (Peek, Quick Glance, Draft
//     Insight, Foresight, Mind Read, Omniscience) left every draft pool — the
//     whole draft game is public now, so there is nothing left for them to
//     reveal — shifting the pools they rolled in.
//  10 - the engine payload carries the COMPLETE draft-action stream: reroll
//     and grant opcodes are now serialized (serializeMatchForEngine) and
//     replayed remotely (replay.ts). A v9 engine mis-replays the new opcodes
//     (its action fall-through treats them as `use`), so the bump is
//     mandatory even though the wire shape is backward-parseable.
//  11 - the draft tier curve was extended past round 5 (TIER_CURVE now runs
//     to the tier-8 cap) and the top-tier slip gate now eases off in later
//     rounds. Both feed rollSharedTiers, so a v10 match replays into a
//     different stream of offers from round 5 on.
//  12 - rollSharedTiers deals ONE tier for both slots and both players: the
//     per-card top-tier slip gate is gone (it no longer draws from the RNG)
//     and round 1 never jitters up. A v11 match that reached tier 7+ replays
//     into a different stream of offers.
const REPLAY_VERSION = 12;

// Refresh a match's replay checkpoint (see StoredMatch.checkpoint) at most once
// per this many committed events (moves + draft actions), so gameForPlay never
// replays more than roughly this many plies from the last snapshot. Small
// enough to bound the per-move CPU; large enough that the serialize/store cost
// is amortized. A stale checkpoint only ever forces a one-time full replay.
const checkpointEveryPlies = 20;

type Setup = {
  whiteNerfId: string;
  blackNerfId: string;
  seed: number;
  timeSec: number;
  incrementSec: number;
};
type SeatUser = { id: string; name: string; rating: number; rd?: number; vol?: number; avatar?: string | null };
type ChatEntry = { color: Color; name: string; text: string; at: number };
// Spectator-room chat: watchers only, players never see it.
type SpectatorChatEntry = { name: string; text: string; at: number };
// One resolved draft interaction, stored in order. `ply` is the number of
// accepted moves at the moment the action happened, so replaying moves and
// actions interleaved through the engine rebuilds the exact game state
// (board mutations, RNG stream, and all) on reconnects and DO restarts.
type StoredDraftAction =
  | { ply: number; color: Color; a: "pick"; index: number; cards: { id: string; tier: number }[] }
  | { ply: number; color: Color; a: "bank" }
  | { ply: number; color: Color; a: "reroll" }
  // Owner god-panel grant: an owner summons a card straight into their own
  // hand (no draft, no offer). Recorded so the deterministic replay re-adds it,
  // but NEVER surfaced in publicDraftActions, so the opponent's replica and
  // every spectator stay unaware of the card's IDENTITY (a generic "god panel
  // used" notice still tells them a summon happened).
  | { ply: number; color: Color; a: "grant"; id: string; tier: number }
  // A player flagged the Chess Diff sub-game's 1+0 clock (`color` is the
  // flagged side). A server-time event the move stream cannot carry, so it is
  // recorded (and sent to every replica) as a draft action: replaying it runs
  // resolveDiffFlag, which ends the diff and resumes the paused game.
  | { ply: number; color: Color; a: "diffFlag" }
  | { ply: number; color: Color; a: "use"; buffIndex: number; picks: BuffPick[] };
type StoredMatch = {
  id: string;
  setup: Setup;
  tokens: Record<Color, string>;
  disconnectedAt: Partial<Record<Color, number>>;
  opponentGoneNotified: Partial<Record<Color, boolean>>;
  moves: string[];
  /** Moves committed per seat. Tracked rather than derived from move-count
   * parity because draft games hand out extra moves, which puts the turn (and
   * so the per-seat totals) off parity. See movesByColor. */
  movedBy?: Partial<Record<Color, number>>;
  result: Result;
  clocks: Record<Color, number>;
  runningSince: number | null;
  /** When a disconnect-pause must end even if the player has not come back
   * (ms epoch). The clock resumes on its own at this point so an absent player
   * can still flag; absent while the game is not paused for absence. */
  pauseUntil?: number | null;
  /** When the current disconnect-pause began (ms epoch). Billing measures from
   * here, not from `disconnectedAt`, which the reconnect path clears before the
   * charge runs (see chargePauseBudget). Null whenever no pause is active. */
  pausedSince?: number | null;
  /** Total disconnect-paused time already granted to each seat this game, so
   * repeated background/foreground cycles cannot chain unlimited free pauses. */
  pausedTotalMs?: Partial<Record<Color, number>>;
  /** First-move grace already consumed per seat. The grace is a BUDGET, not a
   * window: deriving it from `now - runningSince` handed the full allowance
   * back every time a path re-anchored runningSince (reconnect, draft settle,
   * takeback, courtesy time), so a seat could farm it. See movesByColor. */
  graceUsedMs?: Partial<Record<Color, number>>;
  /** When the current draft free lock-in window opened (ms epoch), paired with
   * dtDeadline. Kept so the window's elapsed time can be excluded from billing
   * even after it closes — see currentClocks. */
  dtWindowFrom?: number | null;
  drawOfferBy: Color | null;
  // Seat that aborted the game (result.winner null, reason "aborted"), kept so
  // the archived row can attribute the abort for abuse tracking.
  abortedBy?: Color;
  // Pending takeback request (casual games only).
  takebackOfferBy?: Color | null;
  createdAt: number;
  startedAt: number | null;
  completedAt: number | null;
  // Rated matchmade games carry the two accounts; friend games may carry them
  // too (for history) but stay casual.
  rated?: boolean;
  users?: Partial<Record<Color, SeatUser>>;
  recorded?: boolean;
  // Matchmade and rematch games start automatically once both seats connect
  // (friend games wait in the lobby for a join instead).
  autoStart?: boolean;
  // Direct challenge: only this username may join as black. Never listed as
  // an open challenge in the lobby.
  invitedUsername?: string;
  rematchOfferBy?: Color | null;
  // Set once a rematch match has been created from this one.
  rematchedTo?: string | null;
  chat?: ChatEntry[];
  spectatorChat?: SpectatorChatEntry[];
  // Colors that voluntarily revealed their rule to the table mid-game.
  revealed?: Partial<Record<Color, boolean>>;
  // Draft ruleset games. Friend/challenge Draft matches are always casual:
  // createMatch never honors a rated request. Queue Draft matches are rated
  // under their mode's rating bucket (see queueJoin).
  draft?: boolean;
  // Which section the draft game runs under: "nerf" (opening nerf pick,
  // nerf-modifier buffs only, slow cadence) or "buff" (no nerfs at all,
  // nerf-modifier buffs excluded). Absent = legacy merged rules, kept so
  // stored games replay unchanged.
  mode?: DraftMode;
  // Friend-game setting: both seats see each other's pending offer cards.
  picksVisible?: boolean;
  // "Surprise / Stacked draft" preset: the joining friend (black seat) drafts
  // with a persistent tier lift on every offer, so they receive a strong,
  // high-tier build. Casual only. Persisted so the boost replays identically.
  stacked?: boolean;
  // Replay compatibility stamp (see REPLAY_VERSION). Absent = version 1.
  replayVersion?: number;
  // Draft cadence the game was created under, persisted so replays keep
  // using it even after the engine default changes.
  cadence?: number;
  // Seed for the draft engine RNG (offer rolls). Never sent to any client:
  // it would let a client predict every future offer.
  draftSeed?: number;
  // Moderator card overrides that shape this game's draft pools (disabled
  // buff ids and tier moves), frozen at match creation. Replays re-roll
  // offers and resolve recorded pick indexes against them, so the snapshot
  // must never change over the life of a match. Absent = no overrides.
  cardOverrides?: DraftPoolOverrides;
  draftActions?: StoredDraftAction[];
  // Opening nerf draft (Draft games only). Dealt when the second seat
  // arrives; the match stays un-started (clocks off, moves rejected) until
  // both seats have picked. Options are public to both seats; each pick's
  // identity follows the usual reveal rules.
  nerfOptions?: Record<Color, string[]>;
  nerfPicks?: Partial<Record<Color, number>>;
  // Lock-in deadlines (ms epoch). The opening nerf draft and any pending
  // buff offers auto-resolve when these pass; clocks stay paused meanwhile.
  nerfDeadline?: number | null;
  dtDeadline?: number | null;
  // Which seats currently hold an unresolved buff offer, mirrored from the
  // game state whenever offers roll or resolve. Kept on the match so clock
  // math (currentClocks / finishOnFlag) can charge a straggling drafter
  // without replaying the game: past the free window the seat still holding
  // its offer pays with its own time, never the seat waiting on it.
  offerSeats?: Partial<Record<Color, boolean>> | null;
  // Draft games: the side actually to move. Buff activations consume the
  // activator's turn and tempo cards insert extra moves or skips, so move
  // parity no longer determines it. Classic games never set this.
  turnColor?: Color;
  // Chess Diff sub-game in progress: the paused game's banked clocks, swapped
  // back in when the diff is decided. Mirrors the engine's bs.diff (kept on
  // the match so flag checks never need a game replay); in a timed game the
  // live clocks hold the diff's 1+0 minute while this is set. Null/absent
  // when no diff is running.
  diff?: { savedClocks: Record<Color, number> } | null;
  // House-player seats: color -> house user id (see lib/server/bots.ts). A
  // house seat counts as connected for game start; the alarm plays its moves
  // and draft picks. Absent on every purely human game.
  bots?: Partial<Record<Color, string>>;
  // When the next pending house action (move, opening nerf pick, or buff
  // offer resolve) lands. Null/absent when no house action is pending.
  botActAt?: number | null;
  // Replay checkpoint: a serialized game snapshot taken every few plies so the
  // play path (gameForPlay) resumes from mid-game instead of replaying every
  // move from ply 0 on each bot/human action (the O(n^2)-per-game cost that
  // could blow the DO CPU limit). Purely an optimization: a stale/mismatched
  // snapshot (fingerprint or replay-version guard) is ignored and the full
  // replay runs, so it can never desync a game. `ply`/`cursor` are the
  // moves/draft-actions already folded into the snapshot; `revealed` restores
  // the buff-reveal set (as [color, buff index] pairs) the skipped replay would
  // have built. See gameFromCheckpoint / maybeCheckpoint.
  checkpoint?: {
    ply: number;
    cursor: number;
    revealed: [Color, number][];
    fp: string;
    rv: number;
    snap: GameSnapshot;
  } | null;
  // Monotonic public state revision, bumped on every committed event (moves and
  // draft actions). Doubles as the spectator event seq. Absent on legacy records
  // (they backfill to match.moves.length on first touch). Additive: nothing that
  // reads a StoredMatch requires it.
  seq?: number;
  // Public-state parity hash of the CURRENT revision (recomputed on every
  // committed event, not only on the persisted-snapshot cadence), so the
  // spectator envelope for any event carries the exact post-event hash. Small
  // (8 hex chars); additive. Absent on legacy records until the next event.
  seqHash?: string;
  // Server-authoritative PUBLIC spectator snapshot (see toPublicSnapshot). A
  // sanitized projection kept parallel to `checkpoint`: it carries only what a
  // spectator may see (no slot rng, no secret nerf id, no unrevealed card) and
  // is rebuilt whenever a board-mutating card resolves or the checkpoint
  // cadence elapses, persisted atomically with the seq bump in the same
  // saveMatch write. Absent on legacy records; the watch path builds one on
  // demand. `hash` is the public-state parity token over `snap`.
  pubSnap?: {
    seq: number;
    ply: number;
    cursor: number;
    schemaVersion: number;
    replayVersion: number;
    hash: string;
    snap: PublicSpectatorSnapshot;
  } | null;
};
type SessionAttachment = {
  id: string;
  matchId?: string;
  color?: Color;
  token?: string;
  // Account attached at websocket upgrade from the session cookie.
  userId?: string;
  username?: string;
  // Chat mute (moderation): timestamp the mute expires, read at connect time.
  mutedUntil?: number;
  // Match id this socket spectates (mutually exclusive with a seat).
  watching?: string;
  // Debounce timestamp for the courtesy/owner clock-adjust buttons, so the
  // +15s / -15s frames cannot be spammed. In-memory only (fine for a debounce).
  lastClockAdjustAt?: number;
  // Owner "see opponent buffs" toggle (god-panel accounts only, re-verified on
  // use): when set, this socket's dtState carries the OPPONENT's unmasked
  // held-buff identities. Per-socket and in-memory, so it resets on reconnect and never
  // affects any other viewer's masking.
  seeOppBuffs?: boolean;
  // Owner "infinite rerolls" toggle (god-panel accounts only, re-verified on
  // use): when set, this socket's own seat's rerollsLeft is reported as the
  // INFINITE_REROLLS sentinel (so the Reroll control always shows) and the
  // draft-reroll handler tops the real count back up so it never drains. A
  // video-scripting aid; the opponent's dtState still carries the seat's real
  // count, so nothing is leaked. Per-socket and in-memory (resets on reconnect).
  godRerolls?: boolean;
};
type QueueEntry = {
  attachmentId: string;
  userId: string;
  username: string;
  rating: number;
  rd?: number;
  vol?: number;
  avatar?: string | null;
  at: number;
};
type ClientFrame =
  | { t: "create"; d?: { timeSec?: unknown; incrementSec?: unknown; draft?: unknown; mode?: unknown; picksVisible?: unknown; invite?: unknown; stacked?: unknown; rated?: unknown } }
  | { t: "join"; d?: { id?: unknown } }
  | { t: "reconnect"; d?: { id?: unknown; color?: unknown; token?: unknown } }
  | { t: "move"; d?: { u?: unknown; ply?: unknown } }
  | { t: "resign" }
  | { t: "abort" }
  | { t: "claimWin" }
  | { t: "claimDraw" }
  | { t: "drawOffer" }
  | { t: "drawAccept" }
  | { t: "drawDecline" }
  | { t: "takebackOffer" }
  | { t: "takebackAccept" }
  | { t: "takebackDecline" }
  | { t: "queue"; d?: { pool?: unknown; mode?: unknown; target?: { userId?: unknown } } }
  | { t: "playbot"; d?: { difficulty?: unknown; mode?: unknown; timeSec?: unknown; incrementSec?: unknown; color?: unknown } }
  | { t: "queueCancel" }
  | { t: "watch"; d?: { id?: unknown } }
  | { t: "watchLeave" }
  | { t: "lobby" }
  | { t: "rematch" }
  | { t: "rematchCancel" }
  | { t: "chat"; d?: { text?: unknown } }
  | { t: "schat"; d?: { text?: unknown } }
  | { t: "reveal" }
  | { t: "dtPick"; d?: { index?: unknown } }
  | { t: "dtBank" }
  | { t: "dtReroll" }
  | { t: "dtUse"; d?: { buffIndex?: unknown; picks?: unknown } }
  | { t: "dtTarget"; d?: { buffIndex?: unknown; picks?: unknown } }
  | { t: "dtNerfPick"; d?: { index?: unknown } }
  // Owner "fun with friends" tools (SERVER-gated, see isGodPanelUser):
  // adjustOppClock nudges the opponent's clock (+15s courtesy for anyone in a
  // casual game; -15s only for the god-panel accounts); adminGrant summons a
  // card into the owner's own hand; seeOppBuffs flips a per-socket flag so the
  // owner's own dtState reveals the opponent's UNMASKED held-buff identities
  // (their eyes only; no other client's view changes). Each use is announced to
  // the table with a "God panel used" (godUsed) notice.
  | { t: "adjustOppClock"; d?: { delta?: unknown } }
  | { t: "adminGrant"; d?: { id?: unknown } }
  | { t: "seeOppBuffs"; d?: { on?: unknown } }
  // Owner "infinite rerolls": flip a per-socket flag that keeps the owner's own
  // draft Reroll control endlessly available (see the godRerolls handler).
  | { t: "godRerolls"; d?: { on?: unknown } }
  | { t: "p" };

export interface Env {
  GAME_SERVER: DurableObjectNamespace<GameServer>;
  GAME_SERVER_ORIGINS?: string;
  DB: D1Database;
  // Postgres (OCI) holding the finished-game archive, reached via Hyperdrive.
  // Optional so a worker without it still runs (games just aren't archived).
  HYPERDRIVE?: Hyperdrive;
  // House-bot engine offload (Tier 1). When "true", house move searches run on
  // the OCI engine service at HOUSE_ENGINE_URL instead of on this DO. Unset or
  // any other value keeps the search local. HOUSE_ENGINE_TOKEN is the shared
  // bearer secret (set via `wrangler secret put`), sent as Authorization.
  HOUSE_ENGINE_REMOTE?: string;
  HOUSE_ENGINE_URL?: string;
  HOUSE_ENGINE_TOKEN?: string;
  // Arena offload (Tier 2 / M2). The OCI arena runs bot-vs-bot games and POSTs
  // to /arena/* here. INGEST_ENABLED gates whether arena POSTs are accepted at
  // all (bot-vs-bot is never archived or rated — owner rule; the POSTs only
  // feed the lobby/TV and spectator end frames);
  // LOBBY_ENABLED gates whether arena games appear in the lobby/TV. Both off =
  // the arena is inert (its POSTs no-op), so this ships dark and flips on live.
  // ARENA_INGEST_TOKEN is the shared bearer secret (set via `wrangler secret put`).
  ARENA_INGEST_TOKEN?: string;
  ARENA_INGEST_ENABLED?: string;
  ARENA_LOBBY_ENABLED?: string;
  // Moderator-activity notifications (see docs/mod-notifications.md and
  // src/lib/server/modWebhook.ts). MOD_WEBHOOK_URL is a Google Apps Script /exec
  // URL that appends a row to a spreadsheet; MOD_WEBHOOK_TOKEN is an optional
  // shared secret the script checks so a leaked URL alone cannot write junk.
  // Unset = notifications are off, silently. Declared here because this
  // interface is the worker's whole env surface, even though only the Next.js
  // side reads these two.
  MOD_WEBHOOK_URL?: string;
  MOD_WEBHOOK_TOKEN?: string;
  // Tier 2 / M4 cutover, reversible. When "true", the DO stops spawning its own
  // house-vs-house filler (the arena owns bot-vs-bot); bot-vs-human pickup and
  // house seeks stay on the DO. Off = the DO runs filler itself, as before.
  // Ownership only holds while the arena is actually SUPPLYING games: if no
  // /arena/games sync carrying an accepted game lands for
  // ARENA_FILLER_FALLBACK_MS, the DO resumes its own filler until real arena
  // games return, so there is always bot-vs-bot even if the arena is down or
  // misbehaving. Flip, don't delete.
  ARENA_OWNS_FILLER?: string;
}

// Quick-pairing time controls for rated Draft matchmaking. Keys are the wire
