function randomInt(max: number): number {
  const values = new Uint32Array(1);
  crypto.getRandomValues(values);
  return values[0] % max;
}

function randomCode(length = 5): string {
  const chars = "BCDFGHJKMNPQRSTVWXYZ23456789";
  let code = "";
  for (let i = 0; i < length; i++) code += chars[randomInt(chars.length)];
  return code;
}

function newToken(): string {
  const bytes = new Uint8Array(16);
  crypto.getRandomValues(bytes);
  return [...bytes].map((byte) => byte.toString(16).padStart(2, "0")).join("");
}

function makeSeed(): number {
  return randomInt(2 ** 31);
}

// Deal the two secret rules for a new match, honoring moderator-disabled
// nerfs (card_overrides). When the disable list would leave a degenerate pool
// the full opening pool deals instead: a playable game beats the filter.
function pickNerfIds(disabledNerfIds?: string[]): { whiteNerfId: string; blackNerfId: string } {
  if (disabledNerfIds && disabledNerfIds.length > 0) {
    const off = new Set(disabledNerfIds);
    const pool = openingNerfPool().filter((nerf) => !off.has(nerf.id));
    if (pool.length >= 2) return pickNerfPair(randomInt, pool);
  }
  return pickNerfPair(randomInt);
}

function isColor(value: unknown): value is Color {
  return value === "w" || value === "b";
}

function matchKey(id: string): string {
  return `match:${id}`;
}

// `e` is the optional spectator envelope (worker stamps it only on watcher
// frames). It rides as a sibling of the existing `{t, d}` body; older clients
// ignore it, so it is fully backward compatible. See sendWatchers.
function send(ws: WebSocket | undefined, t: string, d?: unknown, e?: SpectatorEnvelope) {
  if (!ws || ws.readyState !== WebSocket.OPEN) return;
  const frame: { t: string; d?: unknown; e?: SpectatorEnvelope } = { t };
  if (d !== undefined) frame.d = d;
  if (e !== undefined) frame.e = e;
  ws.send(JSON.stringify(frame));
}

// The uniform spectator-frame header. Stamped by the server on every fanned
// watcher frame so a spectator can order, dedupe, and version-check the stream.
// Carries ONLY public metadata (ids, versions, the monotonic seq, the
// public-state parity hash) and never any private state.
type SpectatorEnvelopeType =
  | "move"
  | "draftUsed"
  | "draftResolved"
  | "draftState"
  | "draftDiff"
  | "end"
  | "clock"
  | "takeback"
  | "snapshot";
/** Frame types the client applies IN ORDER, each consuming one revision.
 * Must mirror SEQUENCED_TYPES in src/lib/spectate/spectatorSync.ts — the
 * spectator-sync harness asserts the two agree. Everything else (clock, the
 * join snapshot) is applied out of band and must not consume a revision. */
const SEQUENCED_ENVELOPE_TYPES: ReadonlySet<SpectatorEnvelopeType> = new Set([
  "move",
  "draftUsed",
  "draftResolved",
  "draftState",
  "draftDiff",
  "end",
  "takeback",
]);
type SpectatorEnvelope = {
  gameId: string;
  schemaVersion: number;
  replayVersion: number;
  stateRevision: number;
  seq: number;
  type: SpectatorEnvelopeType;
  publicHash: string;
  ts: number;
};

function error(ws: WebSocket, code: string, message: string) {
  send(ws, "error", { code, message });
}

// Constant-time-ish string comparison for bearer secrets (the arena ingest
// token), so the token cannot be probed byte by byte off response timing.
// Mirrors keysMatch in /api/analytics/summary.
function timingSafeEqual(a: string, b: string): boolean {
  const enc = new TextEncoder();
  const ab = enc.encode(a);
  const bb = enc.encode(b);
  if (ab.length !== bb.length) return false;
  let diff = 0;
  for (let i = 0; i < ab.length; i++) diff |= ab[i] ^ bb[i];
  return diff === 0;
}

// House-bot engine offload (see docs/bot-offload-tier1-engine-service.md).
// When HOUSE_ENGINE_REMOTE === "true" the house move search runs on the OCI
// box instead of this single-threaded DO. The fetch is hard-bounded so a slow
// or unreachable box can never stall the alarm tick — on timeout/failure the
// bot falls back to the local engine (full strength), never to nothing.
//
// This is a WALL-clock bound on an awaited fetch, so it costs the DO no CPU
// while waiting — it must clear the real round-trip to the engine or the
// offload silently no-ops and every bot move runs its search locally on the DO
// (the CPU spike this offload exists to avoid). The engine lives in Tokyo behind
// Cloudflare; the observed round-trip is ~500ms, so 150ms aborted every call.
// 3000ms comfortably clears RTT + engine search; bots are meant to pace their
// moves, so the extra latency is harmless.
const HOUSE_ENGINE_TIMEOUT_MS = 3000;

// Arena (Tier 2 / M2). One live bot-vs-bot game announced by the OCI arena. The
// DO holds these only in memory and expires them if the arena stops syncing, so
// a crashed/paused arena drops out of the lobby on its own.
const EXTERNAL_GAME_TTL_MS = 20 * 1000;
// How long ARENA_OWNS_FILLER is honored without an /arena/games sync that
// carried at least one ACCEPTED game (the arena polls every ~4s, so this is
// ~15 missed polls). Past it the DO resumes spawning its own filler, making
// the documented promise real: an arena that is down — or up but supplying
// nothing usable — never means a lobby with no bot-vs-bot games. When real
// arena games land again the stamp refreshes (lastArenaGamesAt) and the DO
// stops spawning new filler on the next tick; any DO-run games just play out.
const ARENA_FILLER_FALLBACK_MS = 60 * 1000;
type ExternalSeat = { userId: string; name: string; rating: number };
type ExternalGameMeta = {
  id: string;
  mode: DraftMode;
  timeSec: number;
  incrementSec: number;
  moves: number;
  seats: Record<Color, ExternalSeat>;
};
// The finished-game record the arena POSTs to /arena/end. A subset of the arena
// service's ArenaFinishedRecord. Bot-vs-bot is never archived or rated (owner
// rule), so this record's only remaining job is the spectator end frame: the
// draft fields (M3) let a spectated game's `end` frame carry held buffs.
type ArenaEndRecord = {
  id: string;
  setup: { whiteNerfId: string; blackNerfId: string; seed: number; timeSec: number; incrementSec: number };
  mode: DraftMode;
  moves: string[];
  bots: Record<Color, string>;
  seats: Record<Color, { name: string }>;
  result: { winner: Color | "draw" | null; reason: string };
  startedAt: number;
  completedAt: number;
  // M3 (spectating): present on arena records, used to rebuild the game for the
  // end frame's held-buff reveal. Optional so an older arena still archives.
  draftSeed?: number;
  cadence?: number;
  draftActions?: StoredDraftAction[];
  // Engine REPLAY_VERSION the arena built the record under (arena's own
  // ArenaFinishedRecord carries it required; optional here so an older bundle
  // that omits it still archives).
  replayVersion?: number;
};

// Bootstrap state for a spectator's wstart, pushed by the arena for a watched,
// started game (Tier 2 / M3). Mirrors arena-service ArenaSnapshot.
type ArenaSnapshot = {
  id: string;
  setup: { whiteNerfId: string; blackNerfId: string; seed: number; timeSec: number; incrementSec: number };
  mode: DraftMode;
  draft: true;
  draftSeed: number;
  cadence: number;
  moves: string[];
  draftActions: StoredDraftAction[];
  clocks: Record<Color, number>;
  startedAt: number;
  seats: Record<Color, ExternalSeat>;
};

// One spectator event the arena pushes for a watched game (Tier 2 / M3). The DO
// advances its ephemeral replica and relays the matching frame to that game's
// watchers. Mirrors arena-service ArenaFrame.
type ArenaFrame =
  | ({ kind: "snapshot" } & ArenaSnapshot)
  | { kind: "move"; id: string; ply: number; u: string; clocks: Record<Color, number> }
  | { kind: "draft"; id: string; action: StoredDraftAction; card?: { id: string; tier: number } };

// Move equality for validating a move returned by the remote engine against
// our own legal-move set. UCI (from+to+promotion) is not enough: buff-generated
// moves share a UCI with a normal move to the same square, so `via` is part of
// the identity.
function sameMove(a: Move, b: Move): boolean {
  return (
    a.from === b.from &&
    a.to === b.to &&
    (a.promotion ?? null) === (b.promotion ?? null) &&
    (a.via ?? null) === (b.via ?? null)
  );
}

// The StoredMatch subset the remote engine needs to replay the position.
// Deliberately omits clocks, sessions, tokens, users — nothing but the record
// the engine replays.
function serializeMatchForEngine(match: StoredMatch): EngineMatch {
  return {
    setup: {
      whiteNerfId: match.setup.whiteNerfId,
      blackNerfId: match.setup.blackNerfId,
      seed: match.setup.seed,
    },
    mode: match.mode,
    draft: match.draft,
    draftSeed: match.draftSeed,
    cadence: match.cadence,
    stacked: match.stacked,
    moves: match.moves,
    // The COMPLETE action stream, rerolls and grants included. A reroll
    // advances the shared draft rngState (see rerollOffer), so dropping it
    // desyncs every subsequent offer/pick in the remote replay — the engine
    // then returns moves that fail the local legality check and EVERY
    // remaining bot move in the game falls back to the local search (the
    // 2026-07-10 DO CPU outage). A grant changes the seat's hand, so later
    // `use` actions depend on it the same way.
    draftActions: match.draftActions,
  };
}

// The archive's full-fidelity draft record (draft games only). Unlike
// serializeMatchForEngine, this keeps the COMPLETE action stream — including
// reroll and grant — because the archive is the system of record and must be
// losslessly, deterministically replayable, not merely best-effort. draftSeed
// falls back to the game seed exactly as the replay loop does (enableDraftMode,
// gameFromMatch). See docs/archive-draft-record.md.
function draftRecordFromMatch(match: StoredMatch): DraftRecord {
  return {
    ...(match.mode ? { mode: match.mode } : {}),
    draftSeed: match.draftSeed ?? match.setup.seed,
    ...(match.cadence !== undefined ? { cadence: match.cadence } : {}),
    ...(match.stacked ? { stacked: true } : {}),
    ...(match.picksVisible ? { picksVisible: true } : {}),
    ...(match.cardOverrides ? { cardOverrides: match.cardOverrides } : {}),
    draftActions: match.draftActions ?? [],
  };
}

export class GameServer extends DurableObject<Env> {
  private sessions = new Map<WebSocket, SessionAttachment>();
  private dbReady: Promise<boolean> | null = null;
  // Short-lived in-memory cache of the assembled lobby snapshot. Every client
  // polls the lobby roughly every 5s and each rebuild does a full match scan on
  // this single-threaded DO, so concurrent polls serialize behind the scan.
  // Caching the shared (public) snapshot for a couple of seconds collapses that
  // burst into one scan. Cleared whenever the match set changes (saveMatch /
  // deleteMatch); queue/seek changes are absorbed by the TTL.
  private lobbyCache: { at: number; payload: unknown } | null = null;
  private static readonly LOBBY_CACHE_TTL_MS = 2000;
  // Last time a browsing viewer fetched the lobby over HTTP (GET /lobby, fronted
  // by the edge-cached /api/lobby route). Lets a lurker who holds NO WebSocket
  // still register as site presence (sitePresence), mirroring the arena's
  // presence-driven spawning. In-memory only: an evicted DO restamps on the next
  // cache-miss fetch, so at worst the house roster lags one alarm cycle behind a
  // cold start — invisible to viewers.
  private lastLobbyHttpAt = 0;
  // When the arena last POSTed an authenticated /arena/games sync — proof the
  // arena process is alive. houseTick uses it to honor ARENA_OWNS_FILLER only
  // while the arena is actually checking in, and to resume DO-run filler when
  // it goes dark (see ARENA_FILLER_FALLBACK_MS). In-memory: after an eviction the
  // isolate's boot time stands in as the reference, so a live arena gets one
  // fallback window to re-sync (it polls every ~4s) before the DO steps in.
  private lastArenaSyncAt = 0;
  // When an arena sync last carried at least one VALID (house-vs-house) game.
  // This — not the bare sync stamp — is what lets the arena keep filler
  // ownership: an arena that is up but supplying nothing usable (empty
  // registry, or a version-skewed roster whose ids all fail isHouseUserId and
  // get filtered) must hand filler back to the DO just like a dead one, or
  // the lobby sits at zero bot games with every check "passing".
  private lastArenaGamesAt = 0;
  private readonly bootedAt = Date.now();
  // Cached LIVE per-mode ratings for the house roster, read from user_ratings
  // (the same buckets recordFinishedGame moves after every rated game). The
  // lobby's online list and the house seeks display from this, so a bot's
  // shown rating actually moves as it wins and loses instead of sitting on
  // its static seed forever. One bounded query per TTL window keeps the
  // lobby/tick paths off per-poll D1 work; a read failure just falls back to
  // houseSeedRating until the next refresh.
  // `identity` rides along in the same cache window: the roster's CURRENT
  // username/avatar from the users table (the system of record once an admin
  // edits a persona from /mod/house), so seeks and filler seats show an
  // admin-renamed bot within a TTL instead of the baked constant.
  private houseRatingsCache: {
    at: number;
    byId: Map<string, Partial<Record<DraftMode, number>>>;
    identity: Map<string, { username: string; avatar: string | null }>;
    // Total recorded games per persona (summed across the nerf+buff buckets):
    // the leaderboard "games" figure, used to bias filler pairing toward the
    // bots with the fewest games so no persona lingers at zero.
    gamesById: Map<string, number>;
  } | null = null;
  private static readonly HOUSE_RATINGS_TTL_MS = 60_000;
  // In-memory tally of filler (bot-vs-bot) games each persona has been seated in
  // this isolate. Bot-vs-bot games are never recorded to the leaderboard, so this
  // is what lets the fair-pairing bias spread TV/lobby appearances evenly within
  // a session (folded onto the recorded-games figure). Resets on eviction, which
  // is fine: it only steers selection, never correctness.
  private houseFillerGames = new Map<string, number>();
  // Arena (Tier 2 / M2): bot-vs-bot games simulated on the OCI arena, kept in
  // memory only. Refreshed by /arena/games; entries older than the TTL are
  // ignored (self-heals if the arena crashes or the DO loses this on eviction).
  private externalGames = new Map<string, { meta: ExternalGameMeta; at: number }>();
  // Tier 2 / M3 (spectating): an ephemeral StoredMatch replica for each arena
  // game a human is watching, built from the arena's snapshot and advanced by
  // its move/draft frames. Never persisted. Present only while watched, so the
  // per-move replay cost the DO pays for a bot game exists only when someone is
  // looking — dropped when the last spectator leaves or the game ends.
  private externalMatches = new Map<string, StoredMatch>();
  // Live replay state for a watched arena replica (Tier 2 / M3): the
  // reconstructed game advanced one frame at a time. Without it, every
  // move/draft frame re-ran a full gameFromMatch replay from ply 1, making a
  // spectated N-move bot game O(N^2) engine work on the single DO thread — the
  // spike that tripped CPU limits and reset the isolate (killing every in-flight
  // request, /arena/games included). Continuing the same game object is
  // determinism-safe by construction: identical primitives, RNG state, and
  // buff-instance identities as a full replay, just not thrown away between
  // frames. `moves`/`cursor` track how far the game has been advanced; `rebuild`
  // is the draftRebuild reveal/acquire state this game's buff instances belong
  // to. Rebuilt from scratch on any inconsistency, so it self-heals like the
  // full-replay path it replaces. Dropped alongside the replica.
  private externalReplay = new Map<
    string,
    { game: NerfGame; moves: number; cursor: number; rebuild: { revealed: Set<BuffInstance>; acquired: Map<number, BuffInstance[]> } }
  >();
  // When the last arena frame (snapshot/move/draft) landed for each watched
  // replica. The arena is the only thing that ever ends a replica; if it dies
  // mid-game (or an old bundle aborts silently), no end frame ever comes and
  // the replica would sit "live" forever with a frozen board — the reported TV
  // stall. sweepExternalReplicas uses this to detect the silence and end the
  // game for its watchers. Dropped alongside the replica.
  private externalFrameAt = new Map<string, number>();

  constructor(ctx: DurableObjectState, env: Env) {
    super(ctx, env);
    for (const ws of this.ctx.getWebSockets()) {
      const attachment = ws.deserializeAttachment() as SessionAttachment | null;
      if (attachment) this.sessions.set(ws, attachment);
    }
    // Idle keepalive that costs nothing: the runtime answers a byte-exact
    // `{"t":"hb"}` ping with `{"t":"n"}` (the bare clock frame a payload-less
    // ping already returns) WITHOUT waking the DO or billing a request. Sockets
    // that are neither playing nor watching send `hb` instead of `p` (see
    // multiplayer.ts), so a lurker's socket no longer wakes the single-threaded
    // DO every 10s. In-game `p` frames are load-bearing (flag check, alarm
    // self-heal, clock resync) and keep the app-level path. NOTE: the match is
    // exact-bytes — keep `{"t":"hb"}` here identical to the client's frame; a
    // serializer/whitespace change silently turns free pings back into billed
    // wakes with no error.
    this.ctx.setWebSocketAutoResponse(new WebSocketRequestResponsePair('{"t":"hb"}', '{"t":"n"}'));
  }

  // Resolves to true when D1 is configured and its schema is in place.
  // Account features degrade to anonymous play when it isn't.
  //
  // A FAILED ensureSchema must NOT be cached forever: it used to be, so one
  // D1 blip on the isolate's very first db() call (most likely right after a
  // deploy, when the additive schema pass has real work to do) left db()
  // returning null for the whole life of the isolate — houseTick bailed at
  // its `if (!db) return` on every tick and the lobby sat at zero seeks and
  // zero games while the online list (baked fallbacks) still looked full.
  // Now a failure clears the latch and retries after a short backoff; only
  // success is cached. The last error is kept for /healthz.
  private dbRetryAt = 0;
  private dbLastError: string | null = null;
  private async db(): Promise<D1Database | null> {
    if (!this.env.DB) return null;
    if (!this.dbReady) {
      if (Date.now() < this.dbRetryAt) return null;
      this.dbReady = ensureSchema(this.env.DB).then(
        () => {
          this.dbLastError = null;
          return true;
        },
        (err) => {
          this.dbLastError = err instanceof Error ? err.message : String(err);
          console.error("ensureSchema failed (will retry)", err);
          // Clear the latch so the NEXT call re-runs ensureSchema (after a
          // short backoff so a hard-down D1 isn't hammered every request).
          this.dbReady = null;
          this.dbRetryAt = Date.now() + 5000;
          return false;
        },
      );
    }
    return (await this.dbReady) ? this.env.DB : null;
  }

  // Runtime on/off for the house bots. Read from the shared app_settings table
  // (a moderator flips it via POST /api/mod/house, which stores "1"/"0") and
  // cached briefly so the alarm/seek paths do no per-tick D1 work. The
  // HOUSE_ENABLED constant stays a hard code-level kill switch that wins over the
  // stored value. This is the SINGLE gate for every bit of house-bot activity:
  // houseTick() calls it first and, when off, stands the roster down and returns
  // before enqueuing any seek, spawning any filler game, or running any engine
  // move; the only other bot entry point (a human accepting a house seek in
  // queueJoin) checks it too. So OFF means zero new seeks, zero new filler, zero
  // engine moves.
  //
  // A SUCCESSFUL read with no row means ON (absent row = enabled by default). But
  // a read ERROR (D1 blip, missing binding) must NOT force ON: that used to flip
  // the bots back on for a cache window right after a moderator turned them off,
  // which is the reported "the off switch does not turn off all the bots". On any
  // failure we keep the last known state instead (defaulting ON only when the
  // flag has never once been read successfully).
  private houseEnabledCache: { value: boolean; at: number } | null = null;
  private async houseEnabled(): Promise<boolean> {
    if (!HOUSE_ENABLED) return false;
    const now = Date.now();
    if (this.houseEnabledCache && now - this.houseEnabledCache.at < houseEnabledTtlMs) {
      return this.houseEnabledCache.value;
    }
    // Fall back to the last known value on any failure, never a hard ON.
    let value = this.houseEnabledCache?.value ?? true;
    try {
      const db = await this.db();
      if (db) {
        const row = await db
          .prepare("SELECT value FROM app_settings WHERE key = ?")
          .bind("house_enabled")
          .first<{ value: string }>();
        // Successful query: an absent row is ON; a present row is OFF for any
        // recognised "off" spelling (the moderator writes "0"), else ON.
        if (!row) {
          value = true;
        } else {
          const raw = String(row.value ?? "").trim().toLowerCase();
          value = !(raw === "0" || raw === "false" || raw === "off" || raw === "no" || raw === "disabled");
        }
      }
    } catch {}
    this.houseEnabledCache = { value, at: now };
    return value;
  }

  // Whole days since the epoch — the seed for the day-varying house count and the
  // rotating active window, so both change once per (UTC) day and stay stable
  // within it. Kept here (not in the pure bots module) because Date is a DO
  // concern; the module takes it as a plain argument.
  private houseDayIndex(): number {
    return Math.floor(Date.now() / 86_400_000);
  }

  // How many house bots are active right now. DEFAULT: a day-varying value in
  // 60-90 (dailyHouseCount), so the population breathes day to day and, together
  // with the rotating window in activeHouseRoster, cycles through the 210-deep
  // roster over time. OVERRIDE: if a moderator has pinned an explicit
  // app_settings.house_count, that clamped value wins. Cached on the same ~15s TTL
  // as houseEnabled; it recomputes shortly after a day boundary.
  private houseCountCache: { value: number; at: number } | null = null;
  private async houseCount(): Promise<number> {
    const now = Date.now();
    if (this.houseCountCache && now - this.houseCountCache.at < houseEnabledTtlMs) {
      return this.houseCountCache.value;
    }
    let value = dailyHouseCount(this.houseDayIndex());
    try {
      const db = await this.db();
      if (db) {
        const row = await db
          .prepare("SELECT value FROM app_settings WHERE key = ?")
          .bind("house_count")
          .first<{ value: string }>();
        // Only a non-empty stored value overrides the daily default; an absent or
        // blank row leaves the day-varying count in place.
        if (row && row.value != null && String(row.value).trim() !== "") {
          value = clampHouseCount(Number(row.value));
        }
      }
    } catch {}
    this.houseCountCache = { value, at: now };
    return value;
  }

  // Moderator concurrent-games target (app_settings.house_games): how many
  // house-vs-house FILLER games to keep live at once, pinned from the /mod
  // "Active games" slider (0..HOUSE_GAMES_MAX). An unset/blank/garbage value
  // falls back to HOUSE_GAMES_DEFAULT (the historical band ceiling), so out of
  // the box nothing changes. Cached on the same ~15s TTL as the other house
  // settings, so a change reaches the spawner within a tick without a redeploy;
  // houseTick clamps this against the live seat budget before using it.
  private houseGamesCache: { value: number; at: number } | null = null;
  private async houseGamesTarget(): Promise<number> {
    const now = Date.now();
    if (this.houseGamesCache && now - this.houseGamesCache.at < houseEnabledTtlMs) {
      return this.houseGamesCache.value;
    }
    let value = HOUSE_GAMES_DEFAULT;
    try {
      const db = await this.db();
      if (db) {
        const row = await db
          .prepare("SELECT value FROM app_settings WHERE key = ?")
          .bind("house_games")
          .first<{ value: string }>();
        // Only a non-empty stored value overrides the default; an absent or blank
        // row leaves the historical band in place.
        if (row && row.value != null && String(row.value).trim() !== "") {
          value = clampHouseGames(Number(row.value));
        }
      }
    } catch {}
    this.houseGamesCache = { value, at: now };
    return value;
  }

  // Moderator house-strength overrides (app_settings.house_skill_overrides): a
  // per-tier JSON patch a moderator sets from /mod to weaken (or restore) the
  // bots live. Cached on the same ~15s TTL as the other house settings, so a
  // change reaches live games within a tick without a redeploy. Held as the
  // parsed map; each persona resolves its own tier fresh per move
  // (resolveHouseProfile). An absent/garbage value reads as "no overrides" =
  // baked strength.
  private houseSkillOverridesCache: { value: Record<string, unknown> | null; at: number } | null = null;
  private async houseSkillOverrides(): Promise<Record<string, unknown> | null> {
    const now = Date.now();
    if (this.houseSkillOverridesCache && now - this.houseSkillOverridesCache.at < houseEnabledTtlMs) {
      return this.houseSkillOverridesCache.value;
    }
    let value = this.houseSkillOverridesCache?.value ?? null;
    try {
      const db = await this.db();
      if (db) {
        const row = await db
          .prepare("SELECT value FROM app_settings WHERE key = ?")
          .bind("house_skill_overrides")
          .first<{ value: string }>();
        value = parseSkillOverrides(row?.value ?? null);
      }
    } catch {}
    this.houseSkillOverridesCache = { value, at: now };
    return value;
  }

  /** Resolve a house persona's effective strength: baked tier profile merged
   * with the current moderator override for that tier, if any. */
  private async houseResolvedProfile(skill: HouseSkill): Promise<ResolvedSkillProfile> {
    return resolveSkillProfile(skill, await this.houseSkillOverrides());
  }

  // Moderator card overrides (the card_overrides table), digested down to the
  // fields that shape pools: disabled buff/nerf ids and buff tier moves. One
  // bounded SELECT (the table holds at most one row per card), cached for
  // cardOverridesTtlMs and refreshed only from match creation and the opening
  // nerf deal: never per message or per alarm tick. Any read error keeps the
  // previous snapshot (or none), so a D1 blip can never block games.
  private cardOverridesCache: { value: CardOverridesSnapshot; at: number } | null = null;
  private async cardOverridesSnapshot(): Promise<CardOverridesSnapshot> {
    const now = Date.now();
    if (this.cardOverridesCache && now - this.cardOverridesCache.at < cardOverridesTtlMs) {
      return this.cardOverridesCache.value;
    }
    let value: CardOverridesSnapshot = this.cardOverridesCache?.value ?? {};
    try {
      const db = await this.db();
      if (db) {
        const { results } = await db
          .prepare(
            "SELECT id, kind, tier, enabled FROM card_overrides WHERE enabled = 0 OR tier IS NOT NULL",
          )
          .all<{ id: string; kind: string; tier: number | null; enabled: number }>();
        const next: CardOverridesSnapshot = {};
        for (const row of results ?? []) {
          if (row.kind === "buff") {
            const def = BUFF_BY_ID[row.id];
            if (!def) continue;
            if (!row.enabled) {
              (next.buffOff ??= []).push(row.id);
            } else if (
              row.tier != null &&
              Number.isInteger(row.tier) &&
              row.tier >= 1 &&
              row.tier <= 8 &&
              row.tier !== def.tier
            ) {
              (next.buffTier ??= {})[row.id] = row.tier;
            }
          } else if (row.kind === "nerf" && !row.enabled) {
            (next.nerfOff ??= []).push(row.id);
          }
        }
        value = next;
      }
    } catch {}
    this.cardOverridesCache = { value, at: now };
    return value;
  }

  // The buff-pool slice of the snapshot, in the shape stamped onto new draft
  // matches (StoredMatch.cardOverrides). Undefined when there is nothing to
  // apply, so untouched deployments keep byte-identical match records.
  private draftPoolStamp(snap: CardOverridesSnapshot): DraftPoolOverrides | undefined {
    const off = snap.buffOff ?? [];
    const tier = snap.buffTier ?? {};
    if (off.length === 0 && Object.keys(tier).length === 0) return undefined;
    return {
      ...(off.length > 0 ? { off: [...off] } : {}),
      ...(Object.keys(tier).length > 0 ? { tier: { ...tier } } : {}),
    };
  }

  // Top-level fetch: a thin guard around handleFetch so a transient storage
  // or accept throw returns a clean degraded response instead of rejecting at
  // the RPC boundary and 503-ing every request into this Durable Object.
  async fetch(request: Request): Promise<Response> {
    try {
      return await this.handleFetch(request);
    } catch (err) {
      console.error("game server fetch failed", err);
      let pathname = "";
      try {
        pathname = new URL(request.url).pathname;
      } catch {}
      if (pathname === "/healthz") {
        return Response.json(
          { ok: false, version: buildVersion, error: err instanceof Error ? `${err.name}: ${err.message}` : String(err) },
          { status: 200 },
        );
      }
      return new Response("game server unavailable", { status: 503 });
    }
  }

  private async handleFetch(request: Request): Promise<Response> {
    const url = new URL(request.url);

    if (url.pathname === "/healthz") {
      // Read-only diagnostics plus a cheap alarm-chain revival. Never run
      // orchestration here: driving engine searches from a request handler
      // blows the per-request CPU limit (learned the hard way, see the
      // retired system's history). Best-effort: a storage hiccup in the
      // revival or cleanup must not stop /healthz from returning diagnostics.
      // reviveAlarmChain is cheap (a getAlarm) and runs on every hit; the full
      // GC scan in cleanupExpired is NOT — throttle it so an uptime monitor
      // polling /healthz every few seconds cannot repeatedly trigger a
      // whole-table scan (plus delete writes) on the single thread.
      try {
        await this.reviveAlarmChain();
        const now = Date.now();
        if (now - this.lastHealthzCleanupAt >= maintenanceMinIntervalMs) {
          this.lastHealthzCleanupAt = now;
          await this.cleanupExpired();
        }
      } catch (err) {
        console.error("healthz maintenance failed", err);
      }

      // cleanupExpired above already ran (and refreshed) a full scan for GC;
      // reuse the live index for these counts via targeted reads instead of a
      // second whole-table deserialize on the single thread. "games" now
      // reports live (unfinished) games, which is the number that matters here.
      const liveMatches = await this.loadLiveMatches();
      const alarmAt = await this.ctx.storage.getAlarm();
      let houseGames = 0;
      let houseVsHouse = 0;
      for (const match of liveMatches) {
        const seats = (["w", "b"] as Color[]).filter((color) => match.bots?.[color]).length;
        if (!seats) continue;
        houseGames++;
        if (seats === 2) houseVsHouse++;
      }
      const seeks = (await this.ctx.storage.get<HouseSeekEntry[]>(houseSeeksKey)) ?? [];
      const seeded = !!(await this.ctx.storage.get<number>(houseSeededKey));

      // Cheap liveness probes for the two dependencies whose silent failure
      // makes the lobby look dead: D1 (schema latch + last error) and the
      // arena (last authenticated sync / last sync that actually carried a
      // game). All in-memory reads; no D1 work is done here.
      const nowMs = Date.now();
      // The EXACT payload a lobby poll would serve right now, reduced to
      // counts. This is the last observability gap: internal state (seeks in
      // storage, arena games in memory) can look healthy while the assembled
      // payload drops them behind some gate — comparing these counts against
      // what a browser's /api/lobby shows bisects server vs edge/client in
      // one look. Cost is one lobby build per healthz hit at most (the 2s
      // shared lobbyCache absorbs it when viewers are polling anyway).
      let lobbySnapshot: Record<string, unknown>;
      try {
        const p = (await this.buildLobbyPayload()) as {
          players?: unknown[];
          anonymous?: number;
          games?: unknown[];
          seeks?: unknown[];
          challenges?: unknown[];
        };
        lobbySnapshot = {
          players: p.players?.length ?? 0,
          anonymous: p.anonymous ?? 0,
          games: p.games?.length ?? 0,
          seeks: p.seeks?.length ?? 0,
          challenges: p.challenges?.length ?? 0,
        };
      } catch (err) {
        lobbySnapshot = { error: err instanceof Error ? err.message : String(err) };
      }
      return Response.json({
        ok: true,
        version: buildVersion,
        sockets: this.sessions.size,
        games: liveMatches.length,
        // How long this isolate has been alive: in-memory stats (presence
        // stamps, arena stamps, error fields) all reset with it, so their
        // absence only means something when the uptime says the isolate has
        // been up long enough to have seen the traffic in question.
        uptimeMs: nowMs - this.bootedAt,
        alarmAt, // ms epoch of the next scheduled maintenance pass, if any
        alarmInMs: alarmAt ? alarmAt - Date.now() : null,
        // What a lobby poll would return RIGHT NOW (counts only), plus the
        // flags that gate its contents.
        lobby: lobbySnapshot,
        flags: {
          houseOn: await this.houseEnabled(),
          arenaLobbyEnabled: this.env.ARENA_LOBBY_ENABLED === "true",
          arenaIngestEnabled: this.env.ARENA_INGEST_ENABLED === "true",
          arenaOwnsFiller: this.env.ARENA_OWNS_FILLER === "true",
        },
        db: {
          // true = schema ensured; false = last attempt failed (retrying);
          // null = not attempted yet this isolate.
          ready: this.dbReady ? await this.dbReady : null,
          lastError: this.dbLastError,
        },
        presence: {
          sitePresence: this.sitePresence(),
          lastLobbyHttpAgoMs: this.lastLobbyHttpAt ? nowMs - this.lastLobbyHttpAt : null,
        },
        arena: {
          lastSyncAgoMs: this.lastArenaSyncAt ? nowMs - this.lastArenaSyncAt : null,
          lastGamesAgoMs: this.lastArenaGamesAt ? nowMs - this.lastArenaGamesAt : null,
          liveGames: this.externalGames.size,
        },
        house: {
          roster: HOUSE_ROSTER.length,
          seeded,
          seeks: seeks.length,
          games: houseGames,
          houseVsHouse,
          tickError: this.houseTickError,
          seedError: this.houseSeedError,
          lastDesync: this.houseLastDesync,
          engineRejects: this.houseEngineRejects,
          lastEngineReject: this.houseLastEngineReject,
        },
      });
    }

    if (url.pathname === "/lobby" && request.method === "GET") {
      // Public lobby snapshot over HTTP, fronted by the edge-cached /api/lobby
      // Worker route so a crowd of browsers costs the DO ~1 request per cache
      // window instead of one WebSocket poll each. Stamp browsing presence and
      // revive the alarm chain (the same cheap getAlarm /healthz runs) so a
      // lurker with no socket still keeps the house roster and clock enforcement
      // alive. The payload is public and identical for every viewer.
      this.lastLobbyHttpAt = Date.now();
      try {
        await this.reviveAlarmChain();
      } catch {}
      return Response.json(await this.buildLobbyPayload());
    }

    if (url.pathname === "/live-game" && request.method === "GET") {
      // Authoritative live-seat lookup for the profile "Playing Right Now" card
      // (see src/components/profile/CurrentGameCard.tsx). Given a user id, return the id
      // (and public mode) of the started, unfinished game that user currently
      // occupies, or null. This reads the SAME bounded live index the lobby
      // snapshot uses, so it never scans a stale lobby cache or guesses a seat.
      // The response is public: a game id and its section only, no seat state.
      const userId = url.searchParams.get("userId");
      if (!userId) return Response.json({ gameId: null });
      const found = await this.liveGameIdForUser(userId);
      return Response.json(found ?? { gameId: null });
    }

    if (url.pathname === "/tournament/create-game" && request.method === "POST") {
      // Internal endpoint for the tournament engine (see
      // src/lib/server/tournamentEngine.ts): create a match with both seats
      // pre-assigned to named accounts. Like /live-game this path is
      // reachable ONLY through the server-side DO stub — the public worker
      // fetch routes just the socket path, /healthz, and /arena/* here — so
      // it needs no bearer token.
      return this.createTournamentGame(request);
    }

    if (url.pathname.startsWith("/arena/")) return this.handleArena(request, url);

    if (url.pathname !== socketPath) return new Response("Not found", { status: 404 });
    if (request.headers.get("Upgrade") !== "websocket") {
      return new Response("Expected WebSocket", { status: 426 });
    }
    if (!this.originAllowed(request)) {
      return new Response("Forbidden", { status: 403 });
    }

    // Same-origin websocket upgrades carry the session cookie; attach the
    // account (if any) so queueing and rated games know who this socket is.
    const attachment: SessionAttachment = { id: crypto.randomUUID() };
    const db = await this.db();
    if (db) {
      try {
        const token = sessionTokenFromCookieHeader(request.headers.get("Cookie"));
        const user = await userForSession(db, token);
        if (user) {
          attachment.userId = user.id;
          attachment.username = user.username;
          if (user.muted_until && user.muted_until > Date.now()) {
            attachment.mutedUntil = user.muted_until;
          }
        }
      } catch {
        // Anonymous on any auth failure.
      }
    }

    const pair = new WebSocketPair();
    const [client, server] = Object.values(pair);
    server.serializeAttachment(attachment);
    this.sessions.set(server, attachment);
    try {
      this.ctx.acceptWebSocket(server);
    } catch (err) {
      // The accept itself failed (hibernation limit, transient platform
      // error). Drop the half-registered session and fail this one upgrade
      // cleanly instead of throwing out of fetch and 503-ing the isolate.
      this.sessions.delete(server);
      console.error("acceptWebSocket failed", err);
      return new Response("game server unavailable", { status: 503 });
    }

    // A connecting human revives a wedged alarm chain so the house roster
    // (and clock enforcement) always comes back after a bad deploy or crash.
    try {
      await this.reviveAlarmChain();
    } catch {}

    return new Response(null, { status: 101, webSocket: client });
  }

  async webSocketMessage(ws: WebSocket, message: ArrayBuffer | string) {
    let frame: ClientFrame;
    try {
      frame = JSON.parse(typeof message === "string" ? message : new TextDecoder().decode(message)) as ClientFrame;
    } catch {
      return error(ws, "bad_json", "Messages must be JSON objects.");
    }

    switch (frame.t) {
      case "create":
        return this.createMatch(ws, frame.d);
      case "join":
        return this.joinMatch(ws, frame.d);
      case "reconnect":
        return this.reconnectMatch(ws, frame.d);
      case "move":
        return this.playClientMove(ws, frame.d);
      case "resign":
        return this.resignGame(ws);
      case "abort":
        return this.abortGame(ws);
      case "claimWin":
        return this.claimAbandonment(ws, false);
      case "claimDraw":
        return this.claimAbandonment(ws, true);
      case "drawOffer":
        return this.offerDraw(ws);
      case "drawAccept":
        return this.acceptDraw(ws);
      case "drawDecline":
        return this.declineDraw(ws);
      case "takebackOffer":
        return this.offerTakeback(ws);
      case "takebackAccept":
        return this.acceptTakeback(ws);
      case "takebackDecline":
        return this.declineTakeback(ws);
      case "queue":
        return this.queueJoin(ws, frame.d);
      case "playbot":
        return this.playHouseBot(ws, frame.d);
      case "queueCancel":
        return this.queueLeave(ws, true);
      case "watch":
        return this.watchMatch(ws, frame.d);
      case "watchLeave":
        return this.watchLeave(ws);
      case "lobby":
        return this.lobbySnapshot(ws);
      case "rematch":
        return this.rematchRequest(ws);
      case "rematchCancel":
        return this.rematchCancel(ws);
      case "chat":
        return this.chatMessage(ws, frame.d);
      case "schat":
        return this.spectatorChatMessage(ws, frame.d);
      case "reveal":
        return this.revealRule(ws);
      case "dtPick":
        return this.draftPick(ws, frame.d);
      case "dtBank":
        return this.draftBank(ws);
      case "dtReroll":
        return this.draftReroll(ws);
      case "dtUse":
        return this.draftUse(ws, frame.d);
      case "dtTarget":
        return this.draftTarget(ws, frame.d);
      case "dtNerfPick":
        return this.nerfDraftPick(ws, frame.d);
      case "adjustOppClock":
        return this.adjustOppClock(ws, frame.d);
      case "adminGrant":
        return this.adminGrant(ws, frame.d);
      case "seeOppBuffs":
        return this.seeOppBuffs(ws, frame.d);
      case "godRerolls":
        return this.godRerolls(ws, frame.d);
      case "p":
        return this.sendClocks(ws);
      default:
        return error(ws, "unknown_message", "Unknown message type.");
    }
  }

  async webSocketClose(ws: WebSocket) {
    await this.queueLeave(ws, false);
    this.notifyWatcherCount(ws);
    await this.detachSession(ws);
  }

  async webSocketError(ws: WebSocket) {
    await this.queueLeave(ws, false);
    this.notifyWatcherCount(ws);
    await this.detachSession(ws);
  }

  // When a spectating socket goes away, tell the remaining watchers the new
  // count. Must run before the session is dropped from the map.
  private notifyWatcherCount(ws: WebSocket) {
    const session = this.sessions.get(ws);
    if (!session?.watching) return;
    const id = session.watching;
    this.sessions.delete(ws);
    this.broadcastWatchers(id);
    this.dropExternalIfUnwatched(id);
  }

  private watcherCount(matchId: string): number {
    return this.watcherInfo(matchId).n;
  }

  // Count plus the signed-in watchers' usernames (deduped across tabs);
  // anonymous watchers only contribute to the count.
  private watcherInfo(matchId: string): { n: number; names: string[] } {
    let n = 0;
    const names = new Set<string>();
    for (const [ws, session] of this.sessions) {
      if (session.watching === matchId && ws.readyState === WebSocket.OPEN) {
        n++;
        if (session.username) names.add(session.username);
      }
    }
    return { n, names: [...names].slice(0, 30) };
  }

  private broadcastWatchers(matchId: string) {
    const { n, names } = this.watcherInfo(matchId);
    for (const [ws, session] of this.sessions) {
      if (ws.readyState !== WebSocket.OPEN) continue;
      if (session.watching === matchId || session.matchId === matchId) {
        send(ws, "watchers", { n, names });
      }
    }
  }

  async alarm() {
    // Nothing in here may throw out of the handler: an uncaught alarm error
    // stops rescheduling until the next external event (no flag enforcement).
    // House work runs first (a queued human waiting for a pickup is the most
    // latency-sensitive thing here) but is fully isolated: any house failure
    // degrades to "bots absent", never to broken human play.
    //
    // Alarm-chain liveness is the single most important invariant here: the
    // reschedule happens via scheduleNextAlarm (at the tail of maintenanceAll,
    // or directly on a throttled in-between tick below), so if that throws
    // before rescheduling — or the isolate is evicted mid-tick by a CPU spike —
    // the chain would die until a socket reconnect and every house game plus
    // clock enforcement would freeze: exactly the "server is always crashing /
    // bot won't move" symptom. Guard it two ways: (1) a defensive floor alarm
    // set up front, before any heavy work, so an eviction still leaves a next
    // alarm armed; (2) a fallback reschedule if either maintenance branch
    // throws. Both only pull the alarm EARLIER or fill a gap; scheduleNextAlarm
    // still refines the exact time (and clears it when truly idle). The floor is
    // gated on someone being online, matching the heartbeat/idle rule, so an
    // empty server still goes idle.
    if (this.sitePresence()) {
      try {
        await this.armAlarmBy(Date.now() + houseHeartbeatMs);
      } catch {}
    }
    try {
      await this.houseTick();
    } catch (err) {
      this.houseTickError = err instanceof Error ? err.message : String(err);
      console.error("houseTick failed", err);
    }
    // The full maintenance sweep is the CPU-heavy part (a whole-table scan plus
    // per-match work). Bot moves wake this alarm about once a second; running
    // the sweep every time is what pushed the DO past its CPU limit (#174), so
    // throttle it. On the in-between ticks do only the cheap indexed reschedule
    // so the alarm chain stays alive and live house games keep moving;
    // flag/deadline enforcement and GC still run on the next sweep, at most a
    // few seconds out. Whichever branch runs IS the reschedule point, so if it
    // throws before rescheduling the chain would die — fall back to a short
    // re-arm so the next pass recovers instead of the whole DO going dark.
    // maintenanceAll is now bounded (live-only enforcement off the persisted
    // index + a single bounded GC page), so it is cheap enough to run every
    // alarm and drains any match-table bloat a page at a time. It reschedules
    // via scheduleNextAlarm at its tail; if it throws before that, fall back to
    // a short re-arm so the chain recovers instead of the whole DO going dark.
    try {
      await this.maintenanceAll();
    } catch (err) {
      console.error("maintenanceAll failed", err);
      try {
        await this.armAlarmBy(Date.now() + 2000);
      } catch {}
    }
  }

  // Revive the alarm chain when the stored alarm is missing or well overdue.
  // A chain wedged in the past returns a non-null getAlarm() value, so
  // checking for "missing" alone never recovers a dead roster. Runs on every
  // socket connect and /healthz: getAlarm() is a cheap local read, and a
  // chain can wedge at any point in an isolate's life, so a once-per-isolate
  // latch would leave a later-wedged chain dead until the isolate recycles.
  private async reviveAlarmChain() {
    const existing = await this.ctx.storage.getAlarm();
    if (!existing || existing < Date.now() - houseHeartbeatMs) {
      await this.ctx.storage.setAlarm(Date.now() + 1000);
    }
  }

  private originAllowed(request: Request): boolean {
    const origin = request.headers.get("Origin");
    const configured = (this.env.GAME_SERVER_ORIGINS || "")
      .split(",")
      .map((allowed) => allowed.trim())
      .filter(Boolean);

    // Explicit allowlist: only the configured origins may connect.
    if (configured.length > 0) {
      return !!origin && configured.includes(origin);
    }

    // No allowlist configured: fail closed to same-origin only. Requests
    // without an Origin header (non-browser clients, which cannot be targets
    // of browser CSRF) are still permitted; cross-origin browser requests are
    // rejected instead of being allowed unconditionally.
    if (!origin) return true;
    try {
      return new URL(origin).host === new URL(request.url).host;
    } catch {
      return false;
    }
  }

  // --- Transient store for house-vs-house filler games -----------------------
  // Bot-only games are entertainment, not records: NOTHING about them is ever
  // written durably (owner rule: "you don't need to store bot vs bot — not
  // anything"). Their live record — moves, clocks, draft actions, replay
  // checkpoint included — lives only in this in-memory map, and their finished
  // state is never archived to D1/Postgres (see endMatch). Human games are
  // untouched: any match with a human seat persists on every save exactly as
  // before. If the isolate is evicted mid-game the games simply vanish and the
  // filler spawner starts fresh TV games; nobody loses anything that matters.
  private botMatches = new Map<string, StoredMatch>();

  /** True for a filler game with NO human seat (both seats house personas). */
  private isBotOnlyMatch(match: StoredMatch): boolean {
    return !!match.bots?.w && !!match.bots?.b;
  }

  private async loadMatch(id: string): Promise<StoredMatch | null> {
    // Bot-only games live only in the in-memory record (never stored).
    const transient = this.botMatches.get(id);
    if (transient) return transient;
    return (await this.ctx.storage.get<StoredMatch>(matchKey(id))) ?? null;
  }

  private async saveMatch(match: StoredMatch, schedule = true) {
    // The match set changed (create / start / move / end), so the cached lobby
    // snapshot is stale. Clearing it forces the next poll to rebuild.
    this.lobbyCache = null;
    if (this.isBotOnlyMatch(match)) {
      if (match.result) {
        // Finished bot-vs-bot: nothing is kept, anywhere. Drop the transient
        // record and clear any durable copy an older build may have written
        // (the previous scheme wrote a creation record + sparse heartbeats).
        this.botMatches.delete(match.id);
        await this.ctx.storage.delete(matchKey(match.id));
      } else {
        // Live bot-vs-bot: memory only. Zero storage writes per move.
        this.botMatches.set(match.id, match);
      }
    } else {
      await this.ctx.storage.put(matchKey(match.id), match);
      // A human game is always durable; make sure it never shadows a stale
      // transient copy (a seat swap cannot happen, but stay defensive).
      this.botMatches.delete(match.id);
    }
    await this.ensureLiveIndex();
    // The live-id set only changes when a game is created or ends; skip the
    // durable index write on the per-move saves where nothing changed.
    if (this.trackLive(match)) await this.persistLiveIndex();
    if (schedule) await this.scheduleAlarmForMatch(match);
  }

  private async deleteMatch(match: StoredMatch) {
    this.lobbyCache = null;
    for (const [ws, session] of this.sessions) {
      if (session.matchId === match.id) {
        this.sessions.delete(ws);
        ws.close(1000, "Game expired");
      }
    }
    this.liveMatchIndex?.delete(match.id);
    this.botMatches.delete(match.id);
    await this.ctx.storage.delete(matchKey(match.id));
  }

  // In-memory mirror of the persisted live-match id set (liveIdsKey). The single
  // global DO serializes ALL traffic, so the frequent paths (houseTick,
  // lobbySnapshot) must never deserialize the whole match table just to reach the
  // handful of live games. Kept exact by saveMatch/deleteMatch (which also
  // persist it) and reconciled by the bounded GC sweep.
  private liveMatchIndex: Set<string> | null = null;

  // Cursor into the "match:" keyspace for the bounded GC sweep. Null means the
  // next sweep starts from the beginning of the keyspace.
  private gcCursor: string | null = null;

  // When /healthz last ran its GC sweep. Gates it so an uptime monitor polling
  // /healthz cannot force back-to-back sweeps on the single thread.
  private lastHealthzCleanupAt = 0;

  // Keep the index in step with a write: a finished game leaves the live set,
  // any other save is a live game. Assumes the index is already loaded.
  // Returns whether membership actually changed, so saveMatch can skip the
  // durable index write on the per-move saves where nothing moved.
  private trackLive(match: StoredMatch): boolean {
    if (!this.liveMatchIndex) return false;
    if (match.result) return this.liveMatchIndex.delete(match.id);
    if (this.liveMatchIndex.has(match.id)) return false;
    this.liveMatchIndex.add(match.id);
    return true;
  }

  // Persist the live-id set so a fresh isolate can load it without a scan.
  private async persistLiveIndex() {
    if (!this.liveMatchIndex) return;
    await this.ctx.storage.put(liveIdsKey, [...this.liveMatchIndex]);
  }

  // Load the live-id set once per isolate from its persisted copy (one cheap
  // get), never from a whole-table scan. The bounded GC sweep folds in any ids
  // the persisted set missed (e.g. a write that raced an isolate restart).
  private async ensureLiveIndex(): Promise<Set<string>> {
    if (this.liveMatchIndex) return this.liveMatchIndex;
    const stored = (await this.ctx.storage.get<string[]>(liveIdsKey)) ?? [];
    this.liveMatchIndex = new Set(stored);
    return this.liveMatchIndex;
  }

  // Load only the unfinished matches, via batched point reads off the live
  // index instead of a full-table scan. A stale entry (record already gone, or
  // finished since the index last updated) is pruned in passing so it stops
  // showing up on the live paths.
  private async loadLiveMatches(): Promise<StoredMatch[]> {
    const index = await this.ensureLiveIndex();
    const ids = [...index];
    const matches: StoredMatch[] = [];
    // storage.get accepts up to 128 keys per batched read.
    for (let i = 0; i < ids.length; i += 128) {
      const chunk = ids.slice(i, i + 128);
      const found = await this.ctx.storage.get<StoredMatch>(chunk.map(matchKey));
      for (const id of chunk) {
        // Bot-only (filler) games live ONLY in the transient store (see
        // saveMatch; they are never written durably). Every live path that goes
        // through this loader (houseTick's due pass and re-arm sweep, the lobby
        // snapshot, maintenance flag checks) must see the SAME record loadMatch
        // serves, so the map is consulted before the batched storage read.
        const match = this.botMatches.get(id) ?? found.get(matchKey(id));
        if (!match || match.result) {
          index.delete(id);
          continue;
        }
        matches.push(match);
      }
    }
    return matches;
  }

  // The started, unfinished game a user currently occupies, if any. Reads the
  // bounded live index (the same set the lobby snapshot walks), so it is an
  // authoritative live-seat lookup, not a stale-lobby-cache scan. Returns the
  // public game id plus its section (mode) only; never seat/board state. A user
  // is only ever in one live game at a time, so the first match wins.
  private async liveGameIdForUser(
    userId: string,
  ): Promise<{ gameId: string; mode?: DraftMode } | null> {
    for (const match of await this.loadLiveMatches()) {
      if (!match.startedAt || match.result) continue;
      for (const color of ["w", "b"] as Color[]) {
        if (match.users?.[color]?.id === userId) {
          return { gameId: match.id, ...(match.mode ? { mode: match.mode } : {}) };
        }
      }
    }
    return null;
  }

  private connectedSession(matchId: string, color: Color): WebSocket | undefined {
    for (const [ws, session] of this.sessions) {
      if (session.matchId === matchId && session.color === color && ws.readyState === WebSocket.OPEN) return ws;
    }
    return undefined;
  }

  private connectedSessions(matchId: string): WebSocket[] {
    return [...this.sessions]
      .filter(([ws, session]) => session.matchId === matchId && ws.readyState === WebSocket.OPEN)
      .map(([ws]) => ws);
  }

  private session(ws: WebSocket): SessionAttachment {
    const restored = ws.deserializeAttachment() as SessionAttachment | null;
    const session = this.sessions.get(ws) ?? restored;
    if (!session) {
      const next = { id: crypto.randomUUID() };
      this.sessions.set(ws, next);
      ws.serializeAttachment(next);
      return next;
    }
    this.sessions.set(ws, session);
    return session;
  }

  private async attachSession(ws: WebSocket, match: StoredMatch, color: Color) {
    const existing = this.connectedSession(match.id, color);
    if (existing && existing !== ws) existing.close(1000, "Reconnected from another tab");

    const session = { ...this.session(ws), matchId: match.id, color, token: match.tokens[color] };
    delete session.watching;
    this.sessions.set(ws, session);
    ws.serializeAttachment(session);
    delete match.disconnectedAt[color];
    delete match.opponentGoneNotified[color];

    // Remember which account holds this seat (used for names in the UI and
    // for game history). Matchmade seats are assigned at pairing and are
    // never overwritten here.
    if (session.userId && session.username && !match.users?.[color]) {
      let rating = 1500;
      let rd = 350;
      let vol = 0.06;
      let avatar: string | null = null;
      const db = await this.db();
      if (db) {
        const row = await this.seatCategoryRating(db, session.userId, this.matchRatingCategory(match));
        if (row) {
          rating = row.rating;
          rd = row.rd;
          vol = row.vol;
          avatar = row.avatar;
        }
      }
      match.users = {
        ...(match.users ?? {}),
        [color]: { id: session.userId, name: session.username, rating, rd, vol, avatar },
      };
    } else if (match.users?.[color]?.id) {
      // Returning seat: re-read its rating so every start frame this player
      // receives shows the live number for this game's own rating bucket
      // (see refreshSeatRatings for the invariant). The caller persists the
      // match after attaching.
      await this.refreshSeatRatings(match, [color]);
    }
  }

  private async detachSession(ws: WebSocket) {
    const session = this.sessions.get(ws) ?? (ws.deserializeAttachment() as SessionAttachment | null);
    this.sessions.delete(ws);
    if (!session?.matchId || !session.color) return;
    if (this.connectedSession(session.matchId, session.color)) return;

    const match = await this.loadMatch(session.matchId);
    if (!match) return;
    match.disconnectedAt[session.color] = Date.now();
    match.opponentGoneNotified[session.color] = false;
    // House game: pause the game clock when the human seat disconnects DURING
    // THEIR OWN TURN, so a disconnected human never flags while it is their
    // move (the clock resumes on reconnect). Bank the time run so far first,
    // exactly like a draft-offer pause does. Bots have no socket, so only the
    // human's departure triggers this; the bot itself never "disconnects".
    //
    // Crucially, the pause is gated on it being the human's turn. When it is
    // the BOT's turn the clock keeps running: the bot's own time must keep
    // draining so a stuck bot game still flags through the normal timeout path
    // (finishOnFlag in maintenanceAll). The old code paused regardless of whose
    // turn it was, so a human who kept refreshing (e.g. because a desync left
    // the board visibly stuck) repeatedly re-paused the bot's clock on the
    // bot's turn and it never timed out — the "bot gets all its time back, the
    // game hangs forever" report. Only the mover ever risks an unfair flag, so
    // pausing on the mover's own turn is all the human protection this needs.
    //
    // The pause is also BOUNDED, in two ways: one absence buys at most
    // PAUSE_MAX_MS, and a seat gets at most PAUSE_BUDGET_MS across the whole
    // game (both in src/lib/server/clockPause.ts). Both exist because it used
    // to be
    // open-ended and self-sustaining: nothing resumed it except the player
    // coming back, so five minutes away cost only the socket's close-detection
    // window, and backgrounding a phone tab (which closes the socket and is
    // indistinguishable from a real disconnect) froze the clock indefinitely.
    // pauseUntil is registered with the alarm, so the clock restarts itself.
    if (
      match.bots &&
      !match.bots[session.color] &&
      match.startedAt &&
      !match.result &&
      match.runningSince !== null &&
      this.chargedColor(match) === session.color
    ) {
      const grant = pauseGrantMs(match, session.color);
      // Budget exhausted: no pause at all, the clock simply keeps running.
      if (grant > 0) {
        const now = Date.now();
        this.bankClocks(match, now);
        match.runningSince = null;
        match.pauseUntil = now + grant;
        // Stamp the start so chargePauseBudget can bill this absence no matter
        // which path ends it; the reconnect path wipes disconnectedAt first.
        match.pausedSince = now;
        await this.armAlarmBy(match.pauseUntil);
      }
    }
    await this.saveMatch(match);
  }

  private async newCode(length = 5): Promise<string> {
    let code = randomCode(length);
    while (await this.loadMatch(code)) code = randomCode(length);
    return code;
  }

  private socketForAttachment(id: string): WebSocket | undefined {
    for (const [ws, session] of this.sessions) {
      if (session.id === id && ws.readyState === WebSocket.OPEN) return ws;
    }
    return undefined;
  }

  // Which rating bucket a match plays for: mode games (Draft with a section)
  // use their mode bucket ("nerf"/"buff"); everything else buckets by time
  // control (legacy classic behavior).
  private matchRatingCategory(match: StoredMatch): RatingCategory {
    if (match.draft && match.mode) return match.mode;
    return categoryForTimeControl(match.setup.timeSec, match.setup.incrementSec);
  }

  // Rating shown/staked for a seat, from the independent rating buckets
  // (seeded from the legacy shared rating on first contact).
  private async seatCategoryRating(
    db: D1Database,
    userId: string,
    category: RatingCategory,
  ): Promise<{ rating: number; rd: number; vol: number; avatar: string | null; username: string | null } | null> {
    try {
      // The avatar/username read is independent of the rating read: run them
      // together so a seat attach costs one D1 round-trip of latency, not two.
      // username is only consumed by houseSeatUser (an admin can rename a
      // house persona from /mod/house); human callers ignore it.
      const [ratings, row] = await Promise.all([
        loadCategoryRatings(db, [userId], category),
        db
          .prepare("SELECT avatar, username FROM users WHERE id = ?")
          .bind(userId)
          .first<{ avatar: string | null; username: string | null }>(),
      ]);
      const r = ratings.get(userId);
      if (!r) return null;
      return {
        rating: r.rating,
        rd: r.rd,
        vol: r.vol,
        avatar: row?.avatar ?? null,
        username: row?.username ?? null,
      };
    } catch {
      return null;
    }
  }

  // Re-read the given seats' rating (plus rd/vol/avatar) from the CURRENT
  // value of the SAME rating bucket this game is rated in
  // (matchRatingCategory).
  //
  // INVARIANT: the rating a start frame shows beside a player must equal what
  // recordFinishedGame will read as `before` when the game ends, so the
  // number on the game screen plus the end frame's delta is exactly the end
  // frame's new rating. match.users is a snapshot taken when the seat was
  // created (queue pairing / challenge creation / rematch creation); rated
  // games recorded for the same account+bucket between that snapshot and the
  // game actually being played (a challenge sitting in the lobby while the
  // host plays elsewhere, rematch chains, a second tab) leave it stale — the
  // "in-game said 1759, game over said 1802 +13" bug. Refreshing on attach
  // and at game start keeps every surface built from match.users honest.
  // Callers persist the match afterwards.
  private async refreshSeatRatings(match: StoredMatch, colors: Color[]) {
    if (match.result) return;
    const db = await this.db();
    if (!db) return;
    // Both seats read independent rows; refresh them concurrently.
    await Promise.all(
      colors.map(async (color) => {
        const seat = match.users?.[color];
        if (!seat?.id) return;
        const row = await this.seatCategoryRating(db, seat.id, this.matchRatingCategory(match));
        if (row) {
          seat.rating = row.rating;
          seat.rd = row.rd;
          seat.vol = row.vol;
          seat.avatar = row.avatar;
          // House bots can be renamed from /mod/house (or the inline profile
          // editor). The users row is the canonical identity, so a LIVE seat
          // reflects a rename on the next attach/start refresh — every
          // current-state surface built from match.users (game cards, spectate,
          // board rows) then shows the new name. Human seats keep their session
          // name; only house identities are re-synced here. (Once the game ends,
          // endMatch snapshots the name into the archived games row, which is a
          // HISTORICAL record and is never rewritten by a later rename.)
          if (row.username && isHouseUserId(seat.id)) seat.name = row.username;
        }
      }),
    );
  }

  private playersPayload(match: StoredMatch) {
    const seat = (color: Color) => {
      const user = match.users?.[color];
      return user
        ? {
            name: user.name,
            rating: Math.round(user.rating),
            avatar: user.avatar ?? null,
            // Provisional (RD still wide) so clients can render "1500?".
            // Omitted when the seat snapshot predates rd tracking.
            ...(typeof user.rd === "number" ? { provisional: isProvisional({ rd: user.rd }) } : {}),
            // No house flag leaves the server: house seats are shaped exactly
            // like human seats (owner request: no bot trace anywhere).
          }
        : { name: "Anonymous", rating: null, avatar: null };
    };
    return { w: seat("w"), b: seat("b") };
  }

  private sendWatchers(match: StoredMatch, t: string, d?: unknown, envType?: SpectatorEnvelopeType) {
    // Stamp the ordered spectator envelope only when a caller names an event
    // type (the board/draft/clock/end frames). Untyped fanned frames (watcher
    // counts, spectator chat) carry no header, exactly as before.
    const e = envType ? this.spectatorEnvelope(match, envType) : undefined;
    for (const [ws, session] of this.sessions) {
      if (session.watching === match.id && ws.readyState === WebSocket.OPEN) send(ws, t, d, e);
    }
  }

  // Projected rating movement for each seat before the game is decided, so
  // players can see what a win/draw/loss is worth ("+8 / +0 / -8").
  private ratingPreview(match: StoredMatch): Record<Color, { win: number; draw: number; loss: number }> | null {
    if (!match.rated || !match.users?.w || !match.users?.b) return null;
    const w = { rating: match.users.w.rating, rd: match.users.w.rd ?? GLICKO_DEFAULT.rd, vol: match.users.w.vol ?? GLICKO_DEFAULT.vol };
    const b = { rating: match.users.b.rating, rd: match.users.b.rd ?? GLICKO_DEFAULT.rd, vol: match.users.b.vol ?? GLICKO_DEFAULT.vol };
    const whiteWins = glickoUpdatePair(w, b, 1);
    const draw = glickoUpdatePair(w, b, 0.5);
    const blackWins = glickoUpdatePair(w, b, 0);
    const delta = (after: number, before: number) => Math.round(after - before);
    return {
      w: {
        win: delta(whiteWins.a.rating, w.rating),
        draw: delta(draw.a.rating, w.rating),
        loss: delta(blackWins.a.rating, w.rating),
      },
      b: {
        win: delta(blackWins.b.rating, b.rating),
        draw: delta(draw.b.rating, b.rating),
        loss: delta(whiteWins.b.rating, b.rating),
      },
    };
  }

  private startPayload(match: StoredMatch, color: Color) {
    const clocks = this.currentClocks(match);
    const myNerfId = color === "w" ? match.setup.whiteNerfId : match.setup.blackNerfId;
    const masterRng = new RNG(match.setup.seed);
    const wSeed = masterRng.fork().getState();
    const bSeed = masterRng.fork().getState();
    const nerfSeed = color === "w" ? wSeed : bSeed;
    const preview = this.ratingPreview(match);
    const revealed: Partial<Record<Color, string>> = {};
    if (match.revealed?.w) revealed.w = match.setup.whiteNerfId;
    if (match.revealed?.b) revealed.b = match.setup.blackNerfId;
    // Draft matches ship the public action record (for exact board replay)
    // plus this seat's filtered view of the live draft state.
    let draftExtras: Record<string, unknown> | null = null;
    if (match.draft) {
      const game = match.startedAt ? this.gameFromMatch(match) : null;
      const opp: Color = color === "w" ? "b" : "w";
      draftExtras = {
        draft: true,
        ...(match.mode ? { mode: match.mode } : {}),
        // The real draft RNG seed, so the client's reconnect replay advances
        // the SAME draft rngState the server did (its locally rolled
        // placeholder offers are discarded; the server's frames carry the real
        // cards). Card-EFFECT randomness no longer reads any seed: api.rng is
        // derived per event from the synced public state (fxRng in
        // engine/game.ts), which is what keeps random removals identical on
        // the server, both clients, and spectators.
        draftSeed: match.draftSeed ?? match.setup.seed,
        // FULL TRANSPARENCY: every draft match plays open-handed now, so the
        // client's picks-visible UI (opponent offer view, face-up dock) is
        // always on regardless of how the match record was created.
        picksVisible: true,
        dtActions: this.publicDraftActions(match, color),
        ...(game?.buffs ? { dtState: this.draftStateFor(game, match, color) } : {}),
        ...(match.dtDeadline ? { dtDeadline: match.dtDeadline } : {}),
        // The opening nerf draft, while unresolved. Both sides' options are
        // public; only this seat's own pick index is included.
        ...(match.nerfOptions && !match.startedAt
          ? {
              nerfDraft: {
                options: match.nerfOptions,
                myPick: match.nerfPicks?.[color] ?? null,
                oppPicked: match.nerfPicks?.[opp] != null,
                deadline: match.nerfDeadline ?? null,
              },
            }
          : {}),
      };
    }
    // Is the OTHER seat currently away, and since when? The opponentGone frame
    // is a one-shot (opponentGoneNotified latches so it is not re-sent every
    // alarm tick), and the client resets its own opponentGone flag on every
    // start frame — so before this field existed, a player who refreshed during
    // an abandonment window lost the claim-win UI for good even though claimWin
    // would still have been accepted. Shipping the raw timestamp lets the
    // client rebuild the countdown from where it actually stands.
    const oppSeat: Color = color === "w" ? "b" : "w";
    const oppGoneSince =
      !match.result && match.startedAt ? (match.disconnectedAt[oppSeat] ?? null) : null;
    return {
      id: match.id,
      color,
      token: match.tokens[color],
      nerfId: myNerfId,
      nerfSeed,
      timeSec: match.setup.timeSec,
      incrementSec: match.setup.incrementSec,
      wc: Math.round(clocks.w),
      bc: Math.round(clocks.b),
      moves: match.moves,
      players: this.playersPayload(match),
      rated: !!match.rated,
      chat: match.chat ?? [],
      ...(oppGoneSince != null ? { oppGoneSince } : {}),
      ...(Object.keys(revealed).length ? { revealed } : {}),
      ...(preview ? { preview } : {}),
      ...(draftExtras ?? {}),
    };
  }

  private sendStart(match: StoredMatch, color: Color) {
    const ws = this.connectedSession(match.id, color);
    send(ws, "start", this.startPayload(match, color));
    if (match.result) {
      const clocks = this.currentClocks(match);
      send(ws, "end", {
        result: match.result,
        wc: Math.round(clocks.w),
        bc: Math.round(clocks.b),
        nerfs: { w: match.setup.whiteNerfId, b: match.setup.blackNerfId },
      });
    }
    // Seed this seat's spectator display with the current watcher list, so a
    // player who joins (or reconnects) while people are already watching sees
    // them right away, not only after the next watch/leave broadcast. Cheap:
    // watcherInfo is an in-memory pass over the sessions map, no storage.
    if (ws) {
      const { n, names } = this.watcherInfo(match.id);
      if (n > 0) send(ws, "watchers", { n, names });
    }
  }

  private broadcast(match: StoredMatch, t: string, d?: unknown) {
    send(this.connectedSession(match.id, "w"), t, d);
    send(this.connectedSession(match.id, "b"), t, d);
  }

  // Which held-buff instances of the most recently rebuilt draft match are
  // public knowledge, plus which instances each stored pick acquired. Derived
  // fresh on every gameFromMatch replay (never persisted): a buff identity is
  // public once its effect has shown on the table, so the set is a pure
  // function of the action and move record. Rules:
  // - instant cards reveal at pick (their effect lands on the board),
  // - activated cards reveal at use (dtUsed carries the identity so replicas
  //   can apply the effect), along with anything a use appends (Mirror
  //   copies, stolen cards),
  // - passive cards reveal the first time one of their granted moves is
  //   played (the move is tagged with the buff id via `move.via`).
  private draftRebuild: {
    matchId: string;
    revealed: Set<BuffInstance>;
    acquired: Map<number, BuffInstance[]>;
  } | null = null;

  private markBuffRevealed(inst: BuffInstance | undefined) {
    if (inst) this.draftRebuild?.revealed.add(inst);
  }

  private isBuffRevealed(inst: BuffInstance): boolean {
    const def = BUFF_BY_ID[inst.id];
    if (def?.kind === "instant") return true;
    // A passive that filters the opponent's legal moves is felt by the
    // opponent from the moment it is drafted (and its fx motif is meant to
    // paint on their pieces): if their replica does not know the card, the
    // filter never runs there and every filtered move looks legal locally but
    // is rejected by the server: a permanent "board out of sync" experience.
    if (def?.kind === "passive" && def.filterOpponentMoves) return true;
    return this.draftRebuild?.revealed.has(inst) ?? false;
  }

  // A hidden passive whose onMovePlayed hook just mutated the board or added
  // a board effect has shown itself on the table exactly like an instant's
  // pick effect does: mark it revealed so replicas receive its identity and
  // can replay the mutation themselves. Runs after every playMove, both on
  // the live path (commitMove, which also pushes the pre-move state to the
  // replicas) and on every rebuild, so the revealed set is a deterministic
  // function of the move and action record.
  private markHookFiredRevealed(game: NerfGame): void {
    const bs = game.buffs;
    if (!bs?.lastHookMutations) return;
    for (const f of bs.lastHookMutations) {
      this.markBuffRevealed(bs.players[f.color].buffs[f.index]);
    }
  }

  // Live-path companion to markHookFiredRevealed: after playMove, mark the
  // fired hooks revealed and report whether any card was NEWLY revealed. When
  // it was, `pre` (a plain deep clone of the pre-move BuffMatchState) is
  // prepared for the pre-move dtState frame: every clone whose live instance
  // is revealed is marked too, so the frame cannot re-mask cards the replicas
  // already know while it unmasks the one that just fired.
  private revealFiredHooks(game: NerfGame, pre: BuffMatchState): boolean {
    const bs = game.buffs;
    if (!bs?.lastHookMutations) return false;
    let revealedNow = false;
    for (const f of bs.lastHookMutations) {
      const inst = bs.players[f.color].buffs[f.index];
      if (inst && !this.isBuffRevealed(inst)) revealedNow = true;
      this.markBuffRevealed(inst);
    }
    if (!revealedNow) return false;
    for (const color of ["w", "b"] as Color[]) {
      pre.players[color].buffs.forEach((clone, i) => {
        const live = bs.players[color].buffs[i];
        if (live && this.isBuffRevealed(live)) this.markBuffRevealed(clone);
      });
    }
    return true;
  }

  // A move tagged with a held buff's id proves the mover holds that card.
  private markViaRevealed(game: NerfGame, move: Move): boolean {
    if (!move.via || !game.buffs) return false;
    const inst = game.buffs.players[move.color].buffs.find((b) => b.id === move.via);
    if (!inst || this.draftRebuild?.revealed.has(inst)) return false;
    this.markBuffRevealed(inst);
    return true;
  }

  private gameFromMatch(match: StoredMatch): NerfGame | null {
    if (!match.startedAt) return null;
    // Buff mode plays without handicaps: both seats run the unrestricted nerf.
    const nerfById = (id: string) =>
      match.mode === "buff" ? UNRESTRICTED_NERF : PLAYABLE_NERFS.find((nerf) => nerf.id === id);
    const white = nerfById(match.setup.whiteNerfId);
    const black = nerfById(match.setup.blackNerfId);
    if (!white || !black) return null;

    const game = newGame(white, black, match.setup.seed);
    if (match.draft) {
      // Replay under the cadence the game was recorded with (older records
      // carry none and fall back to the mode default).
      enableDraftMode(game, match.draftSeed ?? match.setup.seed, {
        mode: match.mode,
        ...(match.cadence ? { cadence: match.cadence } : {}),
        // Stacked-draft preset: the joining friend (black) drafts +2 tiers on
        // every offer. Re-applied on every rebuild so replays stay identical.
        ...(match.stacked ? { stackFor: "b" as Color, stackBoost: 2 } : {}),
      });
      this.draftRebuild = { matchId: match.id, revealed: new Set(), acquired: new Map() };
    }
    // A full replay from the opening: fold in every move + draft action.
    return this.replayForward(game, match, 0, 0);
  }

  // Advance `game` (already built to the state after `startPly` moves and
  // `startCursor` draft actions) forward to the current record head. Shared by
  // gameFromMatch (from a fresh opening) and gameFromCheckpoint (from a
  // mid-game snapshot). Draft actions replay interleaved with moves: an action
  // recorded at ply N happened after N accepted moves, so replaying both
  // streams through the engine reproduces the RNG stream, offers, and board
  // mutations exactly. The match's frozen card-overrides snapshot is installed
  // for the whole replay so offers re-roll from exactly the pools they first
  // rolled from, and cleared in the finally so no other game's rolls see it.
  // Returns null on an unreproducible move (a stale record), exactly as the
  // callers already handle.
  private replayForward(
    game: NerfGame,
    match: StoredMatch,
    startPly: number,
    startCursor: number,
  ): NerfGame | null {
    setDraftPoolOverrides(match.draft ? match.cardOverrides ?? null : null);
    try {
      const actions = match.draftActions ?? [];
      let cursor = startCursor;
      const applyActionsUpTo = (ply: number) => {
        while (cursor < actions.length && actions[cursor].ply <= ply) {
          this.applyStoredDraftAction(game, actions[cursor], cursor);
          cursor += 1;
        }
      };
      for (let i = startPly; i < match.moves.length; i++) {
        applyActionsUpTo(i);
        const move = moveByUci(game, match.moves[i]);
        if (!move) return null;
        if (match.draft) this.markViaRevealed(game, move);
        game = playMove(game, move);
        // Re-derive fire-time reveals (hidden passives whose hooks mutated
        // the board on this move) so reconnect payloads unmask them too.
        if (match.draft) this.markHookFiredRevealed(game);
      }
      applyActionsUpTo(match.moves.length);
      if (match.result) game.result = match.result;
      // Clock adjustments requested by the replayed picks were already applied
      // to the persisted clocks in their own live cycle; drop the regenerated
      // requests so the live apply path only ever sees the new action's.
      if (game.buffs) game.buffs.clockFx = undefined;
      return game;
    } finally {
      setDraftPoolOverrides(null);
    }
  }

  // Play-path rebuild that resumes from the match's checkpoint instead of
  // replaying from ply 0 (the per-move O(n) that becomes O(n^2) over a game and
  // could blow the DO CPU limit under a handful of long house games). The
  // checkpoint is trusted only after three guards, any of which falls back to a
  // clean full replay — so it can only ever be a speedup, never a desync:
  //   1. schema/version: the snapshot format (GAME_SNAPSHOT_VERSION, checked in
  //      deserializeGame) and the replay version (REPLAY_VERSION) both match;
  //   2. bounds: the snapshot is not ahead of the record (a takeback rewound
  //      the arrays), so the delta replay is well-defined;
  //   3. fidelity: the deserialized game reproduces the exact fingerprint the
  //      snapshot was stamped with (catches a serializer bug or subtle skew).
  private gameFromCheckpoint(match: StoredMatch): NerfGame | null {
    const ckpt = match.checkpoint;
    if (
      !ckpt ||
      ckpt.rv !== REPLAY_VERSION ||
      ckpt.ply > match.moves.length ||
      ckpt.cursor > (match.draftActions?.length ?? 0)
    ) {
      return this.gameFromMatch(match);
    }
    const game = deserializeGame(ckpt.snap);
    if (!game || desyncFingerprint(game).hash !== ckpt.fp) {
      return this.gameFromMatch(match);
    }
    if (match.draft) {
      // Restore the reveal set the skipped replay (plies 0..ckpt.ply) would have
      // built, so draftStateFor/commitMove mask the right buffs. Reveal-ness
      // maps to a buff's stable [color, index] slot (buff lists are
      // append-only). `acquired` is intentionally left empty: it is only read by
      // publicDraftActions, which always runs off a full gameFromMatch rebuild,
      // never off this play-path checkpoint.
      const revealed = new Set<BuffInstance>();
      if (game.buffs) {
        for (const [color, index] of ckpt.revealed) {
          const inst = game.buffs.players[color].buffs[index];
          if (inst) revealed.add(inst);
        }
      }
      this.draftRebuild = { matchId: match.id, revealed, acquired: new Map() };
    }
    // Fold in only the moves/actions after the checkpoint. A null here (an
    // unreproducible delta — should never happen off a validated checkpoint)
    // still degrades to a clean full replay rather than a soft-lock.
    return this.replayForward(game, match, ckpt.ply, ckpt.cursor) ?? this.gameFromMatch(match);
  }

  // Refresh the match's replay checkpoint from the current live game, at most
  // once every checkpointEveryPlies "events" (moves + draft actions) so the
  // per-move serialize cost stays negligible while bounding the delta replay.
  // Called from the commit paths (a move or a settled draft action), where the
  // game is fully up to date and draftRebuild holds the current reveal set.
  private maybeCheckpoint(match: StoredMatch, game: NerfGame) {
    if (!match.startedAt || match.result) return;
    const events = match.moves.length + (match.draftActions?.length ?? 0);
    const cp = match.checkpoint;
    const since =
      cp && cp.rv === REPLAY_VERSION && cp.ply <= match.moves.length
        ? events - (cp.ply + cp.cursor)
        : checkpointEveryPlies;
    if (since < checkpointEveryPlies) return;
    const revealed: [Color, number][] = [];
    if (game.buffs && this.draftRebuild?.matchId === match.id) {
      for (const color of ["w", "b"] as Color[]) {
        game.buffs.players[color].buffs.forEach((inst, i) => {
          if (this.draftRebuild!.revealed.has(inst)) revealed.push([color, i]);
        });
      }
    }
    match.checkpoint = {
      ply: match.moves.length,
      cursor: match.draftActions?.length ?? 0,
      revealed,
      fp: desyncFingerprint(game).hash,
      rv: REPLAY_VERSION,
      snap: serializeGame(game),
    };
  }

  // Assemble the PUBLIC match bits toPublicSnapshot needs (ids, ratings,
  // revealed rules, clocks, the server revision). Every field is already
  // public: secret nerf ids are surfaced only once revealed, and the card
  // history is the spectator-masked record.
  private publicSnapshotBits(match: StoredMatch, seq: number): PublicSnapshotBits {
    const seat = this.playersPayload(match);
    const player = (color: Color) => {
      const s = seat[color] as { name: string; rating: number | null; provisional?: boolean };
      return {
        name: s.name,
        rating: s.rating,
        ratingCategory: match.mode ?? null,
        title: null,
        ...(typeof s.provisional === "boolean" ? { provisional: s.provisional } : {}),
      };
    };
    // A nerf id is secret until the game ends or the seat reveals it. Buff mode
    // has no nerf at all, so it is never a secret to surface.
    const revealed = (color: Color): string | null => {
      if (match.mode === "buff") return null;
      if (match.result || match.revealed?.[color]) {
        return color === "w" ? match.setup.whiteNerfId : match.setup.blackNerfId;
      }
      return null;
    };
    let timerState: PublicTimerState = "paused";
    if (match.result) {
      timerState = /time/i.test(match.result.reason) ? "flagged" : "paused";
    } else if (
      match.startedAt &&
      match.runningSince !== null &&
      // Same condition currentClocks bills on. Without it a spectator was told
      // "running" through a draft free window that the server is NOT charging
      // (the backstop path leaves runningSince set), so the watcher's local
      // tick drifted down and then snapped back on the next frame.
      !this.draftWindowHolds(match, Date.now())
    ) {
      timerState = this.chargedColor(match) === "w" ? "running-w" : "running-b";
    }
    const clocks = this.currentClocks(match);
    return {
      gameId: match.id,
      replayVersion: REPLAY_VERSION,
      stateRevision: seq,
      lastSeq: seq,
      cursor: match.draftActions?.length ?? 0,
      capturedAtMs: Date.now(),
      mode: match.mode ?? null,
      rated: !!match.rated,
      players: { w: player("w"), b: player("b") },
      clocks: { w: Math.round(clocks.w), b: Math.round(clocks.b) },
      timeSec: match.setup.timeSec,
      incrementSec: match.setup.incrementSec,
      timerState,
      revealedNerfs: { w: revealed("w"), b: revealed("b") },
      ...(match.draft ? { publicCardHistory: this.publicDraftActions(match, "spectator") } : {}),
      offerSeats: { w: !!match.offerSeats?.w, b: !!match.offerSeats?.b },
      nextDraftAtPly: null,
      spectatorDelaySec: 0,
      lastCardPlayId: null,
    };
  }

  // Project the already-reconstructed game into a stored pubSnap record (the
  // sanitized public snapshot + its parity hash). Never triggers a fresh replay
  // on its own: the caller passes the game it already holds.
  private buildPubSnap(
    match: StoredMatch,
    game: NerfGame,
    seq: number,
  ): NonNullable<StoredMatch["pubSnap"]> {
    const snap = toPublicSnapshot(game, this.publicSnapshotBits(match, seq));
    snap.publicHash = publicStateHash(snap);
    return {
      seq,
      ply: match.moves.length,
      cursor: match.draftActions?.length ?? 0,
      schemaVersion: PUBLIC_SNAPSHOT_VERSION,
      replayVersion: REPLAY_VERSION,
      hash: snap.publicHash,
      snap,
    };
  }

  // Refresh the public parity hash and, when warranted, rebuild the
  // authoritative public spectator snapshot. Called on every commit path right
  // before saveMatch so the refreshed projection persists in the same write.
  // `force` rebuilds regardless of cadence: pass it when a board-mutating card
  // resolves and on result, so a resyncing spectator can never land on a stale
  // board. Reuses the passed-in game; it never replays. Absent-startedAt
  // (pre-game) is a no-op.
  //
  // It does NOT advance match.seq. The revision counter is allocated per
  // EMITTED FRAME by spectatorEnvelope (see there) — one bump followed by
  // three fanned frames must produce three distinct, consecutive seqs, not
  // three copies of one. The snapshot is stamped with the seq the next frame
  // will carry, which is the frame that delivers this board.
  private bumpPublicSnapshot(match: StoredMatch, game: NerfGame, opts?: { force?: boolean }) {
    if (!match.startedAt) return;
    const seq = (match.seq ?? match.moves.length) + 1;
    // Build the (cheap, replay-free) projection every event so the spectator
    // envelope carries the exact post-event parity hash. Reuses the already
    // reconstructed game, never a fresh replay, so this stays O(pieces) per
    // event. Only the HEAVY full snapshot is persisted on the cadence/force
    // gate below; the small hash is always refreshed.
    const built = this.buildPubSnap(match, game, seq);
    match.seqHash = built.hash;
    const prev = match.pubSnap;
    const cadenceElapsed =
      !prev ||
      prev.schemaVersion !== PUBLIC_SNAPSHOT_VERSION ||
      prev.replayVersion !== REPLAY_VERSION ||
      seq - prev.seq >= checkpointEveryPlies;
    if (opts?.force || cadenceElapsed) {
      match.pubSnap = built;
    }
  }

  // Build the SpectatorEnvelope header for a fanned watcher frame, ALLOCATING
  // this frame's revision.
  //
  // The client reducer applies a sequenced frame only at exactly
  // lastAppliedSeq + 1 and drops anything at or below it. Reading a shared
  // match.seq here meant every frame emitted after a single bump carried the
  // same number, so only the first survived: the dtUsed after a dtResolved,
  // and the dtState that follows a draft resolution, were silently dropped for
  // every ordered spectator — and the pre-move reveal frames, which are sent
  // BEFORE the commit's bump, carried an already-applied seq and were dropped
  // too. Allocating per frame makes each one land, and keeps the sequence
  // gapless (a gap would stall the reducer until a resync).
  private spectatorEnvelope(match: StoredMatch, type: SpectatorEnvelopeType): SpectatorEnvelope {
    // Out-of-band types (clock, and the join snapshot) are applied by the
    // client WITHOUT advancing its lastAppliedSeq, so allocating for them here
    // would open a gap the reducer can never fill. They ride the current
    // revision instead. Mirrors SEQUENCED_TYPES in spectatorSync.ts.
    const seq = SEQUENCED_ENVELOPE_TYPES.has(type)
      ? (match.seq ?? match.moves.length) + 1
      : (match.seq ?? match.moves.length);
    match.seq = seq;
    return {
      gameId: match.id,
      schemaVersion: PUBLIC_SNAPSHOT_VERSION,
      replayVersion: REPLAY_VERSION,
      stateRevision: seq,
      seq,
      type,
      publicHash: match.seqHash ?? match.pubSnap?.hash ?? "",
      ts: Date.now(),
    };
  }

  // Ensure a public snapshot exists to ship on join. Returns the stored one, or
  // builds it on demand from the already-reconstructed game (no persist -- the
  // next committed event persists it), or null when the game cannot be
  // reconstructed (a migration stage turns null into a structured wunavailable).
  private ensurePubSnap(match: StoredMatch): StoredMatch["pubSnap"] {
    if (
      match.pubSnap &&
      match.pubSnap.schemaVersion === PUBLIC_SNAPSHOT_VERSION &&
      match.pubSnap.replayVersion === REPLAY_VERSION
    ) {
      return match.pubSnap;
    }
    if (!match.startedAt) return null;
    let game: NerfGame | null = null;
    try {
      game = this.gameFromMatch(match);
    } catch {
      game = null;
    }
    if (!game) return null;
    const seq = match.seq ?? match.moves.length;
    const built = this.buildPubSnap(match, game, seq);
    match.seqHash = built.hash;
    return built;
  }

  // Rebuild the live game for a play-path caller (moves, resigns, draft
  // frames, house actions). A started, unfinished match whose replay can no
  // longer be trusted is ended gracefully here instead of returning null
  // into a soft-lock: a stamped replayVersion that differs from the current
  // constant means the replay is known-desynced (v2+), and an outright
  // replay failure catches v1 records from before the stamp existed (see
  // REPLAY_VERSION). The draw goes through the normal end flow, so the end
  // frame reaches both seats and the game is recorded, never deleted. The
  // draw is forced UNRATED: a game the server cut short with an update should
  // not move either player's rating (the rating apply path skips unrated, and
  // the end frame reports rated:false to the clients).
  private async gameForPlay(match: StoredMatch): Promise<NerfGame | null> {
    const stale =
      match.replayVersion != null && match.replayVersion !== REPLAY_VERSION && !match.result;
    const game = stale ? null : this.gameFromCheckpoint(match);
    if (!game && match.startedAt && !match.result) {
      this.bankClocks(match);
      match.runningSince = null;
      match.result = { winner: "draw", reason: "server update interrupted this game" };
      match.completedAt = Date.now();
      match.rated = false;
      await this.endMatch(match);
    }
    return game;
  }

  private applyStoredDraftAction(game: NerfGame, action: StoredDraftAction, index: number) {
    if (action.a === "pick") {
      const bs = game.buffs;
      const ps = bs?.players[action.color];
      const before = ps?.buffs.length ?? 0;
      const effectsBefore = bs?.effects.length ?? 0;
      const mutationsBefore = bs?.mutations ?? 0;
      pickDraftCard(game, action.color, action.index);
      const acquired = ps ? ps.buffs.slice(before) : [];
      // A pick whose init observably touched the board or effects is public
      // (mirrors resolveDraftPick): replicas must replay it or they desync.
      if (bs && (bs.effects.length !== effectsBefore || (bs.mutations ?? 0) !== mutationsBefore)) {
        for (const b of acquired) this.markBuffRevealed(b);
      }
      this.draftRebuild?.acquired.set(index, acquired);
    } else if (action.a === "bank") {
      bankDraft(game, action.color);
    } else if (action.a === "reroll") {
      // Re-roll the offer off the (replayed) RNG at the same tiers. Never
      // reaches clients (filtered from publicDraftActions), so only the
      // server's own rebuild replays it.
      rerollDraft(game, action.color);
    } else if (action.a === "grant") {
      // Owner god-panel summon: re-add the card to the granting seat's hand on
      // every rebuild. Deliberately NOT markBuffRevealed: this stays masked to
      // the opponent (its identity is a secret, exactly like an un-revealed
      // draft pick). The tier is re-derived from the library so a stored value
      // can never drift from the card definition.
      const def = BUFF_BY_ID[action.id];
      if (def) acquireBuff(game, action.color, action.id, def.tier);
    } else if (action.a === "diffFlag") {
      // A Chess Diff clock flag: end the diff against the flagged color and
      // resume the paused game, exactly as the live path did.
      resolveDiffFlag(game, action.color);
    } else {
      const bs = game.buffs;
      const mine = bs?.players[action.color];
      const theirs = bs?.players[action.color === "w" ? "b" : "w"];
      const inst = mine?.buffs[action.buffIndex];
      const mineBefore = mine?.buffs.length ?? 0;
      const theirsBefore = theirs?.buffs.length ?? 0;
      activateBuff(game, action.color, action.buffIndex, action.picks);
      // Using a card makes it public, along with anything the use created or
      // moved between the players (Mirror copies, stolen cards).
      this.markBuffRevealed(inst);
      for (const added of mine?.buffs.slice(mineBefore) ?? []) this.markBuffRevealed(added);
      for (const added of theirs?.buffs.slice(theirsBefore) ?? []) this.markBuffRevealed(added);
    }
  }

  // Moves the given color has already played.
  //
  // Counted as moves commit (movedBy), NOT derived from move-count parity: in
  // a draft game an extra-move card lets one side move twice in a row, and
  // `activeColor` below already documents that turns leave parity for exactly
  // that reason. Parity credited the wrong seat — after White plays, takes an
  // extra move, and plays again, `moves.length === 2` read as "Black has moved
  // once", so Black lost the first-move grace on a move they had not made and
  // White lost the rest of theirs. That fed the grace check, the flag alarm,
  // the bot think budget and the turn-heal rebank.
  //
  // Falls back to parity for matches persisted before `movedBy` existed, which
  // is exactly as right (and as wrong) as it was for them before.
  private movesByColor(match: StoredMatch, color: Color): number {
    const tracked = match.movedBy?.[color];
    if (tracked != null) return tracked;
    return color === "w" ? Math.ceil(match.moves.length / 2) : Math.floor(match.moves.length / 2);
  }

  /** Record a committed move against its mover, for movesByColor. Call BEFORE
   * pushing onto match.moves: the legacy seed reads the pre-push length. */
  private countMove(match: StoredMatch, mover: Color) {
    const w = match.movedBy?.w ?? Math.ceil(match.moves.length / 2);
    const b = match.movedBy?.b ?? Math.floor(match.moves.length / 2);
    match.movedBy = { w, b, [mover]: (mover === "w" ? w : b) + 1 };
  }

  // Whose turn it is. Classic turns always alternate w, b, w, … so this is
  // pure move-count parity, with no need to replay the game. Keeping clock
  // and flag checks off the replay path is what stops the single-threaded
  // Durable Object from stalling live sockets and the lobby. Draft games
  // track the real turn on the match instead (buff activations and tempo
  // cards move it off parity).
  private activeColor(match: StoredMatch): Color {
    return match.turnColor ?? (match.moves.length % 2 === 0 ? "w" : "b");
  }

  // Which seat the running clock bills. Normally the side to move — but in a
  // draft game, once the free lock-in window has expired with exactly one
  // seat still holding its offer, that straggler pays: the waiting player
  // may not move while the draft is open, so their clock must never run.
  // (Both seats straggling keeps the mover charged: both are equally late,
  // and a single running timestamp can only bill one side.)
  private chargedColor(match: StoredMatch): Color {
    const active = this.activeColor(match);
    if (match.draft && match.startedAt && !match.diff && !match.result) {
      const w = !!match.offerSeats?.w;
      const b = !!match.offerSeats?.b;
      if (w !== b) return w ? "w" : "b";
    }
    return active;
  }

  // Mirror which seats hold an unresolved offer onto the match, so clock
  // math never needs a game replay. Call wherever offers roll (commitMove)
  // or resolve (settleDraftAction) with the post-mutation game in hand.
  private syncOfferSeats(match: StoredMatch, game: NerfGame | null) {
    if (!match.draft || !game?.buffs) {
      match.offerSeats = null;
      return;
    }
    match.offerSeats = {
      w: !!game.buffs.players.w.offer,
      b: !!game.buffs.players.b.offer,
    };
  }

  // Buff mode's opening pick: the opener offers are dealt at game CREATION
  // (enableDraftMode -> rollOpenerOffers), before any move, so no commitMove
  // ever opens their lock-in window. Without this, a starting buff game sent
  // its start frames with no dtDeadline and a running clock: clients treated
  // the free window as already expired (the draft mounted minimized on the
  // red "On your clock" chip) and the seats burned clock from ply 0 while
  // both players were still picking their opener. Call after match.startedAt
  // is set and BEFORE the start frames go out, so they carry the deadline.
  // No-op for non-draft games and for nerf mode (no openers), and once both
  // openers are resolved settleDraftAction resumes the clock exactly like a
  // mid-game round.
  private async openStartDraftWindow(match: StoredMatch, now: number) {
    if (!match.draft || !match.startedAt || match.result) return;
    const game = await this.gameForPlay(match);
    if (!game?.buffs) return;
    if (!game.buffs.players.w.offer && !game.buffs.players.b.offer) return;
    match.dtDeadline = now + draftPrepMs + draftLockInMs;
    match.dtWindowFrom = now;
    // Both clocks pause for the shared free window; enforceDraftDeadlines
    // resumes them if the window expires with an offer still open.
    this.bankClocks(match, now);
    match.runningSince = null;
    // Any disconnect-pause is subsumed by this window: bill what it actually
    // used now, rather than leaving an orphaned pauseUntil behind a clock this
    // window owns (the alarm would later drop it as stale, billing nothing).
    if (match.pauseUntil != null) {
      const away = awaySeat(match);
      if (away) chargePauseBudget(match, away, now);
      else clearPause(match);
    }
    this.syncOfferSeats(match, game);
    // House seats resolve their opener inside the window: re-arm with the
    // game in hand so the offer branch schedules a draft think instead of
    // the move timer an earlier armBotAction(match, null) may have set.
    if (match.bots) {
      match.botActAt = null;
      this.armBotAction(match, game, now);
    }
  }

  /** First-move grace this seat has left, in ms. A per-seat budget, so paths
   * that re-anchor runningSince cannot hand it back (see graceUsedMs). */
  private graceLeftMs(match: StoredMatch, color: Color): number {
    if (this.movesByColor(match, color) > 0) return 0;
    return Math.max(0, firstMoveGraceMs - (match.graceUsedMs?.[color] ?? 0));
  }

  /** True while a draft free lock-in window is actually open right now. */
  private draftWindowHolds(match: StoredMatch, now: number): boolean {
    return (
      !!match.draft &&
      !match.diff &&
      match.dtDeadline != null &&
      now < match.dtDeadline &&
      !!(match.offerSeats?.w || match.offerSeats?.b)
    );
  }

  /** Milliseconds of [runningSince, now] that fell inside a draft free window
   * and so must never be billed — including a window that has since closed.
   * Without this the backstop below only DEFERRED the charge: runningSince was
   * left untouched, so the instant the window expired the very next read billed
   * the whole window in one jump (an instant flag in a 1+0 game). */
  private draftWindowMs(match: StoredMatch, now: number): number {
    if (!match.draft || match.diff) return 0;
    if (match.runningSince === null) return 0;
    if (match.dtWindowFrom == null || match.dtDeadline == null) return 0;
    const from = Math.max(match.runningSince, match.dtWindowFrom);
    const to = Math.min(now, match.dtDeadline);
    return to > from ? to - from : 0;
  }

  private currentClocks(match: StoredMatch, now = Date.now()): Record<Color, number> {
    const clocks = { ...match.clocks };
    if (!match.setup.timeSec || match.result || !match.startedAt || match.runningSince === null) return clocks;
    // Draft free lock-in window: BOTH clocks pause for the shared window,
    // opening and recurring rounds alike (the single, authoritative clock rule
    // for drafts). The correct roll/open paths already null runningSince so the
    // guard above catches them; this is the belt-and-braces backstop for any
    // start or reconnect path that failed to pause (see openStartDraftWindow) —
    // it makes an opening draft physically unable to burn clock, matching what
    // recurring rounds already do.
    if (this.draftWindowHolds(match, now)) return clocks;
    const active = this.chargedColor(match);
    // Bill wall time, minus any of it that fell inside a draft window (even a
    // closed one) and minus whatever first-move grace the seat still has.
    let elapsed = now - match.runningSince - this.draftWindowMs(match, now);
    elapsed = Math.max(0, elapsed - this.graceLeftMs(match, active));
    clocks[active] = Math.max(0, clocks[active] - elapsed);
    return clocks;
  }

  /**
   * Bank the running clock into match.clocks and consume whatever first-move
   * grace the active seat actually used in that interval.
   *
   * EVERY path that re-anchors or clears runningSince must bank through here.
   * That is the whole fix for the grace exploit: the allowance is a budget held
   * on the match, and it is spent exactly once no matter how many times the
   * clock is re-anchored (reconnect, draft settle, takeback, courtesy time).
   */
  private bankClocks(match: StoredMatch, now = Date.now()): Record<Color, number> {
    const banked = this.currentClocks(match, now);
    // Compute the spend against the pre-bank state, then store.
    if (
      match.setup.timeSec &&
      !match.result &&
      match.startedAt &&
      match.runningSince !== null &&
      !this.draftWindowHolds(match, now)
    ) {
      const active = this.chargedColor(match);
      const left = this.graceLeftMs(match, active);
      if (left > 0) {
        const billable = Math.max(0, now - match.runningSince - this.draftWindowMs(match, now));
        const used = Math.min(left, billable);
        if (used > 0) {
          match.graceUsedMs = {
            ...match.graceUsedMs,
            [active]: (match.graceUsedMs?.[active] ?? 0) + used,
          };
        }
      }
    }
    match.clocks = banked;
    return banked;
  }

  private async finishOnFlag(match: StoredMatch, now = Date.now(), schedule = true): Promise<boolean> {
    if (!match.startedAt || match.result || !match.setup.timeSec) return false;
    const clocks = this.currentClocks(match, now);
    const active = this.chargedColor(match);
    if (clocks[active] > 0) return false;

    // A flag during a Chess Diff loses the DIFF, never the match: the other
    // side takes the mythic, the paused game (and its stashed clocks) resumes.
    if (match.diff) {
      await this.flagChessDiff(match, active, now, schedule);
      return false;
    }

    match.clocks = clocks;
    match.runningSince = null;
    match.result = {
      winner: active === "w" ? "b" : "w",
      reason: active === "w" ? "white ran out of time" : "black ran out of time",
    };
    match.completedAt = now;
    await this.endMatch(match, schedule);
    return true;
  }

  // A player ran out the Chess Diff's 1+0 clock: decide the diff against them
  // in the engine, record it as a `diffFlag` draft action (a server-time event
  // the move stream cannot carry — every rebuild and every replica replays the
  // recorded action, so the record stays deterministic), restore the paused
  // game's clocks, and tell every client. The match itself continues.
  private async flagChessDiff(match: StoredMatch, flagged: Color, now: number, schedule = true) {
    const game = await this.gameForPlay(match);
    if (!game) return; // gameForPlay already ended an unreplayable match
    if (game.buffs?.diff) {
      match.draftActions = [
        ...(match.draftActions ?? []),
        { ply: match.moves.length, color: flagged, a: "diffFlag" },
      ];
      resolveDiffFlag(game, flagged);
      match.turnColor = game.board.turn;
    }
    // Restore the paused game's clocks (also reconciles a skewed match.diff
    // if the engine had no diff running).
    this.applyDiffTransitions(match, game, now);
    this.armBotAction(match, game, now);
    this.maybeCheckpoint(match, game);
    // Resolving a Chess Diff flag mutates the board (pieces restored / removed):
    // force a fresh public snapshot alongside the seq bump.
    this.bumpPublicSnapshot(match, game, { force: true });
    await this.saveMatch(match, schedule);
    // Replicas replay the flag as a draft action; the clock frame carries the
    // restored clocks and the draft state re-syncs the restored effects.
    this.broadcast(match, "dtDiffFlag", { color: flagged });
    this.sendWatchers(match, "dtDiffFlag", { color: flagged }, "draftDiff");
    const clocks = this.currentClocks(match, now);
    const clockFrame = { wc: Math.round(clocks.w), bc: Math.round(clocks.b) };
    this.broadcast(match, "n", clockFrame);
    this.sendWatchers(match, "n", clockFrame, "clock");
    this.sendDraftState(match, game);
    this.sendWatcherDraftState(match, game);
  }

  // Drain the buff system's pending clock adjustments (Time Thief, Deadline,
  // Overtime Whistle...) and apply them authoritatively to the match clocks, so
  // both clients stay in sync through the normal clock frames. Deltas land on
  // the BANKED clock values, which leaves runningSince/elapsed untouched, while
  // every removal is floored against each color's CURRENT clock so a running
  // clock is respected and no clock is ever pushed below clockFxFloorMs (a card
  // can squeeze the opponent but never instantly flag them). A steal removes
  // from the opponent and gives the exact amount removed to the caster. The
  // request list is transient engine state, so it is cleared here whether or not
  // the match is timed; in an untimed game the requests simply resolve to no-ops.
  // Returns true when any clock changed. Only ever called on the live apply path
  // (never during a rebuild), so historical requests are never re-applied.
  private applyClockFx(match: StoredMatch, game: NerfGame, now = Date.now()): boolean {
    const bs = game.buffs;
    const reqs = bs?.clockFx;
    if (bs) bs.clockFx = undefined;
    if (!reqs || reqs.length === 0 || !match.setup.timeSec) return false;
    const cur = this.currentClocks(match, now);
    let changed = false;
    const give = (color: Color, ms: number) => {
      if (ms <= 0) return;
      match.clocks[color] += ms;
      cur[color] += ms;
      changed = true;
    };
    const take = (color: Color, ms: number): number => {
      const room = Math.max(0, cur[color] - clockFxFloorMs);
      const taken = Math.min(Math.max(0, ms), room);
      if (taken <= 0) return 0;
      match.clocks[color] -= taken;
      cur[color] -= taken;
      changed = true;
      return taken;
    };
    for (const req of reqs) {
      const caster = req.caster;
      const opp: Color = caster === "w" ? "b" : "w";
      if (req.addSelfSec) give(caster, Math.round(req.addSelfSec * 1000));
      if (req.subOppSec) take(opp, Math.round(req.subOppSec * 1000));
      if (req.stealFractionOfOpp || req.stealFlatSec) {
        let want = 0;
        if (req.stealFractionOfOpp) want = Math.max(want, cur[opp] * req.stealFractionOfOpp);
        if (req.stealFlatSec) want = Math.max(want, req.stealFlatSec * 1000);
        if (req.stealCapSec != null) want = Math.min(want, req.stealCapSec * 1000);
        give(caster, take(opp, Math.round(want)));
      }
    }
    return changed;
  }

  // Reconcile the match record with the engine's Chess Diff state after any
  // action that advanced the game. The engine flips bs.diff on/off entirely
  // inside its deterministic replay; the match record mirrors it so flag
  // checks never need a replay, and (in timed games) the clocks swap: the
  // paused game's banked clocks are stashed and both sides get the diff's
  // 1+0 minute, then swap back when the diff is decided. Banks the live
  // clocks itself (idempotent if the caller already did) and restarts the
  // charge from `now`, so no pre-diff elapsed time bleeds into the diff and
  // no diff time bleeds back out. Returns true when the clocks changed.
  private applyDiffTransitions(match: StoredMatch, game: NerfGame, now = Date.now()): boolean {
    const engineDiff = !!game.buffs?.diff;
    if (engineDiff && !match.diff) {
      this.bankClocks(match, now);
      match.diff = { savedClocks: { ...match.clocks } };
      if (match.runningSince !== null) match.runningSince = now;
      if (match.setup.timeSec) {
        match.clocks = { w: chessDiffClockMs, b: chessDiffClockMs };
        return true;
      }
      return false;
    }
    if (!engineDiff && match.diff) {
      const saved = match.diff.savedClocks;
      match.diff = null;
      if (match.runningSince !== null) match.runningSince = now;
      if (match.setup.timeSec) {
        match.clocks = { ...saved };
        return true;
      }
    }
    return false;
  }

  // Final-board facts for achievement evaluation: material per side (kings
  // excluded) and the highest-tier card each side drafted. Computed from the
  // replayed end state, best-effort: a replay hiccup just yields nothing, which
  // only means the material/draft achievements do not fire for this game.
  private achievementExtras(match: StoredMatch): AchievementExtras {
    try {
      const game = match.startedAt ? this.gameFromMatch(match) : null;
      if (!game) return {};
      const material: Record<Color, number> = { w: 0, b: 0 };
      for (const piece of game.board.pieces) {
        if (piece && piece.type !== "k") material[piece.color] += PIECE_VALUE[piece.type];
      }
      const maxBuffTier: Record<Color, number> = { w: 0, b: 0 };
      if (game.buffs) {
        for (const color of ["w", "b"] as Color[]) {
          for (const b of game.buffs.players[color].buffs) {
            const tier = b.tier as number;
            if (tier > maxBuffTier[color]) maxBuffTier[color] = tier;
          }
        }
      }
      return { material, maxBuffTier };
    } catch {
      return {};
    }
  }

  // Single exit point for a finished match: persist it to D1 (updating both
  // ratings when the game was rated), then notify players and spectators.
  private async endMatch(match: StoredMatch, schedule = true) {
    if (!match.result) return;
    if (!match.completedAt) match.completedAt = Date.now();

    let ratings: { w: RatingChange | null; b: RatingChange | null } | null = null;
    // Bot-vs-bot games are never recorded ANYWHERE (owner rule): no games row
    // (D1 or Postgres), no recorded_games claim, no rating movement, no
    // achievement pass. Only games with at least one human seat archive.
    if (!match.recorded && match.startedAt && !this.isBotOnlyMatch(match)) {
      match.recorded = true;
      // Persist the result (and the recorded claim) BEFORE the D1/PG write
      // below. That write is a subrequest, so it does not hold the DO input
      // gate: a frame arriving mid-write (a move, a draw accept) loads the
      // match from storage and must already see match.result there — without
      // this save, such a frame could be accepted into (and saved over) a game
      // that has already ended, resurrecting it as live.
      await this.saveMatch(match, schedule);
      const db = await this.db();
      if (db) {
        try {
          const recorded = await recordFinishedGame(db, {
            id: match.id,
            whiteUserId: match.users?.w?.id ?? null,
            blackUserId: match.users?.b?.id ?? null,
            whiteName: match.users?.w?.name ?? "Anonymous",
            blackName: match.users?.b?.name ?? "Anonymous",
            whiteNerfId: match.setup.whiteNerfId,
            blackNerfId: match.setup.blackNerfId,
            seed: match.setup.seed,
            timeSec: match.setup.timeSec,
            incrementSec: match.setup.incrementSec,
            moves: match.moves,
            winner: match.result.winner,
            reason: match.result.reason,
            rated: !!match.rated,
            ...(match.abortedBy ? { abortedBy: match.abortedBy } : {}),
            ...(match.draft ? { ruleset: "draft" } : {}),
            // Mode games count toward (and, when rated, move) the per-mode
            // rating bucket instead of a speed bucket.
            ...(match.draft && match.mode ? { ratingCategory: match.mode } : {}),
            // Full draft record so the game replays from the archive alone.
            ...(match.draft ? { draftRecord: draftRecordFromMatch(match) } : {}),
            // Engine-version provenance for every game (absent stamp = v1).
            replayVersion: match.replayVersion ?? 1,
            startedAt: match.startedAt,
            completedAt: match.completedAt,
          }, this.env.HYPERDRIVE?.connectionString, this.achievementExtras(match));
          if (recorded.white || recorded.black) {
            ratings = { w: recorded.white, b: recorded.black };
          }
        } catch (err) {
          console.error("failed to record game", match.id, err);
          // Drop the claim so a later end-path replay can retry the record:
          // the recorded_games ledger makes a retry idempotent (rating deltas
          // apply at most once), whereas keeping recorded=true here would make
          // this game permanently unrecorded after one transient D1/PG blip.
          match.recorded = false;
        }
      }
    }
    await this.saveMatch(match, schedule);

    const clocks = this.currentClocks(match);
    // Draft games also close with the public draft record: each side's held
    // buffs (public all game anyway, repeated here for post-game screens).
    let draftBuffs: Record<Color, { id: string; tier: number; spent?: boolean; nullified?: boolean }[]> | null = null;
    // The held-buff reveal (and the final public snapshot below) need a full
    // replay from ply 0 — worth it for any game a human played or is watching,
    // pure waste for an unwatched filler game (its end frame goes to nobody).
    if (!this.isBotOnlyMatch(match) || this.watcherCount(match.id) > 0) {
      try {
        const game = this.gameFromMatch(match);
        if (game?.buffs) {
          const held = (color: Color) =>
            game.buffs!.players[color].buffs.map((b) => ({
              id: b.id,
              tier: b.tier as number,
              ...(b.spent ? { spent: true } : {}),
              ...(b.nullified ? { nullified: true } : {}),
            }));
          draftBuffs = { w: held("w"), b: held("b") };
        }
        // Capture the final PUBLIC snapshot at result-set time (maybeCheckpoint
        // skips post-result), so a just-ended game still ships a correct final
        // board rather than the last mid-game one. Persisted in its own save.
        if (game) {
          this.bumpPublicSnapshot(match, game, { force: true });
          await this.saveMatch(match, schedule);
        }
      } catch {
        // The end frame (and result save above) must go out even if the replay
        // hiccups; a missing final pubSnap degrades to build-on-demand at watch.
      }
    }
    // Both secret rules become public at game end — players and spectators
    // all receive them with the result.
    const payload = {
      result: match.result,
      wc: Math.round(clocks.w),
      bc: Math.round(clocks.b),
      nerfs: { w: match.setup.whiteNerfId, b: match.setup.blackNerfId },
      ...(ratings ? { ratings } : {}),
      ...(draftBuffs ? { draftBuffs } : {}),
    };
    this.broadcast(match, "end", payload);
    this.sendWatchers(match, "end", payload, "end");
  }

  private async createMatch(ws: WebSocket, data: unknown) {
    const session = this.session(ws);
    if (session.matchId) return error(ws, "already_joined", "This connection already belongs to a game.");
    if (await this.abortTimedOut(ws, session.userId)) return;

    const requested = (data || {}) as { timeSec?: unknown; incrementSec?: unknown; draft?: unknown; mode?: unknown; picksVisible?: unknown; invite?: unknown; stacked?: unknown; rated?: unknown };
    const timeSec = Number.isInteger(requested.timeSec) ? Number(requested.timeSec) : 600;
    const incrementSec = Number.isInteger(requested.incrementSec) ? Number(requested.incrementSec) : 0;
    if (timeSec < 0 || timeSec > 7200 || incrementSec < 0 || incrementSec > 60) {
      return error(ws, "invalid_clock", "Unsupported time control.");
    }
    // Custom challenges may opt into a rated game. Rating still only moves when
    // both seats belong to accounts (attachSession fills match.users for signed
    // -in seats, and recordFinishedGame no-ops the rating when either side is
    // anonymous), so a rated flag on an anonymous game degrades to casual on
    // its own. The category is the same bucket the queue uses (mode for Draft,
    // else time control), so a rated custom game moves the normal rating.
    const rated = requested.rated === true;
    // Optional Draft ruleset for friend games.
    const draft = requested.draft === true;
    // The game's section: "nerf" or "buff". Older clients send neither and
    // get the legacy merged rules.
    const mode: DraftMode | undefined =
      draft && (requested.mode === "nerf" || requested.mode === "buff") ? requested.mode : undefined;
    // Draft picks are public in every draft game: both seats see each other's
    // offers and picks as they happen (owner call: "the opponent's draft
    // should not be hidden"). The flag stays on the match record because the
    // masking machinery keys off it, but it can no longer be turned off.
    const picksVisible = draft;
    void requested.picksVisible;
    // "Surprise / Stacked draft" preset: the joining friend drafts strong,
    // high-tier cards. Casual only, and only meaningful in a draft game.
    const stacked = draft && requested.stacked === true;
    // Direct challenge: reserve the black seat for the named player. Only a
    // signed-in host can address a challenge (the API notification requires
    // an account anyway).
    const invite =
      session.userId && typeof requested.invite === "string" ? requested.invite.trim().slice(0, 30) : "";

    const id = await this.newCode();
    // Moderator card overrides: disabled nerfs leave the dealt pair, and the
    // draft-pool slice is frozen onto the match record (see cardOverrides).
    const cardSnap = await this.cardOverridesSnapshot();
    const cardOverrides = draft ? this.draftPoolStamp(cardSnap) : undefined;
    const match: StoredMatch = {
      id,
      setup: {
        // Buff mode has no handicaps: both seats carry the unrestricted
        // "none" rule instead of dealt nerfs.
        ...(mode === "buff"
          ? { whiteNerfId: UNRESTRICTED_NERF.id, blackNerfId: UNRESTRICTED_NERF.id }
          : pickNerfIds(cardSnap.nerfOff)),
        seed: makeSeed(),
        timeSec,
        incrementSec,
      },
      tokens: { w: newToken(), b: newToken() },
      disconnectedAt: {},
      opponentGoneNotified: {},
      moves: [],
      result: null,
      clocks: { w: timeSec * 1000, b: timeSec * 1000 },
      runningSince: null,
      drawOfferBy: null,
      createdAt: Date.now(),
      startedAt: null,
      completedAt: null,
      replayVersion: REPLAY_VERSION,
      ...(rated ? { rated: true } : {}),
      ...(draft
        ? {
            draft: true,
            ...(mode ? { mode } : {}),
            picksVisible,
            ...(stacked ? { stacked: true } : {}),
            cadence: mode === "nerf" ? NERF_MODE_CADENCE : DEFAULT_CADENCE,
            draftSeed: makeSeed(),
            ...(cardOverrides ? { cardOverrides } : {}),
            draftActions: [],
          }
        : {}),
      ...(invite ? { invitedUsername: invite } : {}),
    };

    await this.attachSession(ws, match, "w");
    await this.saveMatch(match);
    send(ws, "created", { id, color: "w", token: match.tokens.w });
  }

  private async joinMatch(ws: WebSocket, data: unknown) {
    const session = this.session(ws);
    if (session.matchId) return error(ws, "already_joined", "This connection already belongs to a game.");
    if (await this.abortTimedOut(ws, session.userId)) return;

    const id = String((data as { id?: unknown } | undefined)?.id || "").trim().toUpperCase();
    const match = await this.loadMatch(id);
    // A dealt nerf draft means both seats are claimed even though the game
    // has not started, so the code is no longer joinable.
    if (!match || match.startedAt || match.nerfOptions || this.connectedSession(id, "b")) {
      return error(ws, "not_found", "That code is not accepting a player.");
    }
    // Direct challenges are reserved: only the invited account may take the
    // black seat, so a lobby stranger can never race the invitee to it.
    if (
      match.invitedUsername &&
      match.invitedUsername.toLowerCase() !== (session.username ?? "").toLowerCase()
    ) {
      return error(ws, "invite_only", "This game is reserved for the invited player.");
    }
    // The host is gone (navigated away or closed the tab): joining would
    // start a game against an empty seat. Tell the joiner plainly instead.
    if (!this.connectedSession(id, "w")) {
      return error(ws, "host_gone", "The player who created this game has left.");
    }

    await this.attachSession(ws, match, "b");
    // The host's seat rating was snapshotted when the challenge was created,
    // possibly long before this join (their rating may have moved in other
    // games since); bring it current before the start frames go out. The
    // joiner's own seat was read fresh in attachSession just above.
    await this.refreshSeatRatings(match, ["w"]);
    // Draft games open with the nerf draft instead of starting outright.
    // Buff mode has no nerfs, so it starts like a classic game.
    if (match.draft && match.mode !== "buff") return this.beginNerfDraft(match);
    match.startedAt = Date.now();
    match.runningSince = match.startedAt;
    // Buff mode: the opening pick's free lock-in window opens with the game.
    await this.openStartDraftWindow(match, match.startedAt);
    await this.saveMatch(match);
    this.sendStart(match, "w");
    this.sendStart(match, "b");
  }

  private async reconnectMatch(ws: WebSocket, data: unknown) {
    const session = this.session(ws);
    if (session.matchId) return error(ws, "already_joined", "This connection already belongs to a game.");

    const request = (data || {}) as { id?: unknown; color?: unknown; token?: unknown };
    const id = String(request.id || "").trim().toUpperCase();
    const color = isColor(request.color) ? request.color : null;
    const token = typeof request.token === "string" ? request.token : "";
    const match = await this.loadMatch(id);
    if (!match || !color || match.tokens[color] !== token) {
      return error(ws, "reconnect_failed", "Could not resume that game.");
    }

    await this.attachSession(ws, match, color);
    await this.saveMatch(match);
    if (!match.startedAt) {
      // Mid nerf draft: resume it. The start payload restores this seat's
      // options and pick state (a seat that already picked sees the waiting
      // state again).
      if (match.nerfOptions) return this.sendStart(match, color);
      // Matchmade and rematch games begin the moment both paired players
      // arrive at the game URL; friend games wait in the lobby for a join.
      // A house-player seat counts as arrived (it has no socket).
      if ((match.rated || match.autoStart) && this.seatReady(match, "w") && this.seatReady(match, "b")) {
        // Buff mode skips the opening nerf draft entirely.
        if (match.draft && match.mode !== "buff") return this.beginNerfDraft(match);
        match.startedAt = Date.now();
        match.runningSince = match.startedAt;
        this.armBotAction(match, null, match.startedAt);
        // Buff mode: the opening pick's free lock-in window opens with the game.
        await this.openStartDraftWindow(match, match.startedAt);
        await this.saveMatch(match);
        this.sendStart(match, "w");
        this.sendStart(match, "b");
        return;
      }
      return send(ws, "created", { id, color, token: match.tokens[color] });
    }
    // A live draft game whose replay went stale across a deploy ends now,
    // through gameForPlay's graceful draw, so the returning player gets the
    // end frame instead of a board that can never accept a move. If the rebuild
    // THROWS (a special card that corrupts its own replay), never leave the
    // returning player stuck on "connecting": end the game as an interrupted,
    // unrated draw and deliver the end frame instead. Logged so the offending
    // card can be found and fixed at the source.
    if (match.draft && !match.result) {
      try {
        await this.gameForPlay(match);
      } catch (err) {
        console.error("reconnect replay threw, ending game", match.id, "moves=", match.moves.length, "draftActions=", JSON.stringify(match.draftActions ?? []), err);
        if (!match.result) {
          this.bankClocks(match);
          match.runningSince = null;
          match.result = { winner: "draw", reason: "game interrupted" };
          match.completedAt = Date.now();
          match.rated = false;
          try {
            await this.endMatch(match);
          } catch (endErr) {
            console.error("reconnect end after replay throw failed", match.id, endErr);
          }
        }
        return;
      }
    }
    // House game: the clock was paused when this human seat disconnected;
    // resume it now that they are back, unless a draft offer's lock-in window
    // is still holding it paused. Re-arm the bot so it resumes acting on its
    // turn (its timer may have been left armed while play was paused).
    if (
      match.bots &&
      !match.bots[color] &&
      match.startedAt &&
      !match.result &&
      match.runningSince === null
    ) {
      const offerHolding = !!match.dtDeadline && Date.now() < match.dtDeadline;
      if (!offerHolding) {
        const now = Date.now();
        chargePauseBudget(match, color, now);
        match.runningSince = now;
        this.armBotAction(match, null, now);
        await this.saveMatch(match);
      }
    }
    this.sendStart(match, color);
    // A rematch was created while this seat was away (page refresh or dropped
    // socket mid-rematch): re-deliver the seat in the new game so the player
    // reclaims it instead of arriving at the rematch as a spectator. Only
    // while the rematch is still unfinished, so revisiting an old game page
    // never bounces into an already-decided one.
    if (match.rematchedTo && match.rematchedTo !== REMATCH_PENDING) {
      const rematch = await this.loadMatch(match.rematchedTo);
      if (rematch && !rematch.result) {
        const newColor: Color = color === "w" ? "b" : "w";
        send(ws, "rematched", { id: rematch.id, color: newColor, token: rematch.tokens[newColor] });
      }
    }
  }

  private async playClientMove(ws: WebSocket, data: unknown) {
    const session = this.session(ws);
    const match = session.matchId ? await this.loadMatch(session.matchId) : null;
    if (!match || !session.color) return error(ws, "no_game", "Join a game before sending moves.");
    if (await this.finishOnFlag(match)) return;
    if (match.result) return error(ws, "game_over", "This game is over.");
    // Draft games: no moves while the opening nerf draft is unresolved.
    if (match.draft && match.nerfOptions && !match.startedAt) {
      return error(ws, "nerf_pending", "Pick your nerf before the game starts.");
    }

    const game = await this.gameForPlay(match);
    // gameForPlay already ended a match whose replay went stale (the end
    // frame is on its way to this seat); only a genuinely unjoined game
    // still warrants the error.
    if (!game) return match.result ? undefined : error(ws, "no_game", "Join a game before sending moves.");
    if (game.board.turn !== session.color) return error(ws, "not_your_turn", "It is not your turn.");
    // Draft games: a pending buff offer blocks the seat's moves, mirroring
    // how the client blocks the board until the draft is resolved.
    if (match.draft && game.buffs?.players[session.color].offer) {
      return error(ws, "draft_pending", "Resolve your buff draft before moving.");
    }
    // The OPPONENT's open draft blocks moves too: their pick can mutate the
    // board mid-flight, and the waiting player is not being charged for this
    // time (see chargedColor), so they must not get free thinking moves
    // either. The client mirrors this by banking premoves until the pick
    // lands.
    if (match.draft && game.buffs?.players[session.color === "w" ? "b" : "w"].offer) {
      return error(ws, "opp_draft_pending", "Wait for your opponent to finish drafting.");
    }

    const request = (data || {}) as { u?: unknown; ply?: unknown };
    const uci = typeof request.u === "string" ? request.u.toLowerCase() : "";
    if (Number.isInteger(request.ply) && Number(request.ply) !== match.moves.length) {
      return error(ws, "stale_ply", "Your board is out of date.");
    }
    const move = moveByUci(game, uci);
    if (!move) return error(ws, "illegal_move", "That move is not legal in the current position.");

    await this.commitMove(match, game, session.color, move, uci);
  }

  // Apply an accepted move and everything that follows it: clocks, pending
  // offer declines, draft offer rolls and deadlines, broadcasts, and the end
  // flow. Shared verbatim by human moves (playClientMove) and house-player
  // moves (playHouseAction), so a house game's record and wire frames are
  // identical to a human game's.
  private async commitMove(match: StoredMatch, game: NerfGame, mover: Color, move: Move, uci: string) {
    const now = Date.now();
    this.bankClocks(match, now);
    if (match.drawOfferBy && match.drawOfferBy !== mover) {
      match.drawOfferBy = null;
      this.broadcast(match, "drawDeclined", { color: mover });
    }
    // Moving past an opponent's takeback request declines it.
    if (match.takebackOfferBy && match.takebackOfferBy !== mover) {
      match.takebackOfferBy = null;
      this.broadcast(match, "takebackDeclined", { color: mover });
    }
    // Which seats already had a pending offer: playMove mutates the game, so
    // newly rolled offers are detected against this pre-move snapshot.
    const offersBefore =
      match.draft && game.buffs
        ? { w: !!game.buffs.players.w.offer, b: !!game.buffs.players.b.offer }
        : null;
    // A move granted by a hidden passive buff proves the mover holds that
    // card: reveal it to the table BEFORE the move goes out, so replicas can
    // regenerate the granted move when they replay the frame. The dtState is
    // computed on the pre-move game so replicas tick charges exactly once.
    if (match.draft && game.buffs && !match.picksVisible && this.markViaRevealed(game, move)) {
      this.sendDraftState(match, game);
      this.sendWatcherDraftState(match, game);
    }
    // Snapshot the pre-move draft state (plain serializable data). If a
    // hidden passive's hook fires inside playMove (a capture detonation, a
    // triggered summon...), its identity plus PRE-move card state must reach
    // every replica BEFORE the move frame, so the replica's own playMove
    // replays the same board mutation. dtState never carries the board, so a
    // hook a replica skips is a permanent desync; this is the onMovePlayed
    // analogue of the via-reveal above.
    const preBuffs: BuffMatchState | null =
      match.draft && game.buffs ? (JSON.parse(JSON.stringify(game.buffs)) as BuffMatchState) : null;
    // Live moves roll offers under the same frozen overrides snapshot the
    // rebuild path uses; cleared right after so nothing else inherits it.
    setDraftPoolOverrides(match.draft ? match.cardOverrides ?? null : null);
    let nextGame: NerfGame;
    try {
      nextGame = playMove(game, move);
    } finally {
      setDraftPoolOverrides(null);
    }
    if (preBuffs && this.revealFiredHooks(nextGame, preBuffs)) {
      const preGame = { buffs: preBuffs } as unknown as NerfGame;
      this.sendDraftState(match, preGame);
      this.sendWatcherDraftState(match, preGame);
    }
    this.countMove(match, mover);
    match.moves.push(uci);
    // Draft games: extra moves and skips can leave the turn off parity.
    if (match.draft) match.turnColor = nextGame.board.turn;
    // No increment while a Chess Diff runs: the sub-game is strictly 1+0
    // (this also covers the move that decides it — the paused game's restored
    // clocks resume untouched below).
    if (match.setup.timeSec && !match.diff) match.clocks[mover] += match.setup.incrementSec * 1000;
    const offersPending =
      match.draft && nextGame.buffs
        ? !!nextGame.buffs.players.w.offer || !!nextGame.buffs.players.b.offer
        : false;
    const rolledNow = ["w", "b"].some(
      (color) => nextGame.buffs?.players[color as Color].offer && !offersBefore?.[color as Color],
    );
    if (match.draft) {
      // The window is presentation budget + the full decision time: clients
      // reveal the countdown only once the cards are dealt and interactive,
      // so the player still receives the complete decision window after the
      // chest and deal animations.
      if (rolledNow && !nextGame.result) {
        match.dtDeadline = now + draftPrepMs + draftLockInMs;
        match.dtWindowFrom = now;
      } else if (!offersPending) {
        match.dtDeadline = null;
        match.dtWindowFrom = null;
      }
      // Keep the charged-seat mirror current: past the free window the seat
      // still holding its offer pays (see chargedColor), never the waiter.
      this.syncOfferSeats(match, nextGame);
    }
    // A pending buff offer pauses the game clock only during its free
    // lock-in window (dtDeadline). Once the window has expired the clock
    // runs on: deliberating past it costs the straggler's own time.
    if (nextGame.result || (offersPending && match.dtDeadline)) {
      match.runningSince = null;
    } else if (match.pauseUntil != null && now < match.pauseUntil) {
      // A live disconnect-pause outranks the move resume (same rule as
      // settleDraftAction): restarting the clock here would silently end the
      // absent player's protection early and orphan pauseUntil, which the
      // alarm would later sweep as stale, billing nothing. Leave the clock
      // paused; releaseExpiredPause owns the resume.
      match.runningSince = null;
    } else {
      if (match.pauseUntil != null) {
        const away = awaySeat(match);
        if (away) chargePauseBudget(match, away, now);
        else clearPause(match);
      }
      match.runningSince = now;
    }
    match.result = nextGame.result;
    if (nextGame.result) match.completedAt = now;
    // A move that decided a Chess Diff restores the paused game's clocks (the
    // move frame below then carries the restored values to every client).
    this.applyDiffTransitions(match, nextGame, now);
    // A clock-manipulation buff whose onMovePlayed hook fired this move adjusts
    // the clocks now, so the move frame below carries the updated values.
    this.applyClockFx(match, nextGame, now);
    // House seats: arm the next pending house action (a reply move, or a
    // freshly rolled offer on the house side). No-op for purely human games.
    this.armBotAction(match, nextGame, now);
    // Refresh the replay checkpoint from the just-advanced game (throttled).
    this.maybeCheckpoint(match, nextGame);
    // Advance the public revision and rebuild the spectator snapshot. Force a
    // rebuild when the game ended or a held card's hook mutated the board this
    // move, so a resyncing spectator never lands on a stale board.
    this.bumpPublicSnapshot(match, nextGame, {
      force: !!nextGame.result || !!nextGame.buffs?.lastHookMutations?.length,
    });
    await this.saveMatch(match);

    const movePayload = {
      u: uci,
      ply: match.moves.length,
      wc: Math.round(match.clocks.w),
      bc: Math.round(match.clocks.b),
      // Desync telemetry: hash of the authoritative post-move position
      // (placement, turn, castling, ep). A replica that applies this move and
      // lands on a different hash has silently diverged and should resync +
      // beacon (see src/engine/desync.ts and /api/desync).
      f: fnv1a(positionKey(nextGame.board)),
    };
    this.broadcast(match, "move", movePayload);
    this.sendWatchers(match, "move", movePayload, "move");
    if (match.draft && nextGame.buffs) {
      // The shared draft cadence rolls offers for BOTH seats on the same
      // move, so each seat whose offer appeared gets its dtOffer frame now,
      // not just the mover's. FULL TRANSPARENCY: every offer goes to BOTH
      // seats, always — pending offers are public, live (spectators read the
      // same cards from their open dtState).
      let rolledAny = false;
      for (const color of ["w", "b"] as Color[]) {
        const rolled = nextGame.buffs.players[color].offer;
        if (!rolled || offersBefore?.[color]) continue;
        rolledAny = true;
        const offerPayload = {
          color,
          cards: rolled.cards,
          index: rolled.index,
          ...(rolled.banked ? { banked: true } : {}),
          ...(match.dtDeadline ? { deadline: match.dtDeadline } : {}),
        };
        send(this.connectedSession(match.id, color), "dtOffer", offerPayload);
        send(this.connectedSession(match.id, color === "w" ? "b" : "w"), "dtOffer", offerPayload);
      }
      if (rolledAny) this.sendDraftState(match, nextGame);
    }
    if (match.result) await this.endMatch(match);
  }

  private async resignGame(ws: WebSocket) {
    const session = this.session(ws);
    const match = session.matchId ? await this.loadMatch(session.matchId) : null;
    if (!match || !session.color) return error(ws, "no_game", "Join a game before resigning.");
    if (await this.finishOnFlag(match)) return;
    if (match.result) return;

    const game = await this.gameForPlay(match);
    if (!game) return match.result ? undefined : error(ws, "no_game", "Join a game before resigning.");

    this.bankClocks(match);
    match.runningSince = null;
    match.result = resign(game, session.color).result;
    match.completedAt = Date.now();
    await this.endMatch(match);
  }

  // Abort: either player may end the game with no result (and no rating
  // movement — recordFinishedGame treats a null winner as unrated) until one
  // whole turn has been played. Repeated aborts draw a warning and then a
  // temporary matchmaking timeout; see the abort* constants.
  private async abortGame(ws: WebSocket) {
    const session = this.session(ws);
    let match = session.matchId ? await this.loadMatch(session.matchId) : null;
    if (!match || !session.color) return error(ws, "no_game", "Join a game before aborting.");
    if (await this.finishOnFlag(match)) return;
    if (match.result) return;
    if (match.moves.length >= abortMaxPlies) {
      return error(ws, "abort_too_late", "The game can no longer be aborted once both sides have moved.");
    }

    const game = await this.gameForPlay(match);
    if (!game) return match.result ? undefined : error(ws, "no_game", "Join a game before aborting.");

    // Snapshot the aborter's ring buffer BEFORE endMatch appends this game's
    // flag, so the warning/timeout decision can compare the window with and
    // without this abort. House-bot seats never abort, so only humans land here.
    const db = await this.db();
    let prevFlags = "";
    if (db && session.userId && match.startedAt) {
      try {
        const row = await db
          .prepare(`SELECT recent_aborts FROM users WHERE id = ?`)
          .bind(session.userId)
          .first<{ recent_aborts: string | null }>();
        prevFlags = row?.recent_aborts ?? "";
      } catch {}
      // That read was a subrequest, so it did not hold the DO input gate: a
      // frame landing mid-read (a move that ended the game, a flag, the other
      // seat's abort) may have finished the stored match. Re-check before
      // writing the aborted result over it.
      const fresh = await this.loadMatch(match.id);
      if (!fresh || fresh.result) return;
      match = fresh;
      if (match.moves.length >= abortMaxPlies) {
        return error(ws, "abort_too_late", "The game can no longer be aborted once both sides have moved.");
      }
    }

    this.bankClocks(match);
    match.runningSince = null;
    match.drawOfferBy = null;
    match.abortedBy = session.color;
    match.result = { winner: null, reason: "aborted" };
    match.completedAt = Date.now();
    await this.endMatch(match);

    // Warning / timeout pass. Only started games are recorded (and so only
    // they append to the ring buffer); an unstarted abort carries no penalty.
    if (db && session.userId && match.startedAt) {
      const aborts = (flags: string) =>
        flags.slice(-abortWindow).split("").filter((c) => c === "1").length;
      const before = aborts(prevFlags);
      const after = aborts(prevFlags + "1");
      if (after >= abortWarnCount) {
        if (before >= abortWarnCount) {
          // Already warned (still at the threshold) and aborted again: block
          // new games for a cooldown period.
          const until = Date.now() + abortTimeoutMs;
          try {
            await db
              .prepare(`UPDATE users SET abort_timeout_until = ? WHERE id = ?`)
              .bind(until, session.userId)
              .run();
          } catch {}
          send(ws, "abortWarning", { level: "timeout", until });
        } else {
          send(ws, "abortWarning", { level: "warning" });
        }
      }
    }
  }

  // True (and an error frame already sent) when this signed-in account is
  // inside an abort-abuse cooldown, so every new-game entry point can refuse
  // with one call. Anonymous sessions pass: they have no row to check.
  private async abortTimedOut(ws: WebSocket, userId: string | null | undefined): Promise<boolean> {
    if (!userId) return false;
    const db = await this.db();
    if (!db) return false;
    let until = 0;
    try {
      const row = await db
        .prepare(`SELECT abort_timeout_until FROM users WHERE id = ?`)
        .bind(userId)
        .first<{ abort_timeout_until: number | null }>();
      until = row?.abort_timeout_until ?? 0;
    } catch {}
    if (until <= Date.now()) return false;
    const mins = Math.max(1, Math.ceil((until - Date.now()) / 60_000));
    error(
      ws,
      "abort_timeout",
      `You've aborted too many recent games. You can start a new game in ${mins} minute${mins === 1 ? "" : "s"}.`,
    );
    return true;
  }

  // ---------------- abandonment claims ----------------

  // Once the opponent has been disconnected for 30+ seconds in a started,
  // unfinished game, the remaining player may end it as a win or a draw.
  private async claimAbandonment(ws: WebSocket, draw: boolean) {
    const session = this.session(ws);
    const match = session.matchId ? await this.loadMatch(session.matchId) : null;
    if (!match || !session.color) return error(ws, "no_game", "Join a game before claiming.");
    if (await this.finishOnFlag(match)) return;
    if (match.result) return;
    if (!match.startedAt) return error(ws, "not_started", "The game has not started yet.");

    const opponent: Color = session.color === "w" ? "b" : "w";
    const disconnectedAt = match.disconnectedAt[opponent];
    if (
      this.connectedSession(match.id, opponent) ||
      !disconnectedAt ||
      Date.now() - disconnectedAt < abandonmentClaimMs
    ) {
      return error(ws, "no_claim", "Your opponent has not been gone long enough to claim.");
    }

    this.bankClocks(match);
    match.runningSince = null;
    match.result = draw
      ? { winner: "draw", reason: "abandonment" }
      : { winner: session.color, reason: "abandonment" };
    match.completedAt = Date.now();
    await this.endMatch(match);
  }

  private async offerDraw(ws: WebSocket) {
    const session = this.session(ws);
    const match = session.matchId ? await this.loadMatch(session.matchId) : null;
    if (!match || !session.color) return error(ws, "no_game", "Join a game before offering a draw.");
    if (await this.finishOnFlag(match)) return;
    if (match.result) return;
    if (match.drawOfferBy === session.color) return error(ws, "draw_pending", "Your draw offer is already pending.");
    if (match.drawOfferBy && match.drawOfferBy !== session.color) return this.acceptDraw(ws);

    match.drawOfferBy = session.color;
    await this.saveMatch(match);
    this.broadcast(match, "drawOffer", { color: session.color });
  }

  private async acceptDraw(ws: WebSocket) {
    const session = this.session(ws);
    const match = session.matchId ? await this.loadMatch(session.matchId) : null;
    if (!match || !session.color) return error(ws, "no_game", "Join a game before accepting a draw.");
    if (await this.finishOnFlag(match)) return;
    if (match.result) return;
    if (!match.drawOfferBy || match.drawOfferBy === session.color) {
      return error(ws, "no_draw_offer", "There is no opponent draw offer to accept.");
    }

    this.bankClocks(match);
    match.runningSince = null;
    match.drawOfferBy = null;
    match.result = { winner: "draw", reason: "draw by agreement" };
    match.completedAt = Date.now();
    await this.endMatch(match);
  }

  private async declineDraw(ws: WebSocket) {
    const session = this.session(ws);
    const match = session.matchId ? await this.loadMatch(session.matchId) : null;
    if (!match || !session.color) return error(ws, "no_game", "Join a game before declining a draw.");
    if (await this.finishOnFlag(match)) return;
    if (match.result) return;
    if (!match.drawOfferBy || match.drawOfferBy === session.color) {
      return error(ws, "no_draw_offer", "There is no opponent draw offer to decline.");
    }

    match.drawOfferBy = null;
    await this.saveMatch(match);
    this.broadcast(match, "drawDeclined", { color: session.color });
  }

  // ---------------- takebacks (casual games only) ----------------

  // How many plies an accepted takeback removes: the offerer's last move,
  // plus the opponent's reply if they already answered it.
  private takebackPlies(match: StoredMatch, offerer: Color): number {
    const lastMover: Color = match.moves.length % 2 === 1 ? "w" : "b";
    return lastMover === offerer ? 1 : 2;
  }

  private async offerTakeback(ws: WebSocket) {
    const session = this.session(ws);
    const match = session.matchId ? await this.loadMatch(session.matchId) : null;
    if (!match || !session.color) return error(ws, "no_game", "Join a game before requesting a takeback.");
    if (await this.finishOnFlag(match)) return;
    if (match.result) return;
    if (match.rated) return error(ws, "takeback_rated", "Takebacks are not allowed in rated games.");
    // Draft state (rolled offers, consumed RNG, applied buffs) cannot be
    // rewound, so draft games have no takebacks.
    if (match.draft) return error(ws, "takeback_draft", "Takebacks are not available in Draft games.");
    const myMoves = session.color === "w" ? Math.ceil(match.moves.length / 2) : Math.floor(match.moves.length / 2);
    if (myMoves === 0) return error(ws, "no_moves", "You have no move to take back.");
    if (this.takebackPlies(match, session.color) > match.moves.length) {
      return error(ws, "no_moves", "You have no move to take back.");
    }
    if (match.takebackOfferBy === session.color) {
      return error(ws, "takeback_pending", "Your takeback request is already pending.");
    }
    if (match.takebackOfferBy && match.takebackOfferBy !== session.color) return this.acceptTakeback(ws);

    match.takebackOfferBy = session.color;
    await this.saveMatch(match);
    this.broadcast(match, "takebackOffer", { color: session.color });
  }

  private async acceptTakeback(ws: WebSocket) {
    const session = this.session(ws);
    const match = session.matchId ? await this.loadMatch(session.matchId) : null;
    if (!match || !session.color) return error(ws, "no_game", "Join a game before accepting a takeback.");
    if (await this.finishOnFlag(match)) return;
    if (match.result) return;
    const offerer = match.takebackOfferBy;
    if (!offerer || offerer === session.color) {
      return error(ws, "no_takeback_offer", "There is no takeback request to accept.");
    }

    const remove = this.takebackPlies(match, offerer);
    if (remove > match.moves.length) {
      match.takebackOfferBy = null;
      await this.saveMatch(match);
      return error(ws, "no_moves", "There is nothing to take back.");
    }

    const now = Date.now();
    this.bankClocks(match, now);
    match.moves = match.moves.slice(0, match.moves.length - remove);
    // The rewind drops the move list below the checkpoint; clear it so the play
    // path rebuilds a fresh one instead of falling back to full replay until the
    // game catches back up (the bounds guard keeps it correct either way).
    match.checkpoint = null;
    match.takebackOfferBy = null;
    match.runningSince = match.startedAt ? now : null;
    // A takeback rewinds the board: rebuild the snapshot from the rewound game
    // so the takeback envelope carries the exact post-rewind parity hash. The
    // revision itself is allocated by the "takeback" envelope emitted below (a
    // spectator applies it as the next in-order event) — bumping it here too
    // would leave a hole in the sequence that the client's reducer can never
    // fill, stalling every later frame until a resync. If the rewound game
    // cannot be rebuilt the frame still advances the revision on its own, so a
    // spectator sees the change and can resync.
    let rewound: NerfGame | null = null;
    try {
      rewound = this.gameFromMatch(match);
    } catch {
      rewound = null;
    }
    if (rewound) this.bumpPublicSnapshot(match, rewound, { force: true });
    await this.saveMatch(match);

    const payload = {
      by: offerer,
      moves: match.moves,
      ply: match.moves.length,
      wc: Math.round(match.clocks.w),
      bc: Math.round(match.clocks.b),
    };
    this.broadcast(match, "takeback", payload);
    this.sendWatchers(match, "takeback", payload, "takeback");
  }

  private async declineTakeback(ws: WebSocket) {
    const session = this.session(ws);
    const match = session.matchId ? await this.loadMatch(session.matchId) : null;
    if (!match || !session.color) return error(ws, "no_game", "Join a game before declining a takeback.");
    if (await this.finishOnFlag(match)) return;
    if (match.result) return;
    if (!match.takebackOfferBy || match.takebackOfferBy === session.color) {
      return error(ws, "no_takeback_offer", "There is no takeback request to decline.");
    }

    match.takebackOfferBy = null;
    await this.saveMatch(match);
    this.broadcast(match, "takebackDeclined", { color: session.color });
  }

  // ---------------- matchmaking queue ----------------

  private queueKey(mode: DraftMode, pool: string): string {
    return `queue:${mode}:${pool}`;
  }

  private async queueJoin(ws: WebSocket, data: unknown) {
    const session = this.session(ws);
    if (session.matchId) return error(ws, "already_joined", "This connection already belongs to a game.");
    if (!session.userId || !session.username) {
      return error(ws, "auth_required", "Sign in to use quick pairing.");
    }
    if (await this.abortTimedOut(ws, session.userId)) return;
    const req = (data as { pool?: unknown; mode?: unknown; target?: unknown } | undefined) ?? {};
    const poolName = String(req.pool || "3+2");
    const pool = QUEUE_POOLS[poolName];
    if (!pool) return error(ws, "bad_pool", "Unknown queue pool.");
    // Which of the two pools (Nerf or Buff) this seek enters. Older clients
    // send no mode and land in Buff, which is what the queue always ran.
    const mode: DraftMode = req.mode === "nerf" ? "nerf" : "buff";
    // Answering a specific lobby seek carries that seeker's identity. A targeted
    // join must pair ONLY with that person (or that house persona) — never a
    // random pool waiter or a random bot. Untargeted frames (the main Quick
    // Pair button) leave this null and keep pairing with whoever is first.
    const targetUserId =
      typeof (req.target as { userId?: unknown } | undefined)?.userId === "string"
        ? String((req.target as { userId: string }).userId).slice(0, 64)
        : "";
    const db = await this.db();
    if (!db) return error(ws, "server_unconfigured", "Matchmaking is unavailable right now.");

    let rating = 1500;
    let rd = 350;
    let vol = 0.06;
    let avatar: string | null = null;
    {
      // Queueing reads (and stakes) the rating bucket for this pool's mode,
      // shown beside names and updated when the game ends: queue games are
      // rated under the per-mode buckets.
      const row = await this.seatCategoryRating(db, session.userId, mode);
      if (row) {
        rating = row.rating;
        rd = row.rd;
        vol = row.vol;
        avatar = row.avatar;
      }
    }

    const key = this.queueKey(mode, poolName);
    let entries = (await this.ctx.storage.get<QueueEntry[]>(key)) ?? [];
    // Drop dead sockets and any previous entry by this same account.
    entries = entries.filter(
      (entry) => entry.userId !== session.userId && this.socketForAttachment(entry.attachmentId),
    );

    const me: SeatUser = { id: session.userId, name: session.username, rating, rd, vol, avatar };

    // Targeted join: the player tapped a specific seek row in the lobby, so
    // they mean to play THAT person. Pair only with them; a stale seek must
    // report "no longer waiting" rather than fall through to a random pool
    // waiter or (via the house pickup) a random bot.
    if (targetUserId) {
      if (targetUserId === session.userId) {
        return error(ws, "seek_gone", "That player is no longer waiting.");
      }
      // A house-persona seek pairs immediately with that exact bot. A human
      // explicitly asked for THIS game, so honour it past the background cap.
      if (isHouseUserId(targetUserId)) {
        // House players are paused: their seeks are cleared, but a stale client
        // may still try to accept one. Treat it as gone.
        if (!(await this.houseEnabled())) return error(ws, "seek_gone", "That player is no longer waiting.");
        const persona = housePersona(targetUserId);
        if (!persona) return error(ws, "seek_gone", "That player is no longer waiting.");
        // One game per bot: a persona already seated in a live game must never be
        // paired into a second. A ~5-7s-stale lobby row (the seek was cleared when
        // the persona got pulled into a house game) or two humans double-tapping
        // the same row would otherwise double-seat it — the reported "one account
        // playing two games at once". Reject as gone, mirroring the busy guard
        // playHouseBot uses; the human can quick-pair or tap another row.
        const houseBusy = new Set<string>();
        for (const m of await this.loadLiveMatches()) {
          if (m.result) continue;
          for (const c of ["w", "b"] as Color[]) {
            const bid = m.bots?.[c];
            if (bid) houseBusy.add(bid);
          }
        }
        if (houseBusy.has(persona.userId)) {
          return error(ws, "seek_gone", "That player is no longer waiting.");
        }
        const meEntry: QueueEntry = {
          attachmentId: session.id,
          userId: session.userId,
          username: session.username,
          rating,
          rd,
          vol,
          avatar,
          at: Date.now(),
        };
        await this.pairHumanWithHouse(meEntry, ws, poolName, mode, persona, db);
        // Retire that persona's advertised seek so it stops showing as waiting.
        try {
          const seeks = (await this.ctx.storage.get<HouseSeekEntry[]>(houseSeeksKey)) ?? [];
          const remaining = seeks.filter((seek) => seek.userId !== persona.userId);
          if (remaining.length !== seeks.length) await this.ctx.storage.put(houseSeeksKey, remaining);
        } catch {}
        return;
      }
      // A human seek: match by account id (never by name or `at`, so a re-queue
      // is still the same person) and only if their socket is still live.
      const idx = entries.findIndex(
        (entry) => entry.userId === targetUserId && this.socketForAttachment(entry.attachmentId),
      );
      if (idx < 0) return error(ws, "seek_gone", "That player is no longer waiting.");
      const opponent = entries.splice(idx, 1)[0];
      await this.ctx.storage.put(key, entries);
      return this.createQueueMatch(ws, me, opponent, poolName, mode);
    }

    const opponent = entries.shift();
    if (!opponent) {
      entries.push({
        attachmentId: session.id,
        userId: session.userId,
        username: session.username,
        rating,
        rd,
        vol,
        avatar,
        at: Date.now(),
      });
      await this.ctx.storage.put(key, entries);
      // Nobody was waiting: make sure the alarm fires soon so a house player
      // can pick this seek up if no human arrives (houseTick pairs a lone
      // human with a persona after ~4.5s; a human opponent queueing in the
      // meantime still pairs instantly through this method).
      try {
        await this.armAlarmBy(Date.now() + houseHumanPickupMs);
      } catch {}
      return send(ws, "queued", { pool: poolName, mode });
    }
    await this.ctx.storage.put(key, entries);
    return this.createQueueMatch(ws, me, opponent, poolName, mode);
  }

  // Create and store a rated queue match between the caller (already seated as
  // `me`) and a waiting `opponent`, then send both the `paired` frame. Shared
  // verbatim by quick pairing (pair-with-anyone) and a targeted seek join, so
  // both produce identical rated games.
  private async createQueueMatch(
    ws: WebSocket,
    me: SeatUser,
    opponent: QueueEntry,
    poolName: string,
    mode: DraftMode,
  ) {
    const pool = QUEUE_POOLS[poolName];
    const opponentWs = this.socketForAttachment(opponent.attachmentId)!;
    const meWhite = randomInt(2) === 0;
    const them: SeatUser = {
      id: opponent.userId,
      name: opponent.username,
      rating: opponent.rating,
      rd: opponent.rd,
      vol: opponent.vol,
      avatar: opponent.avatar ?? null,
    };
    const id = await this.newCode(8);
    const cardSnap = await this.cardOverridesSnapshot();
    const cardOverrides = this.draftPoolStamp(cardSnap);
    const match: StoredMatch = {
      id,
      setup: {
        // Buff mode has no nerfs, so no dealt rules either. Nerf mode deals
        // an initial pair the same way friend games do; the opening nerf
        // draft replaces both ids once the players pick.
        ...(mode === "buff"
          ? { whiteNerfId: UNRESTRICTED_NERF.id, blackNerfId: UNRESTRICTED_NERF.id }
          : pickNerfIds(cardSnap.nerfOff)),
        seed: makeSeed(),
        timeSec: pool.timeSec,
        incrementSec: pool.incrementSec,
      },
      tokens: { w: newToken(), b: newToken() },
      disconnectedAt: {},
      opponentGoneNotified: {},
      moves: [],
      result: null,
      clocks: { w: pool.timeSec * 1000, b: pool.timeSec * 1000 },
      runningSince: null,
      drawOfferBy: null,
      createdAt: Date.now(),
      startedAt: null,
      completedAt: null,
      // Queue games are rated under the pool's mode bucket ("nerf"/"buff").
      // Friend and challenge games never set `rated`, so they stay casual.
      replayVersion: REPLAY_VERSION,
      rated: true,
      autoStart: true,
      users: { w: meWhite ? me : them, b: meWhite ? them : me },
      draft: true,
      mode,
      picksVisible: false,
      cadence: mode === "nerf" ? NERF_MODE_CADENCE : DEFAULT_CADENCE,
      draftSeed: makeSeed(),
      ...(cardOverrides ? { cardOverrides } : {}),
      draftActions: [],
    };
    await this.saveMatch(match);

    // Both clients navigate to /game/{id} and take their seat via `reconnect`;
    // the game starts once both have arrived.
    const myColor: Color = meWhite ? "w" : "b";
    const theirColor: Color = meWhite ? "b" : "w";
    send(ws, "paired", { id, color: myColor, token: match.tokens[myColor], pool: poolName, mode });
    send(opponentWs, "paired", { id, color: theirColor, token: match.tokens[theirColor], pool: poolName, mode });
  }

  // ---------------- tournaments ----------------
  //
  // Contained section: the ONLY tournament-specific code in this DO. The
  // tournament engine (src/lib/server/tournamentEngine.ts, driven lazily by
  // GET /api/tournaments/[id]) POSTs here once per paired board to create a
  // real match between two named accounts. The match is shaped exactly like a
  // queue match (createQueueMatch above) — autoStart with both seats
  // pre-assigned — except the rated flag follows the tournament's setting and
  // colors are chosen by the pairing, not a coin flip. Neither player is
  // connected when this runs: both receive their seat token through the
  // tournament detail API instead of a `paired` frame, save it with
  // saveOnlineSeat, and the game starts when both arrive at /game/{id}
  // (the same reconnect + autoStart path queue games use).
  private async createTournamentGame(request: Request): Promise<Response> {
    let body: {
      whiteId?: unknown;
      whiteName?: unknown;
      blackId?: unknown;
      blackName?: unknown;
      timeSec?: unknown;
      incrementSec?: unknown;
      mode?: unknown;
      rated?: unknown;
    };
    try {
      body = (await request.json()) as typeof body;
    } catch {
      return Response.json({ error: "bad_json" }, { status: 400 });
    }
    const whiteId = typeof body.whiteId === "string" ? body.whiteId : "";
    const whiteName = typeof body.whiteName === "string" ? body.whiteName.slice(0, 30) : "";
    const blackId = typeof body.blackId === "string" ? body.blackId : "";
    const blackName = typeof body.blackName === "string" ? body.blackName.slice(0, 30) : "";
    const timeSec = Number.isInteger(body.timeSec) ? Number(body.timeSec) : 180;
    const incrementSec = Number.isInteger(body.incrementSec) ? Number(body.incrementSec) : 0;
    const mode: DraftMode = body.mode === "buff" ? "buff" : "nerf";
    const rated = body.rated === true;
    if (!whiteId || !blackId || !whiteName || !blackName || whiteId === blackId) {
      return Response.json({ error: "bad_players" }, { status: 400 });
    }
    if (timeSec < 0 || timeSec > 7200 || incrementSec < 0 || incrementSec > 180) {
      return Response.json({ error: "invalid_clock" }, { status: 400 });
    }

    // Seat ratings from the same per-mode bucket a queue game would stake
    // (refreshed again on attach, like every match). A D1 hiccup degrades to
    // the default seed rather than failing the round.
    const db = await this.db();
    const seatOf = async (userId: string, name: string): Promise<SeatUser> => {
      const row = db ? await this.seatCategoryRating(db, userId, mode) : null;
      return {
        id: userId,
        name,
        rating: row?.rating ?? GLICKO_DEFAULT.rating,
        rd: row?.rd ?? GLICKO_DEFAULT.rd,
        vol: row?.vol ?? GLICKO_DEFAULT.vol,
        avatar: row?.avatar ?? null,
      };
    };
    const [whiteUser, blackUser] = await Promise.all([seatOf(whiteId, whiteName), seatOf(blackId, blackName)]);

    const id = await this.newCode(8);
    const cardSnap = await this.cardOverridesSnapshot();
    const cardOverrides = this.draftPoolStamp(cardSnap);
    const match: StoredMatch = {
      id,
      setup: {
        ...(mode === "buff"
          ? { whiteNerfId: UNRESTRICTED_NERF.id, blackNerfId: UNRESTRICTED_NERF.id }
          : pickNerfIds(cardSnap.nerfOff)),
        seed: makeSeed(),
        timeSec,
        incrementSec,
      },
      tokens: { w: newToken(), b: newToken() },
      disconnectedAt: {},
      opponentGoneNotified: {},
      moves: [],
      result: null,
      clocks: { w: timeSec * 1000, b: timeSec * 1000 },
      runningSince: null,
      drawOfferBy: null,
      createdAt: Date.now(),
      startedAt: null,
      completedAt: null,
      replayVersion: REPLAY_VERSION,
      ...(rated ? { rated: true } : {}),
      autoStart: true,
      users: { w: whiteUser, b: blackUser },
      draft: true,
      mode,
      picksVisible: false,
      cadence: mode === "nerf" ? NERF_MODE_CADENCE : DEFAULT_CADENCE,
      draftSeed: makeSeed(),
      ...(cardOverrides ? { cardOverrides } : {}),
      draftActions: [],
    };
    await this.saveMatch(match);
    return Response.json({ id, whiteToken: match.tokens.w, blackToken: match.tokens.b });
  }

  private async queueLeave(ws: WebSocket, notify: boolean) {
    const session = this.sessions.get(ws) ?? (ws.deserializeAttachment() as SessionAttachment | null);
    if (!session) return;
    // Every queue entry lives under a "queue:" storage key; listing by prefix
    // also scrubs pre-split legacy keys ("queue:<pool>", no mode segment).
    const stored = await this.ctx.storage.list<QueueEntry[]>({ prefix: "queue:" });
    for (const [key, entries] of stored) {
      const next = (entries ?? []).filter((entry) => entry.attachmentId !== session.id);
      if (next.length !== (entries ?? []).length) await this.ctx.storage.put(key, next);
    }
    if (notify) send(ws, "queueCancelled");
  }

  // ---------------- house players ----------------
  //
  // Engine-driven roster (src/lib/server/bots.ts) that keeps the queue warm.
  // Design rules, all learned from the first system's crash history:
  // - Everything is alarm-driven and serialized: one pending action timer per
  //   match (botActAt), at most one house-vs-house action per tick, never a
  //   loop of engine searches.
  // - Every engine search is hard-capped (HOUSE_SEARCH_CEILING_MS = 80ms).
  // - D1 is touched only where human games already touch it (pairing reads a
  //   rating, game end records the result) plus a one-time roster seeding.
  // - Every house code path is isolated: a failure retires that match or
  //   skips that step, degrading to "bots absent", never to broken human play.
  // - With no human socket connected the roster stands down entirely.

  // A seat is ready to start when a socket holds it or a house player owns it.
  private seatReady(match: StoredMatch, color: Color): boolean {
    return !!match.bots?.[color] || !!this.connectedSession(match.id, color);
  }

  private houseTickError: string | null = null;
  // Last cold-start seeding failure (accounts/ratings/club fills). Seeding no
  // longer aborts the tick, but the error is kept for /healthz so a half-dead
  // roster is diagnosable from a browser instead of silently looking "off".
  private houseSeedError: string | null = null;
  // Last house-game turn-desync the self-heal repaired (cached turn != replay
  // turn), surfaced on /healthz so a reproducing owner can report the exact
  // card + move sequence that drifted the turn without needing the DO logs.
  private houseLastDesync: string | null = null;
  // Remote-engine moves rejected by the local legality check (replay
  // divergence): count + last instance, surfaced on /healthz. In-memory only,
  // so they reset with the isolate — nonzero here means it is happening NOW.
  private houseEngineRejects = 0;
  private houseLastEngineReject: string | null = null;
  private houseSeeded = false;
  // Match ids whose retire (end/delete) itself failed while acting. Kept for
  // the life of the isolate so neither the due loop nor the self-heal sweep
  // re-arms a permanently failing match into a perpetual throw/re-arm loop.
  private houseRetireFailed = new Set<string>();

  // Arm the humanlike think timer for the next pending house action: an
  // opening nerf pick, a buff-offer resolve, or a move. Never overwrites an
  // already-armed timer; clears it when no house action is pending. Cheap by
  // design (no game replay): callers pass the live game when they have one so
  // offers can be detected, and the lock-in deadline enforcement plus the
  // houseTick re-arm sweep cover the cases where they don't.
  private armBotAction(match: StoredMatch, game: NerfGame | null, now = Date.now()) {
    if (!match.bots || match.result) {
      if (match.botActAt) match.botActAt = null;
      return;
    }
    if (!match.startedAt) {
      // Opening nerf draft: any house seat that has not picked yet acts
      // after 2-8s, well inside the 15s lock-in.
      if (match.nerfOptions) {
        const pending = (["w", "b"] as Color[]).some(
          (color) => match.bots?.[color] && match.nerfPicks?.[color] == null,
        );
        if (!pending) match.botActAt = null;
        else if (!match.botActAt) match.botActAt = now + houseDraftThinkMs(randomInt);
      } else {
        match.botActAt = null;
      }
      return;
    }
    // A pending buff offer on a house seat resolves within its lock-in
    // window whoever is on turn (the shared cadence rolls offers for both
    // seats on the same move).
    if (game?.buffs) {
      const offerColor = (["w", "b"] as Color[]).find(
        (color) => match.bots?.[color] && game.buffs!.players[color].offer,
      );
      if (offerColor) {
        if (!match.botActAt) match.botActAt = now + houseDraftThinkMs(randomInt);
        return;
      }
      // A HUMAN seat still holding its offer blocks all moves (the same rule
      // the socket handler enforces on humans): the bot waits instead of
      // arming a move timer. settleDraftAction re-arms it when the pick lands.
      const humanDrafting = (["w", "b"] as Color[]).some(
        (color) => !match.bots?.[color] && game.buffs!.players[color].offer,
      );
      if (humanDrafting) {
        match.botActAt = null;
        return;
      }
    }
    const turn = this.activeColor(match);
    if (!match.bots[turn]) {
      match.botActAt = null;
      return;
    }
    if (match.botActAt) return;
    const clocks = this.currentClocks(match, now);
    const grace = this.movesByColor(match, turn) === 0 ? firstMoveGraceMs : 0;
    // Filler (bot-only) games pace slower via the multiplier passed INTO
    // houseThinkMs, so the slow pace is still bounded by the bot's own clock and
    // never flags it early (the multiply used to happen here, after the clamp).
    // Persona tempo: each bot paces its thinks with a stable personal lean
    // (houseStyle), so the roster never moves in lockstep after one delay.
    const turnPersona = housePersona(match.bots[turn] ?? "");
    // The premove tell: when the human just traded, or the bot has only one
    // legal move, a real player answers instantly. Only possible when the caller
    // handed us the live position (the move-commit paths do); other callers pace
    // normally, so no bot path pays a legal-move generation it did not already
    // have. Never applied to filler, where pacing is deliberately decimated.
    const snap =
      game && turnPersona && !this.isBotOnlyMatch(match)
        ? houseSnapReplyMs(turnPersona, randomInt, snapContext(game, turn))
        : null;
    const think =
      snap ??
      houseThinkMs(
        randomInt,
        clocks[turn] + grace,
        match.setup.timeSec,
        this.isBotOnlyMatch(match) ? houseFillerThinkMultiplier : 1,
        turnPersona ? houseStyle(turnPersona).tempo : 1,
      );
    match.botActAt = now + think;
  }

  // Clock re-attribution for a turn-cache heal. While the cache was drifted,
  // currentClocks was (virtually) draining the CACHED side's clock, but the
  // authoritative replay says the REAL side was on turn for the whole running
  // window — typically the bot "thinking" (or the server stalled) while the
  // record charged the human. The old heal banked via currentClocks, which
  // COMMITTED that wrong charge: the human's clock dropped by the entire stall
  // while the bot's sprang back to its last banked value — the reported "the
  // bot visibly ran out of time, then suddenly moved with its clock teleported
  // back up to 24 seconds, and now I'M flagging". Rules here:
  //   - real turn is a BOT seat: charge the window to the bot — its real
  //     elapsed think/stall time, hard-floored at 0. It may flag on it; the
  //     callers run finishOnFlag right after so a genuinely flagged bot ends
  //     the game instead of moving.
  //   - real turn is a HUMAN seat: drop the window entirely. The human was
  //     never shown as on turn (their client had the bot thinking), so a
  //     server-side mixup must never eat their clock.
  //   - the CACHED side is never charged: its banked value stays put. No clock
  //     is ever "healed" upward past the last authoritative frame, and no
  //     clock is charged for a window it was not actually on turn for.
  private rebankTurnHeal(match: StoredMatch, realTurn: Color, now: number) {
    if (match.runningSince !== null) {
      if (match.setup.timeSec && !match.result && match.bots?.[realTurn]) {
        const grace = this.movesByColor(match, realTurn) === 0 ? firstMoveGraceMs : 0;
        const elapsed = Math.max(0, now - match.runningSince - grace);
        match.clocks[realTurn] = Math.max(0, match.clocks[realTurn] - elapsed);
      }
      match.runningSince = now;
    }
    match.turnColor = realTurn;
  }

  // After a turn-cache heal (cached turnColor != authoritative replay), the
  // SERVER is consistent again — but a connected human client built its board
  // from the live frame stream, which is exactly what the replay disagreed
  // with. If the reconciled turn is the HUMAN's, no further server frame is
  // coming (the bot correctly stays idle), so a client still showing "opponent
  // to move" waits forever — the reported "made two moves and the bot just
  // stopped" freeze in the direction no bot re-arm can fix. Re-send the full
  // start payload (the same authoritative replay-restore frame a reconnect
  // gets) to every connected human seat so their board rebuilds onto the
  // server's truth and play resumes, whichever side is to move.
  private resyncHumanSeatsAfterTurnHeal(match: StoredMatch) {
    for (const color of ["w", "b"] as Color[]) {
      if (match.bots?.[color]) continue;
      if (!this.connectedSession(match.id, color)) continue;
      try {
        this.sendStart(match, color);
      } catch (err) {
        console.error("post-heal resync failed", match.id, color, err);
      }
    }
  }

  // A house match threw while acting (engine edge case, corrupt record, storage
  // hiccup). It must never wedge the roster, so retire it here instead of
  // letting it re-throw on every later tick. A mixed human game ends as an
  // UNRATED DRAW (never a bogus resign/result: a transient action failure is not
  // a lost position, so the bot must not concede it); house-vs-house filler,
  // which nobody is watching for a rating, is deleted. If the retire ITSELF
  // fails, disable the match's timer and remember it so neither the due loop nor
  // the self-heal sweep re-arms it into a perpetual throw/re-arm loop.
  private async retireFailedHouseMatch(match: StoredMatch): Promise<void> {
    try {
      const humanSeat = (["w", "b"] as Color[]).find((c) => !match.bots?.[c]);
      if (humanSeat) {
        if (!match.result) {
          this.bankClocks(match);
          match.runningSince = null;
          match.result = { winner: "draw", reason: "game interrupted" };
          match.completedAt = Date.now();
          match.rated = false;
        }
        await this.endMatch(match, false);
      } else {
        await this.deleteMatch(match);
      }
    } catch (retireErr) {
      console.error("house retire failed, disabling match", match.id, retireErr);
      this.houseRetireFailed.add(match.id);
      try {
        match.botActAt = null;
        await this.saveMatch(match, false);
      } catch {}
    }
  }

  // One orchestration pass, run from the alarm before match maintenance.
  private async houseTick() {
    const now = Date.now();
    if (!(await this.houseEnabled())) {
      // Paused: stop advertising seeks so the lobby shows no bots, and end any
      // bot game already in progress as an unrated draw so no human is left
      // waiting on a bot that will never move. Idempotent: once seeks are empty
      // and house games are ended, later ticks do nothing. Maintenance and the
      // alarm chain continue normally (this only skips house orchestration).
      const seeks = (await this.ctx.storage.get<HouseSeekEntry[]>(houseSeeksKey)) ?? [];
      if (seeks.length) await this.ctx.storage.put(houseSeeksKey, []);
      for (const match of await this.loadLiveMatches()) {
        if (match.result || !(match.bots?.w || match.bots?.b)) continue;
        this.bankClocks(match);
        match.runningSince = null;
        match.result = { winner: "draw", reason: "House players are paused for maintenance" };
        match.completedAt = Date.now();
        match.rated = false;
        try {
          await this.endMatch(match);
        } catch (err) {
          console.error("failed to end paused house game", match.id, err);
        }
      }
      return;
    }
    // Live matches only, via the in-memory index and targeted reads. Finished
    // games were skipped here anyway (see the match.result guard below), so
    // this changes nothing but the cost: no whole-table deserialize per tick.
    const matches = await this.loadLiveMatches();

    // Which personas are tied up, and the live house-game counts for the caps.
    const busy = new Set<string>();
    const liveHouseMatches: StoredMatch[] = [];
    let houseVsHouse = 0;
    let houseGames = 0;
    for (const match of matches) {
      const ids = (["w", "b"] as Color[])
        .map((color) => match.bots?.[color])
        .filter(Boolean) as string[];
      if (!ids.length || match.result) continue;
      // A house match still unstarted long past pairing (the paired human never
      // arrived at the board) frees the seat. Generous window so a slow client
      // load or a backgrounded mobile tab is not dropped mid-arrival; the
      // 30-minute maintenance sweep is the ultimate backstop.
      if (!match.startedAt && !match.nerfOptions && now - match.createdAt > 8 * 60 * 1000) {
        try {
          await this.deleteMatch(match);
        } catch {}
        continue;
      }
      for (const id of ids) busy.add(id);
      houseGames++;
      liveHouseMatches.push(match);
      if (ids.length === 2) houseVsHouse++;
    }

    // Concurrent house-game caps for THIS tick. The house-vs-house filler target
    // is the moderator "Active games" pin (app_settings.house_games, cached),
    // clamped here against the live seat budget — 2 bots per filler game — so a
    // pin can never oversubscribe the roster. The +15 headroom above it is kept
    // for human-vs-bot pickups and /play games, so even a 0 filler target still
    // lets a waiting human be seated with a bot. Lowering the target just stops
    // new filler spawns; the extra games drain out naturally within a few minutes.
    const gamesTarget = await this.houseGamesTarget();
    const houseVsHouseCap = Math.min(gamesTarget, Math.max(0, Math.floor(houseGameSeats / 2)));
    const houseTotalGamesCap = Math.min(gamesTarget + 15, houseGameSeats - houseVsHouseCap);

    // Due house actions. A human waiting on their bot's move is the single most
    // latency-critical thing in this whole method (the reported "accepted a bot
    // game, the bot never moves, then cant connect to game servers"), so
    // human-facing bot actions are drained FIRST, every tick, in a dedicated
    // pass; house-vs-house filler engine work runs only AFTER them, at most one
    // action per tick, and never at all on a tick where a human action had to be
    // deferred. Filler is pure lobby decoration, so it always yields the single
    // thread to a human who is waiting on a move. Everything is bounded per tick
    // (houseMaxActionsPerTick + a wall-clock budget) so one alarm never runs a
    // long batch of 80ms engine searches back to back on the single thread (the
    // CPU spike that evicted the isolate and re-wedged the alarm chain); the
    // remainder drains on a prompt follow-up alarm.
    const isFiller = (m: StoredMatch) => !!(m.bots?.w && m.bots?.b);
    // The human seat of a mixed house match (undefined for house-vs-house
    // filler, which has a bot on both sides).
    const humanSeatOf = (m: StoredMatch): Color | undefined =>
      (["w", "b"] as Color[]).find((c) => !m.bots?.[c]);
    const due = liveHouseMatches
      .filter((m) => m.botActAt && m.botActAt <= now)
      .sort((a, b) => (a.botActAt ?? 0) - (b.botActAt ?? 0));
    const dueHuman = due.filter((m) => !isFiller(m));
    const dueFiller = due.filter((m) => isFiller(m));
    // Bound the engine work this tick can do (see houseMaxActionsPerTick): a
    // stall used to make every game due at once and one alarm ran the whole
    // batch back to back, spiking CPU. Count real actions only (a cheap skip
    // does not count); defer the rest to a prompt follow-up alarm.
    let actionsActed = 0;
    let fillerActed = 0;
    const tickStart = Date.now();
    let deferredDueWork = false;
    const budgetSpent = () =>
      actionsActed >= houseMaxActionsPerTick || Date.now() - tickStart > houseTickBudgetMs;

    // Pass 1: human-facing bot actions (top priority, ahead of all filler).
    for (const match of dueHuman) {
      // A match whose retire failed is left inert (see retireFailedHouseMatch):
      // never act on it again this isolate, so it cannot re-throw on every tick.
      if (this.houseRetireFailed.has(match.id)) continue;
      // Never advance a started house game while its human seat is GENUINELY
      // gone — moving would change the board (or even end the game) before they
      // return. "Gone" is the persisted disconnect signal (disconnectedAt, set
      // on detach and CLEARED on attach), never a bare in-memory socket lookup:
      // an alarm can wake this Durable Object out of hibernation with the
      // sessions map only just being rebuilt, and a just-paired human who has
      // never disconnected must not be mistaken for absent — that made the bot
      // skip its first move on every tick and never play (the reported "bot game
      // never starts"). A fresh seat has no disconnectedAt entry, so the bot
      // acts immediately; the socket lookup is only a secondary guard so a
      // present human (live socket, stale timestamp) is never paused. The bot's
      // timer stays armed across a skip and fires on the first tick after they
      // reconnect (reconnectMatch re-arms it). Draft-deadline safety still runs
      // in maintenance; pre-start nerf-draft picks are harmless (clocks off).
      if (match.startedAt) {
        const humanSeat = humanSeatOf(match);
        if (
          humanSeat &&
          match.disconnectedAt[humanSeat] &&
          !this.connectedSession(match.id, humanSeat)
        ) {
          continue;
        }
      }
      // Per-tick budget: this match would run a real engine action, but we have
      // already spent the tick's action/CPU budget. Leave it (and every human
      // action after it) for an immediate follow-up alarm so one tick never
      // blocks the single thread with a long batch of searches.
      if (budgetSpent()) {
        deferredDueWork = true;
        break;
      }
      try {
        await this.playHouseAction(match, Date.now());
        actionsActed++;
      } catch (err) {
        this.houseTickError = err instanceof Error ? err.message : String(err);
        console.error("house action failed, retiring match", match.id, err);
        await this.retireFailedHouseMatch(match);
      }
    }

    // Pass 2: house-vs-house filler actions, and only once every due
    // human-facing action this tick has been served (deferredDueWork is false)
    // and there is CPU budget left. A human never waits behind a filler search.
    // Up to houseFillerMaxActionsPerTick land per tick, each individually
    // re-checked against the shared action/wall-clock budget, so the 40+
    // concurrent filler games (paced ~8x slower per game, see
    // houseFillerThinkMultiplier) drain their due moves promptly without one
    // alarm ever running a long search batch.
    //
    // Starvation valve: sustained human load can make the yield defer filler
    // on EVERY tick, so a spectated (TV) filler game never acts — the board
    // freezes while its clocks run down. Once the head filler action has been
    // due past houseFillerMaxDeferMs, it takes exactly one action this tick
    // regardless of the budget: one bounded search per tick cannot meaningfully
    // delay the human pass (which already ran), while unbounded deferral is a
    // permanent stall.
    const fillerStarved =
      dueFiller.length > 0 && now - (dueFiller[0].botActAt ?? now) > houseFillerMaxDeferMs;
    for (const match of dueFiller) {
      if (fillerActed >= houseFillerMaxActionsPerTick) break;
      // The starvation valve admits exactly ONE action past the budget; every
      // other filler action must fit the normal budget with no deferred
      // human-facing work.
      const forced = fillerActed === 0 && fillerStarved;
      if (!forced && (deferredDueWork || budgetSpent())) break;
      if (this.houseRetireFailed.has(match.id)) continue;
      try {
        await this.playHouseAction(match, Date.now());
        actionsActed++;
        fillerActed++;
      } catch (err) {
        this.houseTickError = err instanceof Error ? err.message : String(err);
        console.error("house filler action failed, retiring match", match.id, err);
        await this.retireFailedHouseMatch(match);
      }
    }
    // Deferred work (a human action past the budget, or filler we did not reach
    // this tick) fires on an immediate follow-up rather than waiting out the
    // full heartbeat. Those botActAt values are still in the past, so
    // maintenanceAll's scheduleNextAlarm would catch them anyway; this just
    // makes the drain prompt.
    if (deferredDueWork || dueFiller.length > fillerActed) {
      try {
        await this.armAlarmBy(Date.now() + 300);
      } catch {}
    }
    // Self-heal: a live house game with no result and no pending action gets
    // its timer re-armed (covers records saved before a crash or deploy).
    //
    // Un-armed turn-desync recovery: a mixed (human-vs-bot) game whose human is
    // present but has no bot action pending is the one place a drifted turn
    // cache is FATAL. armBotAction reads the cached turnColor; if that says it
    // is the human's turn when the replay (authoritative) says it is the bot's
    // - the extra-move / tempo desync the playHouseAction self-heal repairs -
    // the bot is never armed, so playHouseAction (where that self-heal lives)
    // never runs, and the game sits frozen forever ("used a power-up, took two
    // moves, the bot glitched out and stopped moving"). Rebuild once, reconcile
    // the cache to the real turn, THEN arm off it, so the bot can never be
    // permanently stranded. In the normal case cache == replay, so this only
    // adds one cheap checkpoint-based rebuild while a human is on the clock in a
    // bot game (a handful at most, at the heartbeat cadence); it changes nothing.
    //
    // Filler (bot-vs-bot) games get the same reconcile: they have no human seat
    // to gate on, but the identical extra-move/turn-skip drift strands them just
    // as permanently — and unlike a human game nobody at the board can nudge
    // them, so spectators (TV) watch a frozen board whose clock frame charges
    // the wrong color (the "clock bounces back up every 10s" stall). An unarmed
    // live filler match is already anomalous, so this adds a rebuild only in
    // the failure case it repairs.
    for (const match of liveHouseMatches) {
      if (match.result || match.botActAt || this.houseRetireFailed.has(match.id)) continue;
      try {
        if (await this.finishOnFlag(match, now, false)) continue;
        const humanSeat = humanSeatOf(match);
        if (match.startedAt && (isFiller(match) || (humanSeat && this.connectedSession(match.id, humanSeat)))) {
          const game = await this.gameForPlay(match);
          if (game && !game.result && this.activeColor(match) !== game.board.turn) {
            this.houseLastDesync = `unarmed ${match.id} cached=${this.activeColor(match)} replay=${game.board.turn} moves=${match.moves.length} actions=${JSON.stringify(match.draftActions ?? [])}`;
            console.error("house un-armed turn desync (self-healed)", this.houseLastDesync);
            // Charge the drifted window to the side the replay says was on
            // turn (a bot pays; a human is never charged for a server mixup)
            // and flag the bot outright if that exhausted its clock.
            this.rebankTurnHeal(match, game.board.turn, now);
            if (await this.finishOnFlag(match, now, false)) continue;
            // The heal fixed the SERVER; the human's client may still be on
            // the pre-heal turn (that is how the game got here). Push the
            // authoritative replay-restore frame so their board un-freezes —
            // without this the record heals but the human keeps waiting on a
            // bot the server (correctly) never arms.
            await this.saveMatch(match, false);
            this.resyncHumanSeatsAfterTurnHeal(match);
          }
          this.armBotAction(match, game, now);
          if (match.botActAt) await this.saveMatch(match, false);
          continue;
        }
        this.armBotAction(match, null, now);
        if (match.botActAt) await this.saveMatch(match, false);
      } catch (err) {
        console.error("house re-arm failed", match.id, err);
      }
    }

    // Queue presence and filler games only matter while someone is looking.
    // With nobody on the site — no socket AND no recent lobby fetch — the roster
    // stands down: seeks clear and nothing new starts (live games above still
    // play out and finish).
    let seeks = (await this.ctx.storage.get<HouseSeekEntry[]>(houseSeeksKey)) ?? [];
    const seeksBefore = seeks.length;
    seeks = seeks.filter((seek) => !busy.has(seek.userId) && now - seek.at < houseSeekTtlMs);
    if (!this.sitePresence()) {
      if (seeksBefore) await this.ctx.storage.put(houseSeeksKey, []);
      return;
    }

    const db = await this.db();
    if (!db) return;
    if (!this.houseSeeded) {
      try {
        // Self-healing account seeding. The old gate was a one-time key, so when
        // the roster later grew (60 -> 210) the new personas were never created
        // and showed as accountless "ghost" profiles. Instead, count how many of
        // the CURRENT roster actually have an account and (re)create any missing
        // ones — INSERT OR IGNORE, so it only ever fills gaps. Runs at most once
        // per cold start (this.houseSeeded), and only touches D1 when short.
        if ((await countSeededHouseUsers(db)) < HOUSE_ROSTER_SIZE) {
          await ensureHouseUsers(db);
          await this.ctx.storage.put(houseSeededKey, now);
        }
        // Circulate a roster rating revision to already-seeded accounts. Gated
        // by its own versioned key so it runs once per revision (not per tick),
        // and only after ensureHouseUsers has guaranteed the rows exist.
        if (!(await this.ctx.storage.get<number>(houseRatingsSyncedKey))) {
          await syncHouseRatings(db);
          await this.ctx.storage.put(houseRatingsSyncedKey, now);
        }
        // Self-healing OG-club seeding, mirroring the account seed above. The old
        // gate was a one-shot key, so a seed that set the key but never landed its
        // membership (club row created first, then the club_members batch failed/
        // was partial, or its members referenced not-yet-created ghost accounts)
        // stuck forever and the club stayed empty. Instead, count the club's LIVE
        // members (rows whose user_id has a users row — what the detail route's
        // JOIN actually renders) and (re)run ensureOgClub whenever it is short of
        // the expected membership. Runs after ensureHouseUsers so every persona's
        // users row exists (the club FKs need it); INSERT OR IGNORE, so it only
        // fills gaps. Only touches D1 when short (the ensureHouseUsers pattern).
        if ((await countOgClubMembers(db)) < ogClubMembers().members.length) {
          await ensureOgClub(db);
        }
        // Self-healing membership for EVERY OTHER club (user-made or seeded
        // elsewhere) so the clubs directory never looks dead: each is filled to
        // a deterministic 10-20 house-bot slice. Runs after ensureHouseUsers
        // (the club_members FK needs the persona rows) and skips the OG club
        // (ensureOgClub owns its larger membership). INSERT OR IGNORE and a
        // stable per-slug slice, so it only fills gaps and never touches an
        // owner or a real member's row. Only touches D1 when a club is short.
        if ((await countUnderpopulatedClubs(db)) > 0) {
          await ensureClubsPopulated(db);
        }
        this.houseSeeded = true;
        this.houseSeedError = null;
      } catch (err) {
        // Seeding is profile/leaderboard hygiene, NOT a prerequisite for the
        // lobby being alive — every write above is INSERT OR IGNORE / bounded
        // UPDATE and retries next tick via the unset houseSeeded latch. This
        // used to `return`, so one D1 hiccup here silently killed seeks,
        // pickups, and filler on EVERY tick (0 waiting / 0 in play while the
        // online list still showed the roster) with nothing on /healthz.
        // Now: record it, surface it, and carry on with the rest of the tick.
        this.houseSeedError = err instanceof Error ? err.message : String(err);
        console.error("house seeding failed (continuing tick)", err);
      }
    }

    // Answer any pending friend requests / direct challenges addressed to a bot.
    // Isolated so a social-table hiccup never touches queue/filler orchestration.
    try {
      await this.houseSocialTick(db, busy, now);
    } catch (err) {
      console.error("house social tick failed", err);
    }

    const free = activeHouseRoster(await this.houseCount(), this.houseDayIndex()).filter(
      (persona) => !busy.has(persona.userId) && !seeks.some((seek) => seek.userId === persona.userId),
    );

    // A human waiting alone in a pool gets picked up after a short beat (a
    // human opponent pairs instantly through queueJoin, so still waiting
    // means nobody came). One pickup per tick keeps the tick bounded; each
    // pool is isolated so one hiccup cannot skip the rest. Above the total
    // cap, personas leave the human waiting for a human instead.
    if (houseGames < houseTotalGamesCap) {
      let pickedUp = false;
      outer: for (const mode of QUEUE_MODES) {
        for (const poolName of Object.keys(QUEUE_POOLS)) {
          try {
            const key = this.queueKey(mode, poolName);
            const entries = (await this.ctx.storage.get<QueueEntry[]>(key)) ?? [];
            if (!entries.length) continue;
            const alive = entries.filter((entry) => this.socketForAttachment(entry.attachmentId));
            if (alive.length !== entries.length) await this.ctx.storage.put(key, alive);
            const waiting = alive[0];
            if (!waiting || now - waiting.at < houseHumanPickupMs - 500) continue;
            // Prefer the persona already seeking this pool+mode (the row the
            // human likely saw), then any seeking persona, then an idle one.
            let personaId: string | undefined;
            let index = seeks.findIndex((seek) => seek.mode === mode && seek.pool === poolName);
            if (index < 0 && seeks.length) index = 0;
            if (index >= 0) personaId = seeks.splice(index, 1)[0].userId;
            const persona = (personaId ? housePersona(personaId) : undefined) ?? free.pop();
            if (!persona) continue;
            busy.add(persona.userId);
            const humanWs = this.socketForAttachment(waiting.attachmentId);
            if (!humanWs) continue;
            // Pair first, drop the queue entry after: if pairing throws, the
            // human stays queued for the next tick instead of silently
            // sitting on "searching" forever.
            await this.pairHumanWithHouse(waiting, humanWs, poolName, mode, persona, db);
            await this.ctx.storage.put(key, alive.slice(1));
            pickedUp = true;
            break outer;
          } catch (err) {
            console.error("house pickup failed", mode, poolName, err);
          }
        }
      }
      // One pickup per tick: if it happened, come back quickly in case
      // another human is still waiting in a different pool (the heartbeat
      // alone could be up to 20s away).
      if (pickedUp) {
        try {
          await this.armAlarmBy(now + 1500);
        } catch {}
      }
    }

    // Keep 2-3 personas seeking across the two pools at all times (a mix of
    // Nerf and Buff, rotating which personas via random draw). Seeks carry
    // the persona's LIVE rating (cached, one bounded query per TTL window).
    const liveInfo = await this.houseLiveInfo(db);
    // Heal identity + rating on RETAINED seeks from the live (cached) roster
    // info. A seek row is created once (newHouseSeek) with the name/avatar/rating
    // current at that moment, then kept across ticks until it is picked up or
    // TTLs out — so without this, a bot renamed or re-rated from /mod/house kept
    // showing its OLD name and stale elo in the lobby's seek list until the seek
    // expired. Re-syncing here brings every current-state seek row to the
    // canonical value within one cache window (the same source newHouseSeek and
    // the online-list query read), so the lobby, seek, profile, and leaderboard
    // never disagree for a live bot.
    for (const seek of seeks) {
      const identity = liveInfo.identity.get(seek.userId);
      if (identity) {
        seek.name = identity.username;
        if (identity.avatar) seek.avatar = identity.avatar;
      }
      const liveRating = liveInfo.byId.get(seek.userId)?.[seek.mode];
      if (typeof liveRating === "number") seek.rating = liveRating;
    }
    while (seeks.length < houseSeekMin && free.length) {
      const persona = free.splice(randomInt(free.length), 1)[0];
      seeks.push(this.newHouseSeek(persona, now, liveInfo));
    }
    if (seeks.length >= houseSeekMin && seeks.length < houseSeekMax && free.length && randomInt(100) < 5) {
      const persona = free.splice(randomInt(free.length), 1)[0];
      seeks.push(this.newHouseSeek(persona, now, liveInfo));
    }
    // Per-mode floor: guarantee at least one seek in each pool so neither the
    // Nerf nor the Buff lobby is ever left without a house seeker (the random
    // per-seek mode roll alone can leave one mode empty). Forces the mode but
    // keeps the random pool from newHouseSeek.
    for (const mode of QUEUE_MODES) {
      if (!free.length) break;
      if (seeks.some((seek) => seek.mode === mode)) continue;
      const persona = free.splice(randomInt(free.length), 1)[0];
      seeks.push({ ...this.newHouseSeek(persona, now, liveInfo), mode });
    }
    await this.ctx.storage.put(houseSeeksKey, seeks);

    // House-vs-house filler so the lobby and TV always look busy: maintain a
    // steady 40-55 concurrent bot games (HOUSE_VS_HOUSE_FLOOR/CAP), spawned one
    // per tick with staggered spacing so games never start (or end) in lockstep
    // and a cold start ramps up over minutes rather than bursting.
    // Tier 2 / M4 cutover (reversible): when the arena owns bot-vs-bot, the DO
    // stops spawning its own filler and lets the arena supply it (streamed in
    // via /arena). Flip ARENA_OWNS_FILLER back off and the DO resumes filler on
    // the next tick. Ownership additionally requires the arena to be SUPPLYING:
    // an /arena/games sync that carried at least one accepted game must have
    // landed within ARENA_FILLER_FALLBACK_MS (measured from boot on a fresh
    // isolate). A bare "I'm alive" sync is NOT enough — an arena that is up but
    // whose games all get filtered (version-skewed roster ids) or that never
    // spawns must hand filler back to the DO exactly like a dead one, or the
    // lobby sits empty while every health signal "passes". While the DO is
    // covering, the moment a real arena game lands the stamp refreshes and the
    // DO stops spawning new filler; its in-flight games just play out (brief
    // overlap during an arena ramp-up is fine — the lobby unions both).
    // Bot-vs-human pickup + house seeks above are unaffected.
    const arenaOwnsFiller =
      this.env.ARENA_OWNS_FILLER === "true" &&
      this.env.ARENA_INGEST_ENABLED === "true" &&
      now - (this.lastArenaGamesAt || this.bootedAt) < ARENA_FILLER_FALLBACK_MS;
    // Never let a filler spawn dip into the seek reserve: after taking its two
    // personas the roster must still hold enough free personas to top the seek
    // floor back up on the next tick. Together with the roster-sized caps above
    // this guarantees a steady 2-3 seekers are always maintained.
    const freeAfterFiller = free.length - 2;
    if (
      !arenaOwnsFiller &&
      houseVsHouse < houseVsHouseCap &&
      houseGames + 1 < houseTotalGamesCap &&
      freeAfterFiller >= houseSeekMin
    ) {
      try {
        const nextAt = (await this.ctx.storage.get<number>(houseNextFillerKey)) ?? 0;
        if (now >= nextAt) {
          // Weight the pairing toward the personas with the fewest games played
          // (recorded leaderboard games + this session's filler appearances), so
          // filler spreads evenly across the roster and no bot lingers at zero
          // rather than the same faces churning. The daily active-window rotation
          // (activeHouseRoster) is what eventually feeds every persona into `free`.
          const gamesOf = (id: string) =>
            (liveInfo.gamesById.get(id) ?? 0) + (this.houseFillerGames.get(id) ?? 0);
          const pair = pickHouseFillerPair(free, gamesOf, randomInt);
          if (pair) {
            const [a, b] = pair;
            for (const p of pair) {
              const idx = free.findIndex((f) => f.userId === p.userId);
              if (idx >= 0) free.splice(idx, 1);
              this.houseFillerGames.set(p.userId, (this.houseFillerGames.get(p.userId) ?? 0) + 1);
            }
            await this.startHouseVsHouseGame(a, b, db);
            // Staggered pacing toward the 40-55 steady band: one spawn per tick,
            // ~1.5-3s apart while below the floor (a cold start ramps to 40
            // games over ~2 minutes, never a burst) and 8-15s once there.
            const delay = houseFillerSpawnDelayMs(houseVsHouse + 1, randomInt);
            await this.ctx.storage.put(houseNextFillerKey, now + delay);
            // During ramp-up the games just spawned may not have due actions
            // yet, so make sure an alarm fires for the NEXT spawn rather than
            // waiting out the 20s heartbeat with the population under target.
            if (houseVsHouse + 1 < HOUSE_VS_HOUSE_FLOOR) {
              try {
                await this.armAlarmBy(now + delay);
              } catch {}
            }
          }
        }
      } catch (err) {
        console.error("house filler start failed", err);
      }
    }
  }

  // The house player's pending action lands: an opening nerf pick, a buff
  // offer resolve, an occasional buff activation, or a move. Exactly one
  // action per invocation; every follow-up re-arms through armBotAction.
  // Ask the OCI engine service for a house move. Returns null (never throws)
  // whenever the feature is off, the box is slow/unreachable, the reply is bad,
  // or the engine versions disagree — the caller then falls back to the local
  // engine. The AbortController timeout is what keeps a stalled box from ever
  // holding the alarm tick; the `await` itself yields the DO thread so live
  // sockets are serviced while the remote search runs.
  private async remoteHouseMove(
    match: StoredMatch,
    skill: HouseSkill,
    remainingClockMs?: number,
    profile?: ResolvedSkillProfile,
  ): Promise<Move | null> {
    if (this.env.HOUSE_ENGINE_REMOTE !== "true" || !this.env.HOUSE_ENGINE_URL) return null;
    const ctl = new AbortController();
    const timer = setTimeout(() => ctl.abort(), HOUSE_ENGINE_TIMEOUT_MS);
    try {
      const res = await fetch(`${this.env.HOUSE_ENGINE_URL}/move`, {
        method: "POST",
        signal: ctl.signal,
        headers: {
          "content-type": "application/json",
          ...(this.env.HOUSE_ENGINE_TOKEN
            ? { authorization: `Bearer ${this.env.HOUSE_ENGINE_TOKEN}` }
            : {}),
        },
        body: JSON.stringify({
          match: serializeMatchForEngine(match),
          skill,
          // The moderator-resolved strength. Optional and clamped again on the
          // box, so an old engine build ignores it (baked strength) and a new
          // one honors it — no lockstep deploy needed for a tuning change.
          profile,
          remainingClockMs,
          replayVersion: REPLAY_VERSION,
        }),
      });
      if (res.status === 409) {
        // Version drift: this worker was deployed without an engine redeploy.
        // Ask the box to rebuild itself from origin/master; keep falling back
        // to local compute until it catches up.
        this.pingEngineUpdate();
        return null;
      }
      if (!res.ok) return null; // 401 / 5xx -> local fallback
      const data = (await res.json()) as { move?: Move | null };
      return data.move ?? null;
    } catch {
      return null; // timeout / network / parse -> local fallback
    } finally {
      clearTimeout(timer);
    }
  }

  // Heal engine version drift: POST the box's self-updater (see
  // engine-service/deploy/updater.mjs), which rebuilds from origin/master only
  // when master's REPLAY_VERSION matches ours, so a worker deployed from
  // unpushed code degrades to local fallback, never a desync. Fire-and-forget
  // and throttled here; the updater has its own cooldown + version guard, so
  // duplicate pings (or several DOs pinging at once) are harmless.
  private lastEngineUpdatePingAt = 0;
  private pingEngineUpdate() {
    if (!this.env.HOUSE_ENGINE_URL) return;
    const now = Date.now();
    if (now - this.lastEngineUpdatePingAt < 5 * 60_000) return;
    this.lastEngineUpdatePingAt = now;
    void fetch(`${this.env.HOUSE_ENGINE_URL}/update`, {
      method: "POST",
      headers: {
        "content-type": "application/json",
        ...(this.env.HOUSE_ENGINE_TOKEN
          ? { authorization: `Bearer ${this.env.HOUSE_ENGINE_TOKEN}` }
          : {}),
      },
      body: JSON.stringify({ replayVersion: REPLAY_VERSION }),
    }).catch(() => {});
  }

  private async playHouseAction(dueMatch: StoredMatch, now = Date.now()) {
    // RACE GUARD: `dueMatch` was loaded at the start of the tick, and earlier
    // due matches' actions (engine searches, D1 end writes, remote-engine
    // fetches) awaited in between — none of those hold the DO input gate, so a
    // human frame for THIS match may have landed and advanced or ended it in
    // storage since. For a human-seated game dueMatch is a deserialized copy
    // that cannot see that mutation; acting on it would save the stale copy
    // back over the newer record (a finished game resurrected as live).
    // Re-read the freshest copy (a map hit for bot-only games, one input-gated
    // storage get otherwise) and act on THAT. Behavior is identical when
    // nothing changed.
    let match = (await this.loadMatch(dueMatch.id)) ?? dueMatch;
    match.botActAt = null;
    if (match.result) return;

    // Opening nerf draft picks (no game replay needed).
    if (!match.startedAt) {
      if (!match.nerfOptions) return;
      let picked = false;
      for (const color of ["w", "b"] as Color[]) {
        if (!match.bots?.[color] || match.nerfPicks?.[color] != null) continue;
        const options = match.nerfOptions[color];
        const tierOf = (id: string) => PLAYABLE_NERFS.find((nerf) => nerf.id === id)?.tier ?? 5;
        const index = houseNerfPickIndex([tierOf(options[0]), tierOf(options[1])], randomInt);
        match.nerfPicks = { ...(match.nerfPicks ?? {}), [color]: index };
        picked = true;
        const opp: Color = color === "w" ? "b" : "w";
        if (match.nerfPicks[opp] == null) this.broadcast(match, "dtNerfPicked", { color });
      }
      if (!picked) return;
      if (match.nerfPicks?.w != null && match.nerfPicks?.b != null) {
        await this.finalizeNerfDraft(match);
        return;
      }
      await this.saveMatch(match);
      return;
    }

    if (await this.finishOnFlag(match, now, false)) return;
    // A stale or failed replay ends the game gracefully inside gameForPlay
    // (draw, end frame, recorded); nothing left for the house seat to do.
    let game = await this.gameForPlay(match);
    if (!game) return;
    // Self-heal a drifted turn cache. The clock, flag enforcement and bot
    // arming all read match.turnColor (via activeColor), but the move dispatch
    // below reads the replayed position (game.board.turn). When they disagree
    // the bot's clock bleeds on the cached side while the real turn is the
    // other, so it never moves and eventually flags — a wedge that survives a
    // reconnect because it lives in the record, not the alarm chain. The replay
    // is authoritative for move legality, so reconcile the cache to it; bank the
    // elapsed time to the previously-charged side first (mirrors
    // settleDraftAction's turn handover) so no clock is retroactively
    // double-charged. Logged so the draft action that replays differently can be
    // found and fixed at the source.
    const cachedTurn = this.activeColor(match);
    if (match.draft && cachedTurn !== game.board.turn) {
      this.houseLastDesync = `armed ${match.id} cached=${cachedTurn} replay=${game.board.turn} moves=${match.moves.length} actions=${JSON.stringify(match.draftActions ?? [])}`;
      console.error("house turn desync", this.houseLastDesync);
      // Charge the drifted window to the side the replay says was on turn (a
      // bot pays its real elapsed time; a human is never charged for a server
      // mixup — see rebankTurnHeal). A bot whose re-attributed clock ran out
      // flags right here rather than moving after visibly running out.
      this.rebankTurnHeal(match, game.board.turn, now);
      if (await this.finishOnFlag(match, now, false)) return;
      // Reconciling the cache to the replay can hand the turn to the HUMAN.
      // In that direction the bot correctly goes idle, so no move frame will
      // ever reach the human's client — which is still on the pre-heal turn
      // and shows a bot "thinking" forever. Persist the healed record and
      // re-send the authoritative start payload so the client rebuilds onto
      // the server's truth and can move (the !personaId branch below then
      // parks the bot until they do). When the replay says it is the BOT's
      // turn the move committed below carries the correction instead.
      if (!match.bots?.[game.board.turn]) {
        await this.saveMatch(match, false);
        this.resyncHumanSeatsAfterTurnHeal(match);
      }
    }
    if (game.result) {
      // Derived but unrecorded result (should not happen): settle it.
      this.bankClocks(match, now);
      match.runningSince = null;
      match.result = game.result;
      match.completedAt = now;
      await this.endMatch(match);
      return;
    }

    // A pending buff offer resolves first (it may not even be our turn). A
    // card that throws while the AI evaluates or picks it must never wedge the
    // bot: fall back to banking the offer, which is always a safe skip.
    for (const color of ["w", "b"] as Color[]) {
      if (!match.bots?.[color] || !game.buffs?.players[color].offer) continue;
      try {
        const choice = aiDraftChoice(game, color);
        // Persona draft behavior: cautious personas sometimes bank a pickable
        // offer to roll a higher tier next round (houseStyle().bankBias), so
        // different bots run visibly different draft plans.
        const draftPersona = housePersona(match.bots[color] ?? "");
        const bankRoll =
          draftPersona && choice?.action === "pick"
            ? randomInt(100) < Math.round(houseStyle(draftPersona).bankBias * 100)
            : false;
        if (choice?.action === "pick" && !bankRoll) await this.resolveDraftPick(match, game, color, choice.index);
        else await this.resolveDraftBank(match, game, color);
      } catch (err) {
        console.error("house draft resolve failed, banking offer", match.id, err);
        await this.resolveDraftBank(match, game, color);
      }
      return; // settleDraftAction armed the next action and saved
    }

    // A human seat still resolving its draft blocks all moves (same rule the
    // socket handler applies to humans): stand down until the pick lands —
    // settleDraftAction re-arms the bot then.
    const buffsNow = game.buffs;
    if (
      match.draft &&
      (["w", "b"] as Color[]).some(
        (c) => !match.bots?.[c] && buffsNow?.players[c].offer,
      )
    ) {
      match.botActAt = null;
      await this.saveMatch(match, false);
      return;
    }

    const color = game.board.turn;
    const personaId = match.bots?.[color];
    if (!personaId) {
      this.armBotAction(match, game, now);
      await this.saveMatch(match, false);
      return;
    }
    const persona = housePersona(personaId);
    if (!persona) throw new Error(`unknown house persona ${personaId}`);

    // Sometimes fire a held buff instead of moving. aiChooseBuffActivation
    // applies its own worth-it gates; the extra coin keeps house players from
    // dumping every card the moment it clears the bar. A buff that throws
    // mid-activation must not wedge the bot or corrupt the move it plays next.
    if (match.draft && game.buffs && randomInt(100) < Math.round(houseStyle(persona).activationChance * 100)) {
      try {
        const activation = aiChooseBuffActivation(game, color);
        if (activation) {
          const ps = game.buffs.players[color];
          const inst = ps.buffs[activation.buffIndex];
          const theirs = game.buffs.players[color === "w" ? "b" : "w"];
          const mineBefore = ps.buffs.length;
          const theirsBefore = theirs.buffs.length;
          if (activateBuff(game, color, activation.buffIndex, activation.picks)) {
            this.markBuffRevealed(inst);
            for (const added of ps.buffs.slice(mineBefore)) this.markBuffRevealed(added);
            for (const added of theirs.buffs.slice(theirsBefore)) this.markBuffRevealed(added);
            match.draftActions = [
              ...(match.draftActions ?? []),
              { ply: match.moves.length, color, a: "use", buffIndex: activation.buffIndex, picks: activation.picks },
            ];
            await this.settleDraftAction(match, game, null, {
              color,
              buffIndex: activation.buffIndex,
              picks: activation.picks,
              card: { id: inst.id, tier: inst.tier as number },
            });
            return;
          }
        }
      } catch (err) {
        // Discard the possibly-mutated replica and rebuild a clean one from the
        // stored record (the failed activation was never appended, so the
        // rebuild is the pre-activation position), then fall through to a
        // normal move so the bot still acts this turn.
        console.error("house buff activation failed, skipping to a move", match.id, err);
        const fresh = this.gameFromMatch(match);
        if (!fresh || fresh.result) {
          this.armBotAction(match, null, now);
          await this.saveMatch(match, false);
          return;
        }
        game = fresh;
      }
    }

    // The move: engine-picked inside a hard-capped budget (see bots.ts). A
    // throw or a null pick (an engine edge case) can never leave the bot idle:
    // fall back to any legal move, and only end the game when there truly is
    // no legal move at all.
    const clocks = this.currentClocks(match, now);
    const remaining = match.setup.timeSec ? clocks[color] : undefined;
    // The persona's effective strength (baked tier ⊕ current moderator
    // override). Resolved once and used for both the remote payload and the
    // local fallback so a mid-game strength change is honored on either path.
    const profile = await this.houseResolvedProfile(persona.skill);
    let move: Move | null = null;
    // Remote (OCI) search only for games a human is in. Filler (bot-vs-bot)
    // moves always use the local hard-capped search (<= 80ms): one fewer
    // subrequest and up to HOUSE_ENGINE_TIMEOUT_MS less awaited wall time per
    // bot-vs-bot move, on games whose playing strength nobody depends on.
    // Also skip remote when the bot's clock is nearly gone: the round-trip
    // (up to 3s) is charged as real think time and could flag the bot
    // mid-fetch, while the local pick answers in tens of milliseconds — the
    // hard cap on the bot's think budget under time pressure.
    const useRemote =
      this.env.HOUSE_ENGINE_REMOTE === "true" &&
      !this.isBotOnlyMatch(match) &&
      (remaining === undefined || remaining > HOUSE_ENGINE_TIMEOUT_MS + 2000);
    if (useRemote) {
      const remote = await this.remoteHouseMove(match, persona.skill, remaining, profile);
      // The await above yielded the DO thread for up to HOUSE_ENGINE_TIMEOUT_MS;
      // the match may have ended (resign, disconnect, flag) or advanced while
      // the remote search ran — and for a human-seated game `match` is a
      // pre-await deserialized copy that cannot see a storage mutation (the
      // top-of-method reload only covers up to this point). Re-read before
      // acting so a stale copy is never committed over the newer record.
      const fresh = await this.loadMatch(match.id);
      if (!fresh || fresh.result) return;
      if (fresh !== match) {
        if (
          fresh.moves.length !== match.moves.length ||
          (fresh.draftActions?.length ?? 0) !== (match.draftActions?.length ?? 0)
        ) {
          // The game advanced mid-search: the replayed `game` (and any move
          // validated against it) is stale. Re-arm off the fresh record and
          // let the follow-up alarm act on the real position.
          this.armBotAction(fresh, null, Date.now());
          await this.saveMatch(fresh, false);
          return;
        }
        // Same position (moves/actions unchanged, so `game` is still exact);
        // continue with the freshest record so chat/clock/offer fields written
        // during the await are not clobbered by the pre-await copy.
        fresh.botActAt = null;
        match = fresh;
      }
      // Treat the OCI reply as untrusted: accept only a move that is legal in
      // our own reconstruction, and commit our LOCAL instance (never the wire
      // object). A desynced/tampered move simply isn't found -> local fallback.
      if (remote) {
        move = legalMoves(game).find((m) => sameMove(m, remote)) ?? null;
        if (!move) {
          // A rejected engine move means the remote replay DIVERGED from ours
          // despite matching REPLAY_VERSIONs — a serialization-level bug (the
          // 2026-07-10 reroll incident), not ordinary drift. Every rejection
          // burns a local fallback search on the DO thread, so make the signal
          // impossible to miss: it is surfaced on /healthz next to lastDesync.
          this.houseEngineRejects += 1;
          this.houseLastEngineReject = `${match.id} uci=${moveToUCI(remote)} moves=${match.moves.length}`;
          console.error("house engine move rejected as illegal (replay divergence?)", this.houseLastEngineReject);
        }
      }
    }
    if (!move) {
      try {
        move = pickHouseMove(game, persona.skill, randomInt, remaining, undefined, profile, persona);
      } catch (err) {
        console.error("house move pick failed, using a legal fallback", match.id, err);
      }
    }
    if (!move) {
      const legal = legalMoves(game);
      if (legal.length) {
        // Prefer a random move that does not immediately trip the bot's own
        // nerf loss (mirrors the blunder path in pickHouseMove); fall back to
        // any legal move. triggersOwnNerfLoss is best-effort here: a throw must
        // never leave the bot without a move, so any failure just widens the
        // pool back to every legal move.
        let pool = legal;
        try {
          const safe = legal.filter((m) => !triggersOwnNerfLoss(game, m));
          if (safe.length) pool = safe;
        } catch (err) {
          console.error("house nerf-safety filter failed, using any legal move", match.id, err);
        }
        move = pool[randomInt(pool.length)];
      } else {
        // No legal move but no result — should be unreachable; end through the
        // normal flow rather than wedge the match.
        match.clocks = clocks;
        match.runningSince = null;
        match.result = resign(game, color).result;
        match.completedAt = now;
        await this.endMatch(match);
        return;
      }
    }
    // The searches above (a remote fetch can take up to 3s; a late alarm can
    // add more) run on the bot's own clock. If its time ran out while
    // "thinking", it flags here — a bot must never play a move after visibly
    // running out of time, and its clock must never re-appear with time on it.
    if (await this.finishOnFlag(match, Date.now(), false)) return;
    await this.commitMove(match, game, color, move, moveToUCI(move));
  }

  // Live per-mode ratings for the whole house roster, cached for
  // HOUSE_RATINGS_TTL_MS (see houseRatingsCache). Missing rows and read
  // failures fall back to houseSeedRating at the call sites.
  private async houseLiveRatings(
    db: D1Database | null,
  ): Promise<Map<string, Partial<Record<DraftMode, number>>>> {
    return (await this.houseLiveInfo(db)).byId;
  }

  // Ratings AND identity for the roster, one cache window: two bounded queries
  // per TTL, shared by seeks, filler seats, and any caller that only needs the
  // ratings map (houseLiveRatings above).
  private async houseLiveInfo(db: D1Database | null): Promise<{
    byId: Map<string, Partial<Record<DraftMode, number>>>;
    identity: Map<string, { username: string; avatar: string | null }>;
    gamesById: Map<string, number>;
  }> {
    const now = Date.now();
    if (this.houseRatingsCache && now - this.houseRatingsCache.at < GameServer.HOUSE_RATINGS_TTL_MS) {
      return this.houseRatingsCache;
    }
    const byId = new Map<string, Partial<Record<DraftMode, number>>>();
    const identity = new Map<string, { username: string; avatar: string | null }>();
    const gamesById = new Map<string, number>();
    if (db) {
      try {
        // Chunked (chunkIds): the 210-id roster exceeds D1's 100-bound-params
        // cap in one IN(), which made BOTH queries throw on every call — the
        // catch below then silently pinned every seek and filler seat to its
        // baked name and seed rating forever (the reported "renamed a bot but
        // the lobby never updates").
        const chunks = chunkIds(HOUSE_ROSTER.map((p) => p.userId));
        const [ratingChunks, userChunks] = await Promise.all([
          Promise.all(
            chunks.map((chunk) =>
              db
                .prepare(
                  `SELECT user_id, category, rating, games FROM user_ratings
                   WHERE category IN ('nerf','buff') AND user_id IN (${chunk.map(() => "?").join(",")})`,
                )
                .bind(...chunk)
                .all<{ user_id: string; category: string; rating: number; games: number }>(),
            ),
          ),
          Promise.all(
            chunks.map((chunk) =>
              db
                .prepare(`SELECT id, username, avatar FROM users WHERE id IN (${chunk.map(() => "?").join(",")})`)
                .bind(...chunk)
                .all<{ id: string; username: string; avatar: string | null }>(),
            ),
          ),
        ]);
        for (const rows of ratingChunks) {
          for (const row of rows.results) {
            if (row.category !== "nerf" && row.category !== "buff") continue;
            const entry = byId.get(row.user_id) ?? {};
            entry[row.category as DraftMode] = Math.round(row.rating);
            byId.set(row.user_id, entry);
            gamesById.set(row.user_id, (gamesById.get(row.user_id) ?? 0) + (row.games ?? 0));
          }
        }
        for (const users of userChunks) {
          for (const row of users.results) {
            identity.set(row.id, { username: row.username, avatar: row.avatar });
          }
        }
      } catch {
        // Fall back to seed ratings / baked identity; retry after the TTL.
      }
    }
    this.houseRatingsCache = { at: now, byId, identity, gamesById };
    return this.houseRatingsCache;
  }

  private newHouseSeek(
    persona: HousePersona,
    now: number,
    live?: {
      byId: Map<string, Partial<Record<DraftMode, number>>>;
      identity: Map<string, { username: string; avatar: string | null }>;
    },
  ): HouseSeekEntry {
    const { pool, mode } = pickHouseSeek(randomInt);
    // Identity from the users table (admin edits from /mod/house land there),
    // falling back to the baked persona constants.
    const identity = live?.identity.get(persona.userId);
    return {
      userId: persona.userId,
      name: identity?.username ?? persona.name,
      pool,
      mode,
      // The LIVE rating in the seek's mode bucket, so the number in the lobby
      // moves with the account's real results (seed only as a fallback).
      rating: live?.byId.get(persona.userId)?.[mode] ?? houseSeedRatingForMode(persona, mode),
      avatar: identity?.avatar ?? persona.avatar,
      at: now,
    };
  }

  // The persona's SeatUser for a HUMAN-facing match seat, with its live rating
  // in the pool's mode bucket (one D1 read, event-scale only: queue pickups and
  // /play bot games — filler seats use the cached ratings instead, see
  // startHouseVsHouseGame).
  private async houseSeatUser(db: D1Database, persona: HousePersona, mode: DraftMode): Promise<SeatUser> {
    try {
      const row = await this.seatCategoryRating(db, persona.userId, mode);
      if (row) {
        return {
          id: persona.userId,
          // The users row is the identity system of record (admin renames from
          // /mod/house land there); baked constants are the fallback.
          name: row.username ?? persona.name,
          rating: row.rating,
          rd: row.rd,
          vol: row.vol,
          avatar: row.avatar ?? persona.avatar,
        };
      }
    } catch {}
    const rating = houseSeedRatingForMode(persona, mode);
    return { id: persona.userId, name: persona.name, rating, rd: 150, vol: 0.06, avatar: persona.avatar };
  }

  // A rated queue match against a house player, identical to a human-vs-human
  // queue match except for the house seat markers.
  private async newHouseMatchRecord(
    tc: { timeSec: number; incrementSec: number },
    mode: DraftMode,
    seats: { users: Partial<Record<Color, SeatUser>>; bots: Partial<Record<Color, string>> },
  ): Promise<StoredMatch> {
    const id = await this.newCode(8);
    const cardSnap = await this.cardOverridesSnapshot();
    const cardOverrides = this.draftPoolStamp(cardSnap);
    return {
      id,
      setup: {
        ...(mode === "buff"
          ? { whiteNerfId: UNRESTRICTED_NERF.id, blackNerfId: UNRESTRICTED_NERF.id }
          : pickNerfIds(cardSnap.nerfOff)),
        seed: makeSeed(),
        timeSec: tc.timeSec,
        incrementSec: tc.incrementSec,
      },
      tokens: { w: newToken(), b: newToken() },
      disconnectedAt: {},
      opponentGoneNotified: {},
      moves: [],
      result: null,
      clocks: { w: tc.timeSec * 1000, b: tc.timeSec * 1000 },
      runningSince: null,
      drawOfferBy: null,
      createdAt: Date.now(),
      startedAt: null,
      completedAt: null,
      replayVersion: REPLAY_VERSION,
      rated: true,
      autoStart: true,
      users: seats.users,
      draft: true,
      mode,
      picksVisible: false,
      cadence: mode === "nerf" ? NERF_MODE_CADENCE : DEFAULT_CADENCE,
      draftSeed: makeSeed(),
      ...(cardOverrides ? { cardOverrides } : {}),
      draftActions: [],
      bots: seats.bots,
    };
  }

  // Pair a queued human with a house player. The human gets the usual
  // "paired" frame and takes their seat via reconnect; the house seat counts
  // as arrived, so the game starts the moment the human does.
  private async pairHumanWithHouse(
    waiting: QueueEntry,
    humanWs: WebSocket,
    poolName: string,
    mode: DraftMode,
    persona: HousePersona,
    db: D1Database,
  ) {
    if (!QUEUE_POOLS[poolName]) return;
    const human: SeatUser = {
      id: waiting.userId,
      name: waiting.username,
      rating: waiting.rating,
      rd: waiting.rd,
      vol: waiting.vol,
      avatar: waiting.avatar ?? null,
    };
    const house = await this.houseSeatUser(db, persona, mode);
    const humanWhite = randomInt(2) === 0;
    const pool = QUEUE_POOLS[poolName];
    const match = await this.newHouseMatchRecord(
      { timeSec: pool.timeSec, incrementSec: pool.incrementSec },
      mode,
      {
        users: { w: humanWhite ? human : house, b: humanWhite ? house : human },
        bots: humanWhite ? { b: persona.userId } : { w: persona.userId },
      },
    );
    await this.saveMatch(match);
    const color: Color = humanWhite ? "w" : "b";
    send(humanWs, "paired", { id: match.id, color, token: match.tokens[color], pool: poolName, mode });
  }

  // "Play vs bot" (the /play page), for signed-in Buff/Nerf games: create a
  // RATED house-bot game on demand so a win moves the account rating, exactly
  // like a queue pickup does. This is the same machinery as pairHumanWithHouse
  // (both seats are accounts, rated:true, mode bucket), differing only in that
  // the human chose the opponent's difficulty and the time control directly
  // instead of a queue pool. A human explicitly asked for THIS game, so it is
  // honoured past the background house caps (like a targeted seek answer). Any
  // failure surfaces an error frame; the client then falls back to a local
  // casual bot game, so the button always starts something.
  private async playHouseBot(ws: WebSocket, data: unknown) {
    const session = this.session(ws);
    if (session.matchId) return error(ws, "already_joined", "This connection already belongs to a game.");
    if (!session.userId || !session.username) {
      return error(ws, "auth_required", "Sign in to play a rated bot game.");
    }
    if (await this.abortTimedOut(ws, session.userId)) return;
    const req = (data as
      | { difficulty?: unknown; mode?: unknown; timeSec?: unknown; incrementSec?: unknown; color?: unknown }
      | undefined) ?? {};
    const difficulty: BotDifficulty =
      req.difficulty === "easy" ? "easy" : req.difficulty === "hard" ? "hard" : "medium";
    // The player's colour choice ("w"/"b"), or a coin flip when they picked
    // "random" (or an old client sent nothing).
    const wantColor: Color | null = req.color === "w" ? "w" : req.color === "b" ? "b" : null;
    // Only the two rated draft modes exist as house games (Plain chess has no
    // ranked bucket and stays a local casual game on the client).
    const mode: DraftMode = req.mode === "nerf" ? "nerf" : "buff";
    const timeSec = Number.isInteger(req.timeSec) ? Number(req.timeSec) : 600;
    const incrementSec = Number.isInteger(req.incrementSec) ? Number(req.incrementSec) : 0;
    if (timeSec < 0 || timeSec > 7200 || incrementSec < 0 || incrementSec > 60) {
      return error(ws, "invalid_clock", "Unsupported time control.");
    }
    if (!(await this.houseEnabled())) {
      return error(ws, "house_paused", "Bots are resting right now. Try again shortly.");
    }
    const db = await this.db();
    if (!db) return error(ws, "server_unconfigured", "Bot games are unavailable right now.");
    // Personas already seated in a live game are unavailable; pick a free one in
    // the chosen difficulty band. loadLiveMatches is the bounded live-index read
    // the house tick already uses (never a match-table scan).
    const busy = new Set<string>();
    for (const m of await this.loadLiveMatches()) {
      if (m.result) continue;
      for (const c of ["w", "b"] as Color[]) {
        const id = m.bots?.[c];
        if (id) busy.add(id);
      }
    }
    const persona = pickHouseBotByDifficulty(difficulty, busy, randomInt, activeHouseRoster(await this.houseCount(), this.houseDayIndex()));
    if (!persona) return error(ws, "no_bot", "Every bot is busy right now. Try again shortly.");
    let rating = 1500;
    let rd = 350;
    let vol = 0.06;
    let avatar: string | null = null;
    const row = await this.seatCategoryRating(db, session.userId, mode);
    if (row) {
      rating = row.rating;
      rd = row.rd;
      vol = row.vol;
      avatar = row.avatar;
    }
    const human: SeatUser = { id: session.userId, name: session.username, rating, rd, vol, avatar };
    const house = await this.houseSeatUser(db, persona, mode);
    const humanWhite = wantColor ? wantColor === "w" : randomInt(2) === 0;
    const match = await this.newHouseMatchRecord(
      { timeSec, incrementSec },
      mode,
      {
        users: { w: humanWhite ? human : house, b: humanWhite ? house : human },
        bots: humanWhite ? { b: persona.userId } : { w: persona.userId },
      },
    );
    await this.saveMatch(match);
    const color: Color = humanWhite ? "w" : "b";
    send(ws, "paired", { id: match.id, color, token: match.tokens[color], pool: "bot", mode });
  }

  private async startHouseVsHouseGame(a: HousePersona, b: HousePersona, db: D1Database) {
    // Filler pools skip 1+0/2+1: the slowed filler move pacing would flag an
    // ultra-bullet game within a handful of moves (broken-looking on TV).
    const { pool, mode } = pickHouseFillerSeek(randomInt);
    const aWhite = randomInt(2) === 0;
    const [white, black] = aWhite ? [a, b] : [b, a];
    const tc = QUEUE_POOLS[pool];
    // Filler seats are display-only (a bot-vs-bot game is never recorded, so
    // rd/vol never feed a rating update): build them from the cached live
    // ratings the tick already loads for seeks instead of houseSeatUser's two
    // D1 queries per seat — four fewer queries per filler spawn, zero marginal
    // D1 on this path.
    const liveInfo = await this.houseLiveInfo(db);
    const seatOf = (p: HousePersona): SeatUser => ({
      id: p.userId,
      // Identity from the users table (admin edits from /mod/house), baked
      // constants as the fallback — same resolution as newHouseSeek.
      name: liveInfo.identity.get(p.userId)?.username ?? p.name,
      rating: liveInfo.byId.get(p.userId)?.[mode] ?? houseSeedRatingForMode(p, mode),
      rd: 150,
      vol: 0.06,
      avatar: liveInfo.identity.get(p.userId)?.avatar ?? p.avatar,
    });
    const match = await this.newHouseMatchRecord(
      { timeSec: tc.timeSec, incrementSec: tc.incrementSec },
      mode,
      {
        users: { w: seatOf(white), b: seatOf(black) },
        bots: { w: white.userId, b: black.userId },
      },
    );
    // Bot-vs-bot filler must never draft/play Chess Diff (a board-rewriting card
    // that breaks spectator reconstruction). Fold it into THIS match's draft-pool
    // `off` set so it is never offered in a filler draft, exactly like a
    // moderator-disabled card. This is the one path that applies the exclusion:
    // human-vs-bot pickups (pairHumanWithHouse) and human games go through the
    // same newHouseMatchRecord but keep the card, so only bot-only filler games
    // are affected.
    const off = new Set([...(match.cardOverrides?.off ?? []), ...FILLER_EXCLUDED_CARD_IDS]);
    match.cardOverrides = { ...(match.cardOverrides ?? {}), off: [...off] };
    // Nerf mode opens with the nerf draft (the house seats pick like anyone
    // else); Buff mode starts outright.
    if (mode !== "buff") {
      await this.beginNerfDraft(match);
      return;
    }
    const now = Date.now();
    match.startedAt = now;
    match.runningSince = now;
    this.armBotAction(match, null, now);
    // Buff mode: the opening pick's free lock-in window opens with the game.
    await this.openStartDraftWindow(match, now);
    await this.saveMatch(match);
  }

  // ---- Bot social responses: friend requests + direct challenges ----
  //
  // Bots have no client, so a friend request or a direct challenge addressed to
  // one would otherwise sit unanswered forever. This poll (throttled off the
  // alarm tick, never per tick) does what a real player's tap would: friend
  // requests flip to 'accepted' after a short humanlike beat; direct challenges
  // seat the bot in the waiting game and start it — unless the bot is already in
  // a live game, in which case the challenge is declined (the one-game-per-bot
  // rule). Every step is isolated so one bad row never blocks the rest, and both
  // the row scan and the number of accepts per poll are bounded.
  private async houseSocialTick(db: D1Database, busy: Set<string>, now: number): Promise<void> {
    const nextAt = (await this.ctx.storage.get<number>(houseNextSocialKey)) ?? 0;
    if (now < nextAt) return;
    await this.ctx.storage.put(houseNextSocialKey, now + houseSocialIntervalMs);
    await this.houseSeedFriendCohorts(db, now);
    let budget = houseSocialMaxAcceptsPerTick;
    budget = await this.houseAcceptFriendRequests(db, now, budget);
    if (budget > 0) await this.houseAnswerChallenges(db, busy, now, budget);
  }

  // Owner-configured friend cohorts: the named accounts hold N accepted house
  // friendships. Idempotent and resumable: each social tick tops one cohort up
  // by a bounded batch (INSERT OR IGNORE on the canonical pair key), and once
  // every cohort meets its target a storage flag ends the work for good. Reruns
  // after a version bump only ever ADD missing rows, never duplicate or remove.
  private async houseSeedFriendCohorts(db: D1Database, now: number): Promise<void> {
    const FLAG = "houseFriendCohortsDone:v1";
    if (await this.ctx.storage.get<boolean>(FLAG)) return;
    const COHORTS: { username: string; count: number }[] = [
      { username: "ilovenewjeans", count: 150 },
      { username: "ilovemyboyfriend", count: 50 },
      { username: "ilovemygirlfriend", count: 50 },
    ];
    const BATCH = 30;
    try {
      let allMet = true;
      for (const cohort of COHORTS) {
        const user = await db
          .prepare(`SELECT id FROM users WHERE LOWER(username) = ? LIMIT 1`)
          .bind(cohort.username.toLowerCase())
          .first<{ id: string }>();
        // A cohort whose account does not exist yet stays pending (the flag is
        // withheld), so it seeds automatically once the account is created.
        if (!user) {
          allMet = false;
          continue;
        }
        const existing = await db
          .prepare(
            `SELECT COUNT(*) AS n FROM friendships
             WHERE status = 'accepted' AND (user_lo = ? OR user_hi = ?)`,
          )
          .bind(user.id, user.id)
          .first<{ n: number }>();
        const have = existing?.n ?? 0;
        if (have >= cohort.count) continue;
        // Deterministically shuffled roster (seeded per cohort) so the picks
        // read random but reruns walk the same order and stay idempotent.
        const pool = [...HOUSE_ROSTER]
          .map((p) => ({ p, k: nameHash(`${cohort.username}:${p.userId}`) }))
          .sort((a, b) => a.k - b.k)
          .map(({ p }) => p);
        const missing = Math.min(cohort.count - have, BATCH);
        const statements: D1PreparedStatement[] = [];
        for (const persona of pool) {
          if (statements.length >= missing) break;
          if (persona.userId === user.id) continue;
          const [lo, hi] =
            persona.userId < user.id ? [persona.userId, user.id] : [user.id, persona.userId];
          // Jittered created_at so the roster does not read as one bulk import.
          const at = now - 3600_000 - nameHash(`${lo}:${hi}:at`) % (30 * 24 * 3600_000);
          statements.push(
            db
              .prepare(
                `INSERT OR IGNORE INTO friendships (user_lo, user_hi, requested_by, status, created_at)
                 VALUES (?, ?, ?, 'accepted', ?)`,
              )
              .bind(lo, hi, persona.userId, at),
          );
        }
        if (statements.length > 0) await db.batch(statements);
        // Counting again next tick decides whether this cohort is met; INSERT
        // OR IGNORE may have skipped rows that already existed as pending.
        allMet = false;
      }
      if (allMet) await this.ctx.storage.put(FLAG, true);
    } catch (err) {
      console.error("house friend cohort seeding failed", err);
    }
  }

  // The persona's current display name (an admin rename from /mod/house lands in
  // the cached identity map), falling back to the baked constant.
  private houseDisplayName(userId: string): string {
    return this.houseRatingsCache?.identity.get(userId)?.username ?? housePersona(userId)?.name ?? "A player";
  }

  // Canonical seat identity for an ARENA game, read from the house-ratings
  // cache rather than the arena's payload.
  //
  // The arena service has no database. Its seat rating is a compile-time
  // constant, houseSeedRating(persona), baked from the persona's name and skill
  // (arena-service/game.ts). Shipping that number straight to TV is why a bot
  // could read 2600 on TV and 2300 on its own profile: the profile reads
  // user_ratings, and nothing ever reconciled the two. refreshSeatRatings does
  // exactly this reconciliation for real DO matches but is never called for
  // external ones. The constant is also numerically the frozen legacy
  // users.rating column that ratingSql.ts already calls out as the root of the
  // "ratings don't match between pages" reports.
  //
  // A moderator rating override, a roster revision that reached one deploy and
  // not the other, or simply the account playing rated games all widen the gap
  // without bound, so the arena number can never be trusted. The same applies
  // to the NAME: the DO heals renames for its own seats, and this is the
  // equivalent for external replicas.
  //
  // Synchronous read of the cached map (same pattern as the username lookup
  // above) so the sync snapshot builders do not have to become async; the cache
  // is refreshed by houseTick and warmed on the lobby path. Returns undefined
  // per field when the cache has nothing, and callers keep the arena value as
  // the fallback.
  private arenaSeatIdentity(
    userId: string,
    mode: DraftMode | undefined,
  ): { rating?: number; username?: string } {
    const cache = this.houseRatingsCache;
    if (!cache) return {};
    const byMode = cache.byId.get(userId);
    return {
      rating: byMode?.[mode ?? "nerf"],
      username: cache.identity.get(userId)?.username,
    };
  }

  // Insert a bell notification. A local mirror of social.ts's createNotification
  // so the DO never imports the next/server-based social module.
  private async houseNotify(
    db: D1Database,
    userId: string,
    actorName: string,
    text: string,
    href: string,
    // The acting house persona's user id. Stored as actor_user_id so the
    // notifications read path (/api/notifications) resolves the CURRENT username
    // live and rewrites the frozen actor_name in the row's text — a bot renamed
    // after the notification was sent shows its new name in the bell instead of
    // the stale one, matching how human-actor notifications already self-heal.
    actorUserId: string | null = null,
  ): Promise<void> {
    try {
      await db
        .prepare(
          `INSERT INTO notifications (id, user_id, type, actor_user_id, actor_name, text, href, created_at, read)
           VALUES (?, ?, 'message', ?, ?, ?, ?, ?, 0)`,
        )
        .bind(crypto.randomUUID(), userId, actorUserId, actorName, text, href, Date.now())
        .run();
    } catch {
      // A missed notification must never fail the social write it accompanies.
    }
  }

  // Accept pending friend requests addressed to a house persona once the request
  // has aged past its (deterministic, per-request) humanlike delay. Returns the
  // remaining accept budget.
  private async houseAcceptFriendRequests(db: D1Database, now: number, budget: number): Promise<number> {
    let rows: D1Result<{ user_lo: string; user_hi: string; requested_by: string; created_at: number }>;
    try {
      rows = await db
        .prepare(
          `SELECT user_lo, user_hi, requested_by, created_at FROM friendships
           WHERE status = 'pending' ORDER BY created_at ASC LIMIT 50`,
        )
        .all<{ user_lo: string; user_hi: string; requested_by: string; created_at: number }>();
    } catch {
      return budget;
    }
    for (const r of rows.results) {
      if (budget <= 0) break;
      // The bot is whichever side is a house id; the requester must be the human.
      // (Bots never send requests, so a house `requested_by` is not ours to
      // answer — skip it rather than "accept" a request nobody made.)
      const botId = isHouseUserId(r.user_lo) ? r.user_lo : isHouseUserId(r.user_hi) ? r.user_hi : null;
      if (!botId || r.requested_by === botId || isHouseUserId(r.requested_by)) continue;
      const seed = `friend:${r.user_lo}:${r.user_hi}:${r.created_at}`;
      if (now - r.created_at < houseSocialDelayMs(seed)) continue;
      try {
        await db
          .prepare(
            `UPDATE friendships SET status = 'accepted'
             WHERE user_lo = ? AND user_hi = ? AND status = 'pending'`,
          )
          .bind(r.user_lo, r.user_hi)
          .run();
        const name = this.houseDisplayName(botId);
        await this.houseNotify(db, r.requested_by, name, `${name} accepted your friend request`, "/friend", botId);
        budget--;
      } catch (err) {
        console.error("house friend accept failed", botId, err);
      }
    }
    return budget;
  }

  // Accept or decline pending direct challenges addressed to a house persona,
  // once aged past the humanlike delay. Accept = seat the bot in the waiting
  // game and start it; decline = the bot is busy (one game per bot) or the
  // waiting game is gone/host left, so the challenge stops hanging to its TTL.
  private async houseAnswerChallenges(
    db: D1Database,
    busy: Set<string>,
    now: number,
    budget: number,
  ): Promise<number> {
    let rows: D1Result<{ id: string; from_user_id: string; to_user_id: string; created_at: number }>;
    try {
      rows = await db
        .prepare(
          `SELECT id, from_user_id, to_user_id, created_at FROM challenges
           WHERE status = 'pending' AND created_at > ? ORDER BY created_at ASC LIMIT 50`,
        )
        .bind(now - houseChallengeTtlMs)
        .all<{ id: string; from_user_id: string; to_user_id: string; created_at: number }>();
    } catch {
      return budget;
    }
    for (const r of rows.results) {
      if (budget <= 0) break;
      // Only challenges FROM a human TO a bot are ours to answer.
      if (!isHouseUserId(r.to_user_id) || isHouseUserId(r.from_user_id)) continue;
      const persona = housePersona(r.to_user_id);
      if (!persona) continue;
      const seed = `challenge:${r.id}:${r.created_at}`;
      if (now - r.created_at < houseSocialDelayMs(seed)) continue;

      // One game per bot: a persona already in a live game declines gracefully
      // instead of double-booking. `busy` is this tick's live-seat set, updated
      // as we seat so two challenges in one poll can't both grab the same bot.
      let outcome: "seated" | "gone" | "retry" | "busy" = busy.has(persona.userId) ? "busy" : "gone";
      if (outcome !== "busy") {
        try {
          outcome = await this.houseSeatChallenge(db, r.id, persona);
        } catch (err) {
          console.error("house challenge seat failed", r.id, err);
          outcome = "retry";
        }
      }
      // A transient failure leaves the row pending for the next poll; a real
      // outcome commits.
      if (outcome === "retry") continue;
      try {
        if (outcome === "seated") {
          busy.add(persona.userId);
          await db
            .prepare(`UPDATE challenges SET status = 'accepted' WHERE id = ? AND status = 'pending'`)
            .bind(r.id)
            .run();
        } else {
          await db
            .prepare(`UPDATE challenges SET status = 'declined' WHERE id = ? AND status = 'pending'`)
            .bind(r.id)
            .run();
        }
        budget--;
      } catch (err) {
        console.error("house challenge resolve failed", r.id, err);
      }
    }
    return budget;
  }

  // Seat a persona as black in the waiting challenge game `code` and start it,
  // mirroring joinMatch's start path (a house seat has no socket but counts as
  // arrived). Returns "seated" on success, "gone" when the waiting game is no
  // longer joinable (missing/started/host left/black taken), or "retry" on a
  // transient failure that should be re-attempted next poll.
  private async houseSeatChallenge(
    db: D1Database,
    code: string,
    persona: HousePersona,
  ): Promise<"seated" | "gone" | "retry"> {
    const match = await this.loadMatch(code);
    if (!match || match.result) return "gone";
    // Must still be an open, unstarted challenge with a present host and a free
    // black seat.
    if (match.startedAt || match.nerfOptions) return "gone";
    if (!this.connectedSession(code, "w")) return "gone"; // host navigated away
    if (match.bots?.b || this.connectedSession(code, "b")) return "gone"; // already taken
    const cat = this.matchRatingCategory(match);
    let seat: SeatUser;
    try {
      const row = await this.seatCategoryRating(db, persona.userId, cat);
      seat = row
        ? {
            id: persona.userId,
            name: row.username ?? persona.name,
            rating: row.rating,
            rd: row.rd,
            vol: row.vol,
            avatar: row.avatar ?? persona.avatar,
          }
        : {
            id: persona.userId,
            name: persona.name,
            // Seed the SAME per-mode number houseSeatUser uses (the bucket this
            // game is rated in), not the mode-neutral base — otherwise a bot's
            // advertised rating in a challenge could differ from the number the
            // rest of the site shows for that mode. Non-mode (classic/speed)
            // challenges have no per-mode seed, so fall back to the base.
            rating: isModeCategory(cat) ? houseSeedRatingForMode(persona, cat) : houseSeedRating(persona),
            rd: 150,
            vol: 0.06,
            avatar: persona.avatar,
          };
    } catch {
      return "retry";
    }
    match.bots = { ...(match.bots ?? {}), b: persona.userId };
    match.users = { ...(match.users ?? {}), b: seat };
    // Bring the host's seat rating (snapshotted at challenge creation) current,
    // exactly like joinMatch does before the start frames go out.
    await this.refreshSeatRatings(match, ["w"]);
    // Draft games open with the opening nerf draft (buff mode skips it); a plain
    // game starts outright.
    if (match.draft && match.mode !== "buff") {
      await this.beginNerfDraft(match);
      return "seated";
    }
    const now = Date.now();
    match.startedAt = now;
    match.runningSince = now;
    this.armBotAction(match, null, now);
    // Buff mode: the opening pick's free lock-in window opens with the game.
    await this.openStartDraftWindow(match, now);
    await this.saveMatch(match);
    this.sendStart(match, "w");
    this.sendStart(match, "b");
    return "seated";
  }

  // ---- Arena ingestion (Tier 2 / M2) ----
  // The OCI arena runs bot-vs-bot games and POSTs here: /arena/games (periodic
  // registry of its live games, for lobby/TV) and /arena/end (a finished game,
  // to archive + rate). Auth via ARENA_INGEST_TOKEN. Gated by ARENA_INGEST_ENABLED
  // (archive+rating) and ARENA_LOBBY_ENABLED (visibility), so it ships dark.
  private async handleArena(request: Request, url: URL): Promise<Response> {
    if (request.method !== "POST") return new Response("method not allowed", { status: 405 });
    const token = this.env.ARENA_INGEST_TOKEN;
    // Timing-safe compare: a plain !== short-circuits on the first differing
    // byte, which lets the bearer token be probed off response timing.
    if (!token || !timingSafeEqual(request.headers.get("authorization") ?? "", `Bearer ${token}`)) {
      return new Response("unauthorized", { status: 401 });
    }
    const ingest = this.env.ARENA_INGEST_ENABLED === "true";
    // The arena should spawn only when ingestion is on AND a human is present to
    // see the lobby (mirror the DO's own stand-down). Told to the arena so it
    // pauses otherwise. MUST be sitePresence(), the same signal houseTick
    // stands down on: lobby browsers no longer hold a WebSocket, so the old
    // bare humanSocketCount() check told the arena to pause exactly while
    // people were looking at the lobby — with ARENA_OWNS_FILLER on, that meant
    // no bot-vs-bot games ever showed for a browsing viewer (the DO's own
    // seeks/pickup kept working off sitePresence, which is why bots still
    // accepted queued humans while the "TV" sat empty).
    const enabled = ingest && this.sitePresence();

    if (url.pathname === "/arena/games") {
      // Liveness stamp for the filler-ownership fallback (houseTick): an
      // authenticated sync proves the arena process is up, whatever it carries.
      this.lastArenaSyncAt = Date.now();
      let body: { games?: ExternalGameMeta[] };
      try {
        body = (await request.json()) as { games?: ExternalGameMeta[] };
      } catch {
        return Response.json({ error: "bad_json" }, { status: 400 });
      }
      if (ingest) {
        const now = Date.now();
        const next = new Map<string, { meta: ExternalGameMeta; at: number }>();
        for (const g of body.games ?? []) {
          // Only house accounts may be projected — a forged id can never inject
          // a fake game for a real user.
          if (!g || !isHouseUserId(g.seats?.w?.userId) || !isHouseUserId(g.seats?.b?.userId)) continue;
          next.set(g.id, { meta: g, at: now });
        }
        this.externalGames = next;
        // Stamp only when the sync carried a usable game (post-filter): this is
        // what keeps ARENA_OWNS_FILLER honored (see houseTick). An empty or
        // fully-filtered sync deliberately does NOT count as supply.
        if (next.size > 0) this.lastArenaGamesAt = now;
      } else {
        this.externalGames.clear();
      }
      const lobby = this.env.ARENA_LOBBY_ENABLED === "true";
      // Tell the arena which of its games a human is spectating so it streams
      // per-move frames for those only (Tier 2 / M3). Empty unless the lobby is
      // on (you can only watch a game the lobby surfaced).
      const watch = ingest && lobby ? this.externalWatchedIds() : [];
      return Response.json({ enabled, lobby, watch });
    }

    if (url.pathname === "/arena/frame") {
      // Spectator relay (Tier 2 / M3). Advance the watched game's replica and
      // fan the event out to its watchers. Gated by ingest + lobby; a frame for
      // an unknown/unwatched game is a harmless no-op.
      if (!ingest || this.env.ARENA_LOBBY_ENABLED !== "true") return Response.json({ ok: false, ingest: false });
      let body: { frame?: ArenaFrame };
      try {
        body = (await request.json()) as { frame?: ArenaFrame };
      } catch {
        return Response.json({ error: "bad_json" }, { status: 400 });
      }
      const frame = body.frame;
      if (!frame || typeof frame.id !== "string") return Response.json({ error: "bad_frame" }, { status: 400 });
      try {
        if (frame.kind === "snapshot") this.ingestExternalSnapshot(frame);
        else if (frame.kind === "move") this.applyExternalMove(frame.id, frame.ply, frame.u, frame.clocks);
        else if (frame.kind === "draft") this.applyExternalDraft(frame.id, frame.action, frame.card);
      } catch (err) {
        console.error("arena frame failed", frame.id, err);
        return Response.json({ ok: false, reason: "frame_failed" });
      }
      return Response.json({ ok: true });
    }

    if (url.pathname === "/arena/end") {
      if (!ingest) return Response.json({ ok: false, ingest: false });
      let body: { record?: ArenaEndRecord; aborted?: boolean };
      try {
        body = (await request.json()) as { record?: ArenaEndRecord; aborted?: boolean };
      } catch {
        return Response.json({ error: "bad_json" }, { status: 400 });
      }
      const rec = body.record;
      if (!rec || !isHouseUserId(rec.bots?.w) || !isHouseUserId(rec.bots?.b)) {
        return Response.json({ error: "bad_record" }, { status: 400 });
      }
      this.externalGames.delete(rec.id);
      // Spectators (if any) see the game end with the revealed nerfs + held
      // buffs, then the replica is dropped (Tier 2 / M3).
      this.endExternalForWatchers(rec);
      if (body.aborted) return Response.json({ ok: true, aborted: true });
      // Archive + RATE the finished bot-vs-bot game, exactly like the Tier 3
      // /api/arena/end route (owner directive 2026-07-22: bot games ARE
      // rated). In production the arena normally posts ends to that route
      // (ARENA_END_URL), so this path is the fallback for an arena configured
      // without it — without recording here, losing that one env var made bot
      // ratings silently freeze. recordFinishedGame is idempotent per game id
      // (recorded_games ledger), so even a double-post through both paths
      // applies the rating exactly once. A malformed record from an older
      // arena bundle skips recording but still delivers the end frame above.
      if (rec.setup && Array.isArray(rec.moves) && rec.result) {
        const db = await this.db();
        if (db) {
          try {
            await recordFinishedGame(
              db,
              {
                id: rec.id,
                whiteUserId: rec.bots.w,
                blackUserId: rec.bots.b,
                whiteName: rec.seats?.w?.name ?? "Anonymous",
                blackName: rec.seats?.b?.name ?? "Anonymous",
                whiteNerfId: rec.setup.whiteNerfId,
                blackNerfId: rec.setup.blackNerfId,
                seed: rec.setup.seed,
                timeSec: rec.setup.timeSec,
                incrementSec: rec.setup.incrementSec,
                moves: rec.moves,
                winner: rec.result.winner,
                reason: rec.result.reason,
                rated: true,
                ruleset: "draft",
                ratingCategory: rec.mode,
                ...(rec.draftSeed !== undefined && rec.draftActions
                  ? {
                      draftRecord: {
                        mode: rec.mode,
                        draftSeed: rec.draftSeed,
                        ...(rec.cadence !== undefined ? { cadence: rec.cadence } : {}),
                        draftActions: rec.draftActions,
                      },
                    }
                  : {}),
                replayVersion: rec.replayVersion,
                startedAt: rec.startedAt,
                completedAt: rec.completedAt,
              },
              this.env.HYPERDRIVE?.connectionString,
            );
          } catch (err) {
            console.error("arena end record failed", rec.id, err);
            return Response.json({ ok: false, reason: "record_failed" });
          }
        }
      }
      return Response.json({ ok: true });
    }

    return new Response("not found", { status: 404 });
  }

  // ---- Arena spectating (Tier 2 / M3) ----

  // Distinct arena game ids a human is currently watching. Told to the arena so
  // it streams per-move frames for these only.
  private externalWatchedIds(): string[] {
    const ids = new Set<string>();
    for (const [ws, s] of this.sessions) {
      if (ws.readyState === WebSocket.OPEN && s.watching && this.externalGames.has(s.watching)) ids.add(s.watching);
    }
    return [...ids];
  }

  // Relay a frame to every socket watching a given game id (the by-id twin of
  // sendWatchers, which keys off a StoredMatch).
  private sendWatchersById(id: string, t: string, d?: unknown) {
    for (const [ws, session] of this.sessions) {
      if (session.watching === id && ws.readyState === WebSocket.OPEN) send(ws, t, d);
    }
  }

  // Build the ephemeral replica StoredMatch for a watched arena game from the
  // arena's snapshot. Shaped exactly like a house-vs-house match so every
  // existing spectator helper (gameFromMatch, draftStateFor, publicDraftActions,
  // playersPayload, currentClocks) works on it unchanged. Never persisted.
  private buildExternalMatch(snap: ArenaSnapshot): StoredMatch {
    const seatUser = (s: ExternalSeat): SeatUser => {
      // Canonical rating and name from user_ratings, never the arena's baked
      // constant (see resolveArenaSeat).
      const resolved = resolveArenaSeat(s, this.arenaSeatIdentity(s.userId, snap.mode));
      return {
        id: s.userId,
        name: resolved.name,
        rating: resolved.rating,
        // HOUSE_SEED_RD, not a made-up 150. House accounts seed settled and are
        // never provisional anywhere else, but 150 is above PROVISIONAL_RD (110)
        // so playersPayload flagged every arena bot provisional and TV drew a
        // "?" beside a rating the bot has had for hundreds of games.
        rd: HOUSE_SEED_RD,
        vol: 0.06,
        avatar: housePersona(s.userId)?.avatar ?? null,
      };
    };
    const now = Date.now();
    return {
      id: snap.id,
      setup: {
        whiteNerfId: snap.setup.whiteNerfId,
        blackNerfId: snap.setup.blackNerfId,
        seed: snap.setup.seed,
        timeSec: snap.setup.timeSec,
        incrementSec: snap.setup.incrementSec,
      },
      tokens: { w: "", b: "" },
      disconnectedAt: {},
      opponentGoneNotified: {},
      moves: [...snap.moves],
      result: null,
      clocks: { w: snap.clocks.w, b: snap.clocks.b },
      runningSince: snap.startedAt ? now : null,
      drawOfferBy: null,
      createdAt: snap.startedAt || now,
      startedAt: snap.startedAt || null,
      completedAt: null,
      replayVersion: REPLAY_VERSION,
      rated: true,
      autoStart: true,
      users: { w: seatUser(snap.seats.w), b: seatUser(snap.seats.b) },
      draft: true,
      mode: snap.mode,
      picksVisible: false,
      cadence: snap.cadence,
      draftSeed: snap.draftSeed,
      draftActions: [...snap.draftActions],
      bots: { w: snap.seats.w.userId, b: snap.seats.b.userId },
    };
  }

  // A started snapshot arrived: (re)build the replica and bootstrap every socket
  // already waiting on this game with a wstart (they watched before the arena
  // began streaming). Ignored for pre-start games — the DO can't reconstruct a
  // board whose nerfs are still hidden, so those spectators keep waiting.
  private ingestExternalSnapshot(snap: ArenaSnapshot) {
    if (!isHouseUserId(snap.seats?.w?.userId) || !isHouseUserId(snap.seats?.b?.userId)) return;
    if (!snap.startedAt) return;
    const match = this.buildExternalMatch(snap);
    this.externalMatches.set(snap.id, match);
    this.externalFrameAt.set(snap.id, Date.now());
    // A fresh snapshot replaces the move/action arrays, so any cached replay is
    // stale — drop it and let the next frame rebuild from this snapshot.
    this.externalReplay.delete(snap.id);
    // Seed turnColor from the replayed board, not move parity: in a draft game
    // buff activations and tempo cards move the turn off parity, so a snapshot
    // that lands mid-game would otherwise leave activeColor charging the wrong
    // seat's clock — every 10s heartbeat then re-sent the real on-turn clock at
    // its full banked value (the spectator "clock bounces back up" bug). The
    // replay also warms the incremental cache the first frame would build.
    try {
      const game = this.syncExternalGame(match);
      if (game) match.turnColor = game.board.turn;
    } catch {}
    for (const [ws, session] of this.sessions) {
      if (session.watching === snap.id && ws.readyState === WebSocket.OPEN) this.sendWstart(ws, match);
    }
  }

  // The watched replica's game, advanced to match its current move/action
  // arrays. Reuses the cached replay and steps it forward by only the new
  // frames (O(1) per frame in steady state); rebuilds fully from ply 1 on a
  // cache miss or any inconsistency, so it produces exactly what a full
  // gameFromMatch replay would. Leaves this.draftRebuild pointed at the cached
  // reveal/acquire state so draftStateFor/publicDraftActions see the right
  // spectator reveals for this game's buff instances.
  private syncExternalGame(match: StoredMatch): NerfGame | null {
    if (!match.startedAt) return null;
    const actions = match.draftActions ?? [];
    let entry = this.externalReplay.get(match.id);
    // Cache is unusable if absent or somehow ahead of the record (a re-snapshot
    // rewound the arrays): rebuild from scratch via the shared replay.
    if (!entry || entry.moves > match.moves.length || entry.cursor > actions.length) {
      const game = this.gameFromMatch(match); // full replay; sets this.draftRebuild
      if (!game) {
        this.externalReplay.delete(match.id);
        return null;
      }
      const rebuild =
        this.draftRebuild?.matchId === match.id
          ? { revealed: this.draftRebuild.revealed, acquired: this.draftRebuild.acquired }
          : { revealed: new Set<BuffInstance>(), acquired: new Map<number, BuffInstance[]>() };
      // gameFromMatch applied every action with ply <= moves.length.
      const cursor = actions.reduce((n, a) => (a.ply <= match.moves.length ? n + 1 : n), 0);
      entry = { game, moves: match.moves.length, cursor, rebuild };
      this.externalReplay.set(match.id, entry);
      return entry.game;
    }
    // Install the cached reveal state for the incremental step and for the
    // draftStateFor/publicDraftActions the caller runs right after.
    this.draftRebuild = { matchId: match.id, revealed: entry.rebuild.revealed, acquired: entry.rebuild.acquired };
    setDraftPoolOverrides(match.draft ? match.cardOverrides ?? null : null);
    try {
      const applyActionsUpTo = (ply: number) => {
        while (entry!.cursor < actions.length && actions[entry!.cursor].ply <= ply) {
          this.applyStoredDraftAction(entry!.game, actions[entry!.cursor], entry!.cursor);
          entry!.cursor += 1;
        }
      };
      for (let i = entry.moves; i < match.moves.length; i++) {
        applyActionsUpTo(i);
        const move = moveByUci(entry.game, match.moves[i]);
        if (!move) {
          // Desync (a lost or reordered frame): drop the cache and rebuild from
          // the authoritative arrays, exactly what full replay would do.
          this.externalReplay.delete(match.id);
          return this.syncExternalGame(match);
        }
        if (match.draft) this.markViaRevealed(entry.game, move);
        entry.game = playMove(entry.game, move);
      }
      applyActionsUpTo(match.moves.length);
      entry.moves = match.moves.length;
      if (match.result) entry.game.result = match.result;
      return entry.game;
    } finally {
      setDraftPoolOverrides(null);
    }
  }

  // Advance a watched game's replica by one move and relay it. syncExternalGame
  // advances the cached replay so turn + spectator reveals stay exact (the same
  // result a full replay gives, without the per-frame O(n) cost), so a freshly
  // revealed passive reaches watchers via dtState. No `end` here — /arena/end
  // sends it with the ratings.
  private applyExternalMove(id: string, ply: number, uci: string, clocks: Record<Color, number>) {
    const match = this.externalMatches.get(id);
    if (!match || match.result) return;
    this.externalFrameAt.set(id, Date.now());
    // Apply only the next expected move (mirrors the client's own ply check): a
    // stale/duplicate frame that raced the bootstrap snapshot is dropped, not
    // double-applied. A gap (frame lost) leaves the replica where it is.
    if (typeof ply === "number" && ply !== match.moves.length + 1) return;
    // Rebuild the PRE-move game and run the move through the engine here, so
    // hidden passives that granted the move (via) or fired on it (a capture
    // detonation) are revealed to watchers BEFORE the move frame, exactly
    // like commitMove: a spectator replica applying the move without the
    // card's identity would desync its board, and dtState cannot repair a
    // board. The rebuild count is unchanged (pre-move instead of post-move).
    let game: NerfGame | null = null;
    try {
      game = this.syncExternalGame(match);
    } catch {}
    // Whose move this is, read off the PRE-move replica (game is reassigned to
    // the post-move state below). Null when the replica could not be rebuilt,
    // in which case movesByColor keeps its legacy parity estimate.
    const mover: Color | null = game && !game.result ? game.board.turn : null;
    if (game && !game.result) {
      const move = moveByUci(game, uci);
      if (move && match.draft && game.buffs) {
        if (this.markViaRevealed(game, move)) this.sendWatcherDraftStateById(id, match, game);
        const preBuffs = JSON.parse(JSON.stringify(game.buffs)) as BuffMatchState;
        setDraftPoolOverrides(match.cardOverrides ?? null);
        try {
          game = playMove(game, move);
        } finally {
          setDraftPoolOverrides(null);
        }
        if (this.revealFiredHooks(game, preBuffs)) {
          this.sendWatcherDraftStateById(id, match, { buffs: preBuffs } as unknown as NerfGame);
        }
      } else {
        game = move ? playMove(game, move) : null;
      }
    }
    if (mover) this.countMove(match, mover);
    match.moves.push(uci);
    if (clocks && typeof clocks.w === "number" && typeof clocks.b === "number") {
      match.clocks = { w: clocks.w, b: clocks.b };
    }
    if (game) {
      match.turnColor = game.board.turn;
      if (game.result) match.result = game.result;
    }
    match.runningSince = match.result ? null : Date.now();
    this.sendWatchersById(id, "move", {
      u: uci,
      ply: match.moves.length,
      wc: Math.round(match.clocks.w),
      bc: Math.round(match.clocks.b),
      ...(game ? { f: fnv1a(positionKey(game.board)) } : {}),
    });
    if (game?.buffs) {
      const state = this.draftStateFor(game, match, "spectator");
      if (state) this.sendWatchersById(id, "dtState", { state });
    }
  }

  // Spectator-filtered dtState for an arena-relayed match id.
  private sendWatcherDraftStateById(id: string, match: StoredMatch, game: NerfGame) {
    const state = this.draftStateFor(game, match, "spectator");
    if (state) this.sendWatchersById(id, "dtState", { state });
  }

  // Advance a watched game's replica by one draft action and relay the
  // spectator-filtered frame, reusing the exact masking the native path uses
  // (publicDraftActions for a pick, the fired card for a use).
  private applyExternalDraft(id: string, action: StoredDraftAction, card?: { id: string; tier: number }) {
    const match = this.externalMatches.get(id);
    if (!match || match.result) return;
    this.externalFrameAt.set(id, Date.now());
    match.draftActions = [...(match.draftActions ?? []), action];
    let game: NerfGame | null = null;
    try {
      game = this.syncExternalGame(match);
    } catch {}
    if (game) {
      match.turnColor = game.board.turn;
      if (game.result) match.result = game.result;
    }
    if (action.a === "use") {
      this.sendWatchersById(id, "dtUsed", {
        color: action.color,
        buffIndex: action.buffIndex,
        picks: action.picks,
        ...(card ? { card } : {}),
      });
    } else if (action.a === "pick") {
      const masked = this.publicDraftActions(match, "spectator");
      const last = masked[masked.length - 1];
      const cards = last && last.a === "pick" ? last.cards : [];
      this.sendWatchersById(id, "dtResolved", { color: action.color, kind: "picked", cards });
    } else if (action.a === "bank") {
      this.sendWatchersById(id, "dtResolved", { color: action.color, kind: "banked" });
    }
    // A reroll (native games only) sends no dtResolved: the dtState resync
    // below carries the fresh offer. Arena games never reroll.
    if (game?.buffs) {
      const state = this.draftStateFor(game, match, "spectator");
      if (state) this.sendWatchersById(id, "dtState", { state });
    }
  }

  // Send one spectator their opening wstart from a (replica or native) match.
  // Factored out of watchMatch so an external snapshot can flush it to sockets
  // that were waiting for the arena to start streaming.
  private sendWstart(ws: WebSocket, match: StoredMatch) {
    const id = match.id;
    const clocks = this.currentClocks(match);
    let draftExtras: Record<string, unknown> | null = null;
    if (match.draft) {
      const game = match.startedAt ? this.gameFromMatch(match) : null;
      draftExtras = {
        draft: true,
        ...(match.mode ? { mode: match.mode } : {}),
        dtActions: this.publicDraftActions(match, "spectator"),
        ...(game?.buffs ? { dtState: this.draftStateFor(game, match, "spectator") } : {}),
      };
    }
    // Ship the authoritative PUBLIC snapshot so the spectator joins AT the
    // current revision and applies only later-seq envelopes -- a join at move
    // 300 never replays from move 1. Built on demand for legacy/live records
    // that predate the snapshot. Absent (null) only when the game cannot be
    // reconstructed; a migration stage turns that into a structured notice
    // rather than a false starting board. The moves array stays for older
    // clients that ignore `pub`.
    //
    // The BASELINE (seq + publicHash) must describe what this payload actually
    // carries, which is the LIVE state: `moves` / `dtActions` are current, and
    // that is what the client rebuilds its board from. `pubSnap` is only
    // rebuilt on the checkpoint cadence (every checkpointEveryPlies events) or
    // on force, so `pub.seq` can trail `match.seq` by up to that many plies.
    // Baselining on the trailing value made the very next live frame look like
    // a GAP: the client buffered it, the 1.5s sweep re-issued watch(), the
    // server handed back the same stale snapshot, and the spectator view
    // remounted in a loop until the next checkpoint. `match.seqHash` is
    // refreshed on every event (bumpPublicSnapshot), so it is the hash that
    // matches the live board for parity too.
    const pub = this.ensurePubSnap(match);
    const baselineSeq = match.seq ?? pub?.seq ?? match.moves.length;
    send(ws, "wstart", {
      id,
      timeSec: match.setup.timeSec,
      incrementSec: match.setup.incrementSec,
      wc: Math.round(clocks.w),
      bc: Math.round(clocks.b),
      moves: match.moves,
      players: this.playersPayload(match),
      rated: !!match.rated,
      started: !!match.startedAt,
      result: match.result,
      watchers: this.watcherCount(id),
      watcherNames: this.watcherInfo(id).names,
      spectatorChat: match.spectatorChat ?? [],
      ...(match.result ? { nerfs: { w: match.setup.whiteNerfId, b: match.setup.blackNerfId } } : {}),
      ...(draftExtras ?? {}),
      ...(pub
        ? {
            pub: pub.snap,
            seq: baselineSeq,
            schemaVersion: pub.schemaVersion,
            replayVersion: pub.replayVersion,
            publicHash: match.seqHash ?? pub.hash,
          }
        : {}),
    });
  }

  // A watched arena game finished: reveal nerfs + held buffs to its spectators
  // with the result, then drop the replica. Rebuilds the game from the
  // authoritative end record so held buffs are exact even if a mid-game frame
  // was dropped.
  private endExternalForWatchers(rec: ArenaEndRecord) {
    const match = this.externalMatches.get(rec.id);
    this.externalMatches.delete(rec.id);
    this.externalReplay.delete(rec.id);
    this.externalFrameAt.delete(rec.id);
    if (!match) return; // nobody was watching
    match.moves = [...rec.moves];
    if (rec.draftActions) match.draftActions = [...rec.draftActions];
    match.result = rec.result;
    let draftBuffs: Record<Color, { id: string; tier: number; spent?: boolean; nullified?: boolean }[]> | null = null;
    try {
      const game = this.gameFromMatch(match);
      if (game?.buffs) {
        const held = (color: Color) =>
          game.buffs!.players[color].buffs.map((b) => ({
            id: b.id,
            tier: b.tier as number,
            ...(b.spent ? { spent: true } : {}),
            ...(b.nullified ? { nullified: true } : {}),
          }));
        draftBuffs = { w: held("w"), b: held("b") };
      }
    } catch {}
    this.sendWatchersById(rec.id, "end", {
      result: rec.result,
      wc: Math.round(match.clocks.w),
      bc: Math.round(match.clocks.b),
      nerfs: { w: rec.setup.whiteNerfId, b: rec.setup.blackNerfId },
      ...(draftBuffs ? { draftBuffs } : {}),
    });
  }

  // How far past flag-fall a replica's active clock may run before the watchdog
  // ends it: the arena itself flags a game within a couple seconds, so this only
  // trips when the arena is gone, while comfortably absorbing frame latency.
  private static readonly EXTERNAL_FLAG_SLACK_MS = 15 * 1000;
  // How long a watched replica may go without ANY arena frame before it is
  // considered stranded (paired with a second signal below — silence alone is
  // not enough, since a bot on a long clock may legitimately think a while).
  private static readonly EXTERNAL_SILENCE_MS = 2 * 60 * 1000;

  // Watchdog for stranded arena replicas (Tier 2 / M3). Only /arena/end ends a
  // replica — finishOnFlag and loadMatch never see externalMatches — so an
  // arena that dies mid-game (or an old bundle that aborted without an end
  // frame) left its watchers on a board that never moves again, with the clock
  // frame "bouncing" forever: the reported TV stall. Two conservative
  // tripwires, checked from the maintenance sweep:
  //   1. Flag fall: the active clock ran out well past a slack window and no
  //      frame came — the arena would have ended the game itself long ago.
  //   2. Silence: no frame at all for a generous window while one was clearly
  //      due (the replica already holds a result but the end frame was lost,
  //      or the clock is not running so no flag can ever fall).
  // Either way the game ends for its watchers and the replica drops. Nothing
  // is archived or rated from here — a false positive costs one spectator an
  // early end frame, never a bogus record.
  private sweepExternalReplicas(now: number) {
    for (const [id, match] of [...this.externalMatches]) {
      // Watcherless replicas normally drop on leave/close; this catches a
      // socket that vanished without either event firing.
      this.dropExternalIfUnwatched(id);
      if (!this.externalMatches.has(id)) continue;
      const active = this.chargedColor(match);
      // How far past exhausting its whole banked clock the active side is
      // (null when no flag can fall: untimed, unstarted, or paused clock).
      const overdueBy =
        match.setup.timeSec && match.startedAt && !match.result && match.runningSince !== null
          ? now -
            match.runningSince -
            (this.movesByColor(match, active) === 0 ? firstMoveGraceMs : 0) -
            match.clocks[active]
          : null;
      const silentFor = now - (this.externalFrameAt.get(id) ?? match.createdAt);
      const flagged = overdueBy !== null && overdueBy > GameServer.EXTERNAL_FLAG_SLACK_MS;
      const stale =
        silentFor > GameServer.EXTERNAL_SILENCE_MS && (match.result !== null || overdueBy === null);
      if (!flagged && !stale) continue;
      const result =
        match.result ??
        (flagged
          ? {
              winner: (active === "w" ? "b" : "w") as Color,
              reason: active === "w" ? "white ran out of time" : "black ran out of time",
            }
          : { winner: null, reason: "connection to game lost" });
      console.error(
        "external replica stranded, ending for watchers",
        id,
        JSON.stringify({ flagged, stale, silentFor, overdueBy }),
      );
      // Also drop the lobby listing so a dead game cannot be re-watched (the
      // TTL filter would age it out anyway; this just makes it immediate).
      this.externalGames.delete(id);
      this.endExternalForWatchers({
        id,
        setup: match.setup,
        mode: match.mode ?? "nerf",
        moves: [...match.moves],
        bots: { w: match.bots?.w ?? "", b: match.bots?.b ?? "" },
        seats: { w: { name: match.users?.w?.name ?? "?" }, b: { name: match.users?.b?.name ?? "?" } },
        result,
        startedAt: match.startedAt ?? 0,
        completedAt: now,
        draftSeed: match.draftSeed,
        cadence: match.cadence,
        draftActions: match.draftActions,
      });
    }
  }

  // Fresh (non-expired) arena games as lobby liveGames entries (Tier 2 / M2).
  private externalLiveGames(now: number): Array<{
    id: string;
    origin: "arena";
    players: ReturnType<GameServer["playersPayload"]>;
    rated: boolean;
    draft: boolean;
    mode?: DraftMode;
    timeSec: number;
    incrementSec: number;
    moves: number;
    watchers: number;
  }> {
    if (this.env.ARENA_LOBBY_ENABLED !== "true") return [];
    const games = [];
    for (const { meta, at } of this.externalGames.values()) {
      if (now - at > EXTERNAL_GAME_TTL_MS) continue;
      const seat = (c: Color) => {
        // Canonical rating and name from user_ratings, never the arena's baked
        // constant (see resolveArenaSeat).
        const resolved = resolveArenaSeat(
          meta.seats[c],
          this.arenaSeatIdentity(meta.seats[c].userId, meta.mode),
        );
        return {
          name: resolved.name,
          rating: Math.round(resolved.rating),
          avatar: housePersona(meta.seats[c].userId)?.avatar ?? null,
        };
      };
      games.push({
        id: meta.id,
        // Self-describe arena origin in the shared snapshot so the lobby watch
        // link tags ?src=arena (routing spectators to the arena socket) without
        // depending on any per-client arena cache — the count merge is now
        // server-side and single-source.
        origin: "arena" as const,
        players: { w: seat("w"), b: seat("b") },
        rated: true,
        draft: true,
        mode: meta.mode,
        timeSec: meta.timeSec,
        incrementSec: meta.incrementSec,
        moves: meta.moves,
        watchers: this.watcherCount(meta.id),
      });
    }
    return games;
  }

  // ---------------- rematch ----------------

  // Withdraw a pending rematch offer. Only the player who made the offer can
  // cancel it, and only while no rematch game has been created yet.
  private async rematchCancel(ws: WebSocket) {
    const session = this.session(ws);
    const match = session.matchId ? await this.loadMatch(session.matchId) : null;
    if (!match || !session.color) return;
    if (match.rematchedTo) return;
    if (match.rematchOfferBy !== session.color) return;
    match.rematchOfferBy = null;
    await this.saveMatch(match, false);
    this.broadcast(match, "rematchCancelled", { color: session.color });
  }

  private async rematchRequest(ws: WebSocket) {
    const session = this.session(ws);
    const match = session.matchId ? await this.loadMatch(session.matchId) : null;
    if (!match || !session.color) return error(ws, "no_game", "Join a game before requesting a rematch.");
    if (!match.result) return error(ws, "not_over", "The game is still in progress.");
    if (match.rematchedTo) return error(ws, "rematch_done", "A rematch has already started.");

    const opponentColor: Color = session.color === "w" ? "b" : "w";
    if (match.rematchOfferBy === session.color) return;
    if (match.rematchOfferBy !== opponentColor) {
      if (!this.connectedSession(match.id, opponentColor)) {
        return error(ws, "opponent_gone", "Your opponent has left.");
      }
      match.rematchOfferBy = session.color;
      await this.saveMatch(match, false);
      this.broadcast(match, "rematchOffer", { color: session.color });
      return;
    }

    // Both agreed: new game with colors swapped, fresh rules and seed.
    // Persist the claim BEFORE the first await below (same discipline as
    // endMatch's `recorded`): the rating reads, code allocation and overrides
    // snapshot are subrequests that do not hold the DO input gate, so a
    // double-tapped rematch (or a concurrent rematchCancel) loading the match
    // mid-flight must already see it as taken. The real id replaces the
    // provisional marker once the new match is saved; a failure rolls it back.
    match.rematchedTo = REMATCH_PENDING;
    await this.saveMatch(match, false);
    let rematch: StoredMatch;
    try {
      rematch = await this.buildRematch(match);
    } catch (err) {
      match.rematchedTo = null;
      await this.saveMatch(match, false);
      throw err;
    }
    const id = rematch.id;
    match.rematchOfferBy = null;
    match.rematchedTo = id;
    await this.saveMatch(match, false);

    send(this.connectedSession(match.id, "w"), "rematched", { id, color: "b", token: rematch.tokens.b });
    send(this.connectedSession(match.id, "b"), "rematched", { id, color: "w", token: rematch.tokens.w });
  }

  /** Create and persist the swapped-colors rematch of a finished match. Runs
   * subrequests (ratings, code, overrides), so callers claim the source match
   * first (see rematchRequest). */
  private async buildRematch(match: StoredMatch): Promise<StoredMatch> {
    const users: StoredMatch["users"] = {};
    if (match.users?.b) users.w = { ...match.users.b };
    if (match.users?.w) users.b = { ...match.users.w };
    const db = await this.db();
    if (db) {
      for (const color of ["w", "b"] as Color[]) {
        const seat = users[color];
        if (!seat) continue;
        const row = await this.seatCategoryRating(db, seat.id, this.matchRatingCategory(match));
        if (row) {
          seat.rating = row.rating;
          seat.rd = row.rd;
          seat.vol = row.vol;
          seat.avatar = row.avatar;
        }
      }
    }

    const id = await this.newCode(match.rated ? 8 : 5);
    // A rematch is a NEW match: it takes the current overrides snapshot, not
    // the finished game's, so fresh card edits reach rematches too.
    const cardSnap = await this.cardOverridesSnapshot();
    const cardOverrides = match.draft ? this.draftPoolStamp(cardSnap) : undefined;
    const rematch: StoredMatch = {
      id,
      setup: {
        ...(match.mode === "buff"
          ? { whiteNerfId: UNRESTRICTED_NERF.id, blackNerfId: UNRESTRICTED_NERF.id }
          : pickNerfIds(cardSnap.nerfOff)),
        seed: makeSeed(),
        timeSec: match.setup.timeSec,
        incrementSec: match.setup.incrementSec,
      },
      tokens: { w: newToken(), b: newToken() },
      disconnectedAt: {},
      opponentGoneNotified: {},
      moves: [],
      result: null,
      clocks: { w: match.setup.timeSec * 1000, b: match.setup.timeSec * 1000 },
      runningSince: null,
      drawOfferBy: null,
      createdAt: Date.now(),
      startedAt: null,
      completedAt: null,
      replayVersion: REPLAY_VERSION,
      rated: match.rated,
      autoStart: true,
      users,
      ...(match.draft
        ? {
            draft: true,
            ...(match.mode ? { mode: match.mode } : {}),
            picksVisible: !!match.picksVisible,
            cadence: match.mode === "nerf" ? NERF_MODE_CADENCE : DEFAULT_CADENCE,
            draftSeed: makeSeed(),
            ...(cardOverrides ? { cardOverrides } : {}),
            draftActions: [],
          }
        : {}),
    };
    await this.saveMatch(rematch);
    return rematch;
  }

  // ---------------- chat ----------------

  // Per-socket chat throttle; in-memory only, so at worst a hibernation wake
  // resets the window.
  private lastChatAt = new Map<string, number>();

  private async chatMessage(ws: WebSocket, data: unknown) {
    const session = this.session(ws);
    const match = session.matchId ? await this.loadMatch(session.matchId) : null;
    if (!match || !session.color) return error(ws, "no_game", "Join a game before chatting.");
    const raw = String((data as { text?: unknown } | undefined)?.text ?? "").trim();
    if (!raw) return;
    const now = Date.now();
    if (now - (this.lastChatAt.get(session.id) ?? 0) < 500) return;
    this.lastChatAt.set(session.id, now);

    const name = match.users?.[session.color]?.name ?? (session.color === "w" ? "White" : "Black");
    const clipped = raw.slice(0, 200);
    // Shadow-mute (Lichess-style): a chat-muted player sees their own message
    // echoed back, but it is neither stored nor shown to anyone else.
    if (session.mutedUntil && session.mutedUntil > Date.now()) {
      send(ws, "chat", { color: session.color, name, text: clipped, at: now } satisfies ChatEntry);
      return;
    }
    // Censor profanity before it is stored or relayed, and keep the original
    // in chat_flags so a moderator can review repeat offenders later.
    const matched = findProfanity(clipped);
    const text = matched.length ? censorText(clipped) : clipped;
    if (matched.length) {
      const db = await this.db();
      if (db) {
        try {
          await db
            .prepare(
              `INSERT INTO chat_flags (id, match_id, user_id, username, color, text, matched_words, created_at)
               VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
            )
            .bind(crypto.randomUUID(), match.id, session.userId ?? null, name, session.color, clipped, matched.join(","), now)
            .run();
        } catch (err) {
          console.error("failed to record chat flag", match.id, err);
        }
      }
    }
    const entry: ChatEntry = { color: session.color, name, text, at: now };
    match.chat = [...(match.chat ?? []), entry].slice(-50);
    await this.saveMatch(match, false);
    this.broadcast(match, "chat", entry);
  }

  // Chat between spectators. Relayed only to sockets watching the same game,
  // so the players can't read it (no coaching from the rail).
  private async spectatorChatMessage(ws: WebSocket, data: unknown) {
    const session = this.session(ws);
    const match = session.watching ? await this.loadMatch(session.watching) : null;
    if (!match) return error(ws, "not_watching", "Watch a game before chatting.");
    const raw = String((data as { text?: unknown } | undefined)?.text ?? "").trim();
    if (!raw) return;
    const now = Date.now();
    if (now - (this.lastChatAt.get(session.id) ?? 0) < 500) return;
    this.lastChatAt.set(session.id, now);

    const name = session.username ?? "Anonymous";
    const clipped = raw.slice(0, 200);
    // Shadow-mute works here too: the muted watcher sees only their own echo.
    if (session.mutedUntil && session.mutedUntil > Date.now()) {
      send(ws, "schat", { name, text: clipped, at: now } satisfies SpectatorChatEntry);
      return;
    }
    const matched = findProfanity(clipped);
    const text = matched.length ? censorText(clipped) : clipped;
    if (matched.length) {
      const db = await this.db();
      if (db) {
        try {
          await db
            .prepare(
              `INSERT INTO chat_flags (id, match_id, user_id, username, color, text, matched_words, created_at)
               VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
            )
            .bind(crypto.randomUUID(), match.id, session.userId ?? null, name, "s", clipped, matched.join(","), now)
            .run();
        } catch (err) {
          console.error("failed to record chat flag", match.id, err);
        }
      }
    }
    const entry: SpectatorChatEntry = { name, text, at: now };
    match.spectatorChat = [...(match.spectatorChat ?? []), entry].slice(-50);
    await this.saveMatch(match, false);
    this.sendWatchers(match, "schat", entry);
  }

  // ---------------- voluntary rule reveal ----------------

  // A player may show their secret rule to the table mid-game. Irreversible;
  // the opponent and all spectators learn it immediately, and reconnects
  // replay it via the start payload.
  private async revealRule(ws: WebSocket) {
    const session = this.session(ws);
    const match = session.matchId ? await this.loadMatch(session.matchId) : null;
    if (!match || !session.color) return error(ws, "no_game", "Join a game before revealing your rule.");
    if (!match.startedAt) return error(ws, "not_started", "The game has not started yet.");
    if (match.revealed?.[session.color]) return;

    match.revealed = { ...(match.revealed ?? {}), [session.color]: true };
    await this.saveMatch(match, false);
    const nerfId = session.color === "w" ? match.setup.whiteNerfId : match.setup.blackNerfId;
    const payload = { color: session.color, nerfId };
    this.broadcast(match, "reveal", payload);
    this.sendWatchers(match, "reveal", payload);
  }

  // ---------------- draft mode (buff drafts) ----------------

  // The single place that decides what each receiver may see of the draft
  // state. Visibility rules:
  // - Held buff IDENTITIES are hidden like nerfs: a seat sees its own cards,
  //   but the opponent's held buffs arrive masked ({ hidden, tier, spent,
  //   nullified }) unless the match has picksVisible or the card's identity
  //   already showed on the table (instant effect, activation, or a granted
  //   move; see draftRebuild). Everything reveals at game end.
  // - Board effects, tempo counters, and the draft counters are public.
  // - A pending offer's cards are visible to the offer's own seat, plus the
  //   opposing seat when the match was created with picksVisible. Without
  //   picksVisible the opposing seat only learns that an offer is pending.
  // - Draft flags and the one-shot oppReveal snapshot are per-seat secrets;
  //   the opposing seat gets flags only under picksVisible, never the reveal.
  // - Spectators get none of the hidden data: no offers, no pending markers,
  //   no flags, no reveals, and BOTH sides' held buffs masked, regardless of
  //   settings.
  // - The draft RNG state is never serialized for anyone: it would let a
  //   client predict every future offer.
  private maskBuff(inst: BuffInstance) {
    return {
      hidden: true as const,
      tier: inst.tier as number,
      ...(inst.spent ? { spent: true } : {}),
      ...(inst.nullified ? { nullified: true } : {}),
    };
  }

  private draftStateFor(
    game: NerfGame,
    match: StoredMatch,
    seat: Color | "spectator",
    // Owner "see opponent buffs": when true, unmask the OPPONENT seat's held
    // buff identities for THIS viewer only. Set solely for a god-panel owner's
    // own dtState (server-verified in sendDraftState) and never for a spectator. It
    // touches nothing but the held-buff list: offers, flags, and reveals stay
    // masked exactly as before, and held buffs are display-only on the client,
    // so this reveals already-synced state without changing the authoritative
    // game or any other viewer's view.
    revealOpp = false,
    // Owner "infinite rerolls": when true, report THIS viewer's OWN seat's
    // rerollsLeft as the INFINITE_REROLLS sentinel so their Reroll control never
    // greys out. Set solely for a god-panel owner's own dtState (server-verified
    // in sendDraftState). The real stored count is untouched (draftReroll tops
    // it up), and the opponent's frame still carries the real value, so this
    // changes nothing authoritative and leaks nothing.
    godRerolls = false,
  ) {
    const bs = game.buffs;
    if (!bs) return null;
    const playerState = (color: Color) => {
      const ps = bs.players[color];
      const self = seat === color;
      // FULL TRANSPARENCY (owner rule): the whole draft game is public, live.
      // Every viewer — both seats and every spectator — sees both sides' held
      // cards face-up, pending offers, and draft flags. The old masking layer
      // (maskBuff / isBuffRevealed / picksVisible / the admin reveal toggle)
      // is bypassed rather than deleted, so nothing downstream that still
      // consults it breaks; `revealOpp` is now moot.
      void revealOpp;
      void match;
      const open = true;
      const showBuffs = true;
      return {
        buffs: showBuffs ? ps.buffs : ps.buffs.map((b) => (this.isBuffRevealed(b) ? b : this.maskBuff(b))),
        draftsTaken: ps.draftsTaken,
        nextDraftAt: ps.nextDraftAt,
        // Owner "infinite rerolls": inflate ONLY the requesting owner's own seat
        // so their Reroll control always shows; every other viewer (and the
        // opponent) sees the real count.
        rerollsLeft: self && godRerolls ? Math.max(ps.rerollsLeft ?? 0, INFINITE_REROLLS) : ps.rerollsLeft,
        offer: open ? ps.offer : null,
        ...(seat !== "spectator" && !open && ps.offer ? { offerPending: true } : {}),
        ...(open ? { flags: ps.flags } : {}),
        ...(self ? { oppReveal: ps.oppReveal ?? null } : {}),
        ...(ps.nerfRemoved ? { nerfRemoved: true } : {}),
        revived: ps.revived,
        // Crazyhouse-style pocket: sent for both seats (drops are public moves,
        // so the count is not hidden info) so an inventory drop replays
        // identically on every replica even if a grant's replay path drifts.
        ...(ps.inventory ? { inventory: ps.inventory } : {}),
        // Skip announcements (public): a blocked/dry draft round is explicit.
        ...(ps.lastSkip ? { lastSkip: ps.lastSkip } : {}),
      };
    };
    return {
      cadence: bs.cadence,
      effects: bs.effects,
      extraMoves: bs.extraMoves,
      skips: bs.skips,
      ...(bs.chainKingGuard ? { chainKingGuard: bs.chainKingGuard } : {}),
      ...(bs.historyDiverged ? { historyDiverged: true } : {}),
      players: { w: playerState("w"), b: playerState("b") },
      // The live shared lock-in deadline rides every dtState frame, so a
      // reroll's restarted window (and any other server-side deadline change)
      // reaches clients without needing its own frame type.
      //
      // ALWAYS present, null included. Omitting it when the window closes left
      // the client holding the previous, still-FUTURE deadline: when both seats
      // resolve early (settleDraftAction nulls dtDeadline before it expires),
      // draftGraceOver stayed false and LockInCountdown kept counting a window
      // that no longer existed.
      deadline: match.dtDeadline ?? null,
    };
  }

  private sendDraftState(match: StoredMatch, game: NerfGame) {
    for (const color of ["w", "b"] as Color[]) {
      const seatWs = this.connectedSession(match.id, color);
      if (!seatWs) continue;
      // Owner "see opponent buffs": if this connected seat is a god-panel owner
      // with the reveal toggled on, unmask the OPPONENT's held-buff identities in
      // their dtState only. Re-verified here (never trust the flag alone), applied
      // per socket so no other seat's masking changes, and threaded through every
      // draft change so the reveal stays live as the opponent drafts.
      const seatSession = this.session(seatWs);
      const revealOpp = !!seatSession.seeOppBuffs && isGodPanelUser(seatSession.username);
      // Owner "infinite rerolls": re-verified per socket, applied to this seat's
      // own frame only so the Reroll control stays lit for the owner.
      const godRerolls = !!seatSession.godRerolls && isGodPanelUser(seatSession.username);
      const state = this.draftStateFor(game, match, color, revealOpp, godRerolls);
      if (state) send(seatWs, "dtState", { state });
    }
  }

  // Spectators keep an engine replica too, so identity reveals (a hidden
  // passive's granted move) must reach them the same way, spectator-filtered.
  private sendWatcherDraftState(match: StoredMatch, game: NerfGame) {
    const state = this.draftStateFor(game, match, "spectator");
    if (state) this.sendWatchers(match, "dtState", { state }, "draftState");
  }

  // The draft record a given viewer may replay: your own picked cards are
  // FULL TRANSPARENCY (owner rule): every viewer — both seats and every
  // spectator — replays the same fully-open record. Picks carry their real
  // card identities, banks reveal that they happened, and buff activations
  // carry their targets. The old per-viewer masking ({ hidden, tier }
  // placeholders until a card's identity showed on the table) is gone; the
  // `viewer` parameter is kept so call sites stay unchanged.
  private publicDraftActions(match: StoredMatch, viewer: Color | "spectator") {
    void viewer;
    type PublicDraftAction =
      | { ply: number; color: Color; a: "pick"; cards: { id: string; tier: number }[] }
      | { ply: number; color: Color; a: "bank" }
      | { ply: number; color: Color; a: "diffFlag" }
      | { ply: number; color: Color; a: "use"; buffIndex: number; picks: BuffPick[] };
    return (match.draftActions ?? []).flatMap<PublicDraftAction>((action) => {
      // Rerolls are a server-only RNG detail (the client never rolls offers);
      // drop them so the replica's applyDraftAction never sees one.
      if (action.a === "reroll") return [];
      // Owner god-panel grants: a HIDEABLE summon only seats a held card, which
      // dtState already carries face-up-or-masked, so it is dropped from the
      // replay. An INSTANT summon, though, resolved on the board inside
      // acquireBuff, so a replaying replica (a late-joining spectator, a
      // reconnect) must re-run it or its board desyncs — surface it as a public
      // pick carrying the real identity, exactly as a normally-drafted instant
      // reveals itself. The client's pick path runs acquireBuff for a revealed
      // card, reproducing the same board effect.
      if (action.a === "grant") {
        const def = BUFF_BY_ID[action.id];
        if (def?.kind === "instant") {
          return [{ ply: action.ply, color: action.color, a: "pick" as const, cards: [{ id: action.id, tier: action.tier }] }];
        }
        return [];
      }
      if (action.a !== "pick") return [action];
      return [{ ply: action.ply, color: action.color, a: "pick" as const, cards: action.cards }];
    });
  }

  // Shared validation for the draft frames: a seated, live, started draft
  // match rebuilt through the engine.
  private async draftContext(
    ws: WebSocket,
  ): Promise<{ session: SessionAttachment; match: StoredMatch; game: NerfGame } | null> {
    const session = this.session(ws);
    const match = session.matchId ? await this.loadMatch(session.matchId) : null;
    if (!match || !session.color) {
      error(ws, "no_game", "Join a game before drafting.");
      return null;
    }
    if (!match.draft) {
      error(ws, "not_draft", "This game is not a Draft game.");
      return null;
    }
    if (await this.finishOnFlag(match)) return null;
    if (match.result) {
      error(ws, "game_over", "This game is over.");
      return null;
    }
    // Buff frames wait for the opening nerf draft like moves do.
    if (match.nerfOptions && !match.startedAt) {
      error(ws, "nerf_pending", "Pick your nerf before the game starts.");
      return null;
    }
    const game = await this.gameForPlay(match);
    if (!game?.buffs) {
      if (!match.result) error(ws, "no_game", "The game has not started yet.");
      return null;
    }
    return { session, match, game };
  }

  // Persist a resolved draft action, tell everyone the public outcome, and
  // re-sync both seats' filtered state. The pick event is public but the
  // picked card's identity is not: the picker gets the real cards, everyone
  // else gets masked entries (tier only) unless picksVisible or the card is
  // an instant (its effect is on the board, so replicas must replay it).
  // A use always carries the card identity: the effect must replay on every
  // replica, and a fired card's face is public knowledge anyway. Instant and
  // activated buffs can end the game on the spot (a removal or freeze can
  // decide it), so the end flow runs here too.
  private async settleDraftAction(
    match: StoredMatch,
    game: NerfGame,
    resolved: {
      color: Color;
      kind: "picked" | "banked";
      cards?: { id: string; tier: number }[];
      acquired?: BuffInstance[];
    } | null,
    used?: { color: Color; buffIndex: number; picks: BuffPick[]; card?: { id: string; tier: number } },
  ) {
    // Bill any elapsed time to whoever was charged BEFORE this action
    // resolved (a straggling drafter's deliberation), then re-anchor: the
    // charged seat can change the moment offerSeats is re-synced below.
    if (!match.result && match.draft && match.runningSince !== null) {
      const now = Date.now();
      this.bankClocks(match, now);
      match.runningSince = now;
    }
    if (game.result && !match.result) {
      const now = Date.now();
      this.bankClocks(match, now);
      match.runningSince = null;
      match.result = game.result;
      match.completedAt = now;
    } else if (!match.result && game.board.turn !== this.activeColor(match)) {
      // A buff use consumed the activator's turn: bank their elapsed time
      // and start charging the new mover, exactly like a played move.
      const now = Date.now();
      this.bankClocks(match, now);
      if (match.runningSince !== null) match.runningSince = now;
      match.turnColor = game.board.turn;
    }
    // Resume the paused clock once no offer is pending on either side, or
    // once the free lock-in window has already expired (the clock only stays
    // paused during the window itself).
    const bs = game.buffs;
    const offersPending = !!bs?.players.w.offer || !!bs?.players.b.offer;
    if (!offersPending) {
      match.dtDeadline = null;
      match.dtWindowFrom = null;
    }
    this.syncOfferSeats(match, game);
    if (
      (!offersPending || !match.dtDeadline) &&
      match.startedAt &&
      !match.result &&
      match.runningSince === null
    ) {
      const resumeAt = Date.now();
      // A disconnect-pause outranks the draft resume: restarting the clock
      // here would silently end an absent player's protection early (and the
      // orphaned pauseUntil would later be swept as stale, billing nothing).
      // Leave the clock paused and let the pause's own deadline resume it.
      if (match.pauseUntil != null && resumeAt < match.pauseUntil) {
        // nothing to do — releaseExpiredPause owns the resume
      } else {
        if (match.pauseUntil != null) {
          const away = awaySeat(match);
          if (away) chargePauseBudget(match, away, resumeAt);
          else clearPause(match);
        }
        match.runningSince = resumeAt;
      }
    }
    // A pick that cast Chess Diff swaps both clocks for the diff's 1+0 minute
    // (the paused game's clocks are stashed on the match until it is decided).
    const diffChanged = this.applyDiffTransitions(match, game);
    // A clock-manipulation buff picked or used this action (Time Thief, Jet
    // Lag, Overtime Whistle...) adjusts the authoritative clocks now, after the
    // turn-handover banking above so the delta lands on up-to-date values.
    const clockChanged = this.applyClockFx(match, game) || diffChanged;
    // House seats: a resolved action can hand the turn (or a fresh offer) to
    // the house side. No-op for purely human games.
    this.armBotAction(match, game, Date.now());
    // Refresh the replay checkpoint from the just-settled game (throttled).
    this.maybeCheckpoint(match, game);
    // A settled draft action is exactly the board-mutating-card path: force a
    // fresh public snapshot alongside the seq bump, persisted in the save below.
    this.bumpPublicSnapshot(match, game, { force: true });
    await this.saveMatch(match);
    if (clockChanged) {
      const c = this.currentClocks(match);
      const clockFrame = { wc: Math.round(c.w), bc: Math.round(c.b) };
      this.broadcast(match, "n", clockFrame);
      this.sendWatchers(match, "n", clockFrame, "clock");
    }
    if (resolved) {
      // FULL TRANSPARENCY: the resolved pick (its real cards included) goes to
      // both seats AND every spectator identically — no masked variant.
      const publicFrame = { color: resolved.color, kind: resolved.kind };
      const ownFrame = resolved.cards ? { ...publicFrame, cards: resolved.cards } : publicFrame;
      this.broadcast(match, "dtResolved", ownFrame);
      this.sendWatchers(match, "dtResolved", ownFrame, "draftResolved");
    }
    if (used) {
      this.broadcast(match, "dtUsed", used);
      this.sendWatchers(match, "dtUsed", used, "draftUsed");
    }
    this.sendDraftState(match, game);
    this.sendWatcherDraftState(match, game);
    if (match.result) await this.endMatch(match);
  }

  // Resolve a seat's pending offer by picking a card. Shared by the socket
  // frame handler and the lock-in deadline auto-resolver.
  private async resolveDraftPick(match: StoredMatch, game: NerfGame, color: Color, index: number) {
    const bs = game.buffs!;
    const ps = bs.players[color];
    const before = ps.buffs.length;
    const effectsBefore = bs.effects.length;
    const mutationsBefore = bs.mutations ?? 0;
    pickDraftCard(game, color, index);
    // Everything acquired by this pick (take-both drafts can grab several
    // cards) is recorded; identity reaches the opponent masked unless the
    // card reveals itself (see settleDraftAction).
    const acquired = ps.buffs.slice(before);
    // A pick whose init observably touched the board or effects is public
    // like an instant's effect: replicas must replay it or they desync.
    // Mirrored by applyStoredDraftAction so rebuilds re-derive the same set.
    if (bs.effects.length !== effectsBefore || (bs.mutations ?? 0) !== mutationsBefore) {
      for (const b of acquired) this.markBuffRevealed(b);
    }
    if (this.draftRebuild?.matchId === match.id) {
      this.draftRebuild.acquired.set(match.draftActions?.length ?? 0, acquired);
    }
    const cards = acquired.map((b) => ({ id: b.id, tier: b.tier as number }));
    match.draftActions = [
      ...(match.draftActions ?? []),
      { ply: match.moves.length, color, a: "pick", index, cards },
    ];
    await this.settleDraftAction(match, game, { color, kind: "picked", cards, acquired });
  }

  private async resolveDraftBank(match: StoredMatch, game: NerfGame, color: Color) {
    bankDraft(game, color);
    match.draftActions = [...(match.draftActions ?? []), { ply: match.moves.length, color, a: "bank" }];
    await this.settleDraftAction(match, game, { color, kind: "banked" });
  }

  private async draftPick(ws: WebSocket, data: unknown) {
    const ctx = await this.draftContext(ws);
    if (!ctx) return;
    const { session, match, game } = ctx;
    const color = session.color!;
    const ps = game.buffs!.players[color];
    const offer = ps.offer;
    if (!offer) return error(ws, "no_offer", "You have no pending buff draft.");
    const request = (data || {}) as { index?: unknown };
    const index = Number(request.index);
    if (!Number.isInteger(index) || !offer.cards[index]) {
      return error(ws, "bad_pick", "That card is not part of your offer.");
    }
    await this.resolveDraftPick(match, game, color, index);
  }

  private async draftBank(ws: WebSocket) {
    const ctx = await this.draftContext(ws);
    if (!ctx) return;
    const { session, match, game } = ctx;
    const color = session.color!;
    if (!game.buffs!.players[color].offer) {
      return error(ws, "no_offer", "You have no pending buff draft.");
    }
    await this.resolveDraftBank(match, game, color);
  }

  // Reroll the seat's pending offer: fresh cards at the same tiers, spending
  // one reroll. Server-authoritative and broadcast (the offer never leaves the
  // DO's RNG), so no client can desync it. No dtResolved and no clock/turn
  // change: the offer stays open, so a plain draft-state resync carries the
  // new cards and the decremented reroll count to the seat.
  private async draftReroll(ws: WebSocket) {
    const ctx = await this.draftContext(ws);
    if (!ctx) return;
    const { session, match, game } = ctx;
    const color = session.color!;
    const ps = game.buffs!.players[color];
    if (!ps.offer) return error(ws, "no_offer", "You have no pending buff draft.");
    // Owner "infinite rerolls" (god-panel accounts only, re-verified here): top
    // the real count up by one so rerollOffer's own spend nets to zero and the
    // seat never runs dry. The stored count is otherwise untouched, so toggling
    // the tool off restores normal draining immediately.
    if (!!session.godRerolls && isGodPanelUser(session.username)) {
      ps.rerollsLeft = (ps.rerollsLeft ?? 0) + 1;
    }
    if ((ps.rerollsLeft ?? 0) <= 0) return error(ws, "no_reroll", "You have no rerolls left.");
    if (!rerollDraft(game, color)) return error(ws, "no_reroll", "That draft cannot be rerolled.");
    match.draftActions = [
      ...(match.draftActions ?? []),
      { ply: match.moves.length, color, a: "reroll" },
    ];
    // A reroll INSIDE the shared decision window restarts the presentation
    // (the fresh cards re-deal), so it also restarts the window: prep budget
    // plus the full decision time from now, with clocks still paused. The
    // fresh deadline reaches both clients on the dtState frames below. A
    // reroll AFTER the window expired changes nothing: that draft already
    // runs on the straggler's own clock.
    const now = Date.now();
    if (match.dtDeadline && now < match.dtDeadline) {
      match.dtDeadline = now + draftPrepMs + draftLockInMs;
      match.dtWindowFrom = now;
    }
    // A house seat can hold the offer; a reroll leaves whose-turn-it-is
    // untouched, so just refresh any pending house action off the new state.
    this.armBotAction(match, game, now);
    await this.saveMatch(match);
    this.sendDraftState(match, game);
    this.sendWatcherDraftState(match, game);
  }

  // ---------------- owner "fun with friends" tools ----------------

  // Announce a god-panel action to the whole table (both seats AND every
  // spectator) so its use is never silent. These tools used to be invisible to
  // the opponent by design; they are now surfaced as a plain "God panel used"
  // notice to everyone in the game, including the owner (a confirmation it
  // fired). `by` is the owner's seat name and `action` a short phrase; the
  // notice is transient (like a draft toast), so it is broadcast, not stored.
  private announceGodPanel(match: StoredMatch, by: string, action: string) {
    const payload = { by, action, at: Date.now() };
    this.broadcast(match, "godUsed", payload);
    this.sendWatchers(match, "godUsed", payload);
  }

  // The seat's display name (falls back to the side's colour), used to label
  // whose god panel fired.
  private seatName(match: StoredMatch, color: Color): string {
    return match.users?.[color]?.name ?? (color === "w" ? "White" : "Black");
  }

  // Nudge the OPPONENT's clock. +15s is a lichess-style courtesy any player may
  // send in a casual game; -15s is the owner-only tool, gated to the god-panel
  // accounts.
  // Both are SERVER-authoritative: the magnitude is fixed here (only the sign is
  // read from the client), the subtract path floors the clock so it can never
  // fall to zero and end the game, rated games are refused outright, and each
  // socket is debounced so the buttons cannot be spammed.
  private async adjustOppClock(ws: WebSocket, data: unknown) {
    const session = this.session(ws);
    const match = session.matchId ? await this.loadMatch(session.matchId) : null;
    if (!match || !session.color) return error(ws, "no_game", "Join a game before adjusting clocks.");
    if (!match.setup.timeSec) return error(ws, "no_clock", "This game has no clock.");
    // Never touch a rated game's clock (rating integrity). Draft games are
    // always casual, so this also naturally permits every Draft game.
    if (match.rated) return error(ws, "rated_game", "Clock help is off in rated games.");
    if (await this.finishOnFlag(match)) return;
    if (match.result || !match.startedAt) return error(ws, "not_live", "The game is not running.");
    // Read only the SIGN from the client; the server owns the 15s magnitude.
    const subtract = Number((data as { delta?: unknown } | undefined)?.delta) < 0;
    // -15s is the owner-only cheat: SERVER-verify the account (client gate is UX).
    if (subtract && !isGodPanelUser(session.username)) {
      return error(ws, "forbidden", "That tool is not available on this account.");
    }
    // Debounce per socket so neither button can be spammed.
    const now = Date.now();
    if (now - (session.lastClockAdjustAt ?? 0) < 500) return;
    session.lastClockAdjustAt = now;
    // Bank the live clocks first so the delta lands on up-to-date values, and
    // keep charging the active player from now (mirrors a played move).
    this.bankClocks(match, now);
    if (match.runningSince !== null) match.runningSince = now;
    const opp: Color = session.color === "w" ? "b" : "w";
    const deltaMs = subtract ? -15000 : 15000;
    let next = match.clocks[opp] + deltaMs;
    // Floor a subtract to ~1s so it never ends the game or goes negative.
    if (subtract) next = Math.max(1000, next);
    match.clocks[opp] = next;
    await this.saveMatch(match);
    const c = this.currentClocks(match, now);
    const frame = { wc: Math.round(c.w), bc: Math.round(c.b) };
    this.broadcast(match, "n", frame);
    this.sendWatchers(match, "n", frame, "clock");
    // Only the -15s subtract is a god-panel tool; the +15s add is a courtesy any
    // player may send, so it stays unannounced.
    if (subtract) this.announceGodPanel(match, this.seatName(match, session.color), "cut 15s from the clock");
  }

  // Owner god panel: a god-panel owner summons a card straight into their own
  // hand, no draft and no offer. SERVER-verifies the account (the client gate is
  // only UX) and only grants cards that can be HELD hidden: an instant fires the
  // moment it is acquired and an opponent-move-filtering passive must be known
  // to the opponent to stay in sync, so neither can be a silent summon and both
  // are rejected. The grant is recorded as a draft action (so replays re-add it)
  // but is stripped from publicDraftActions and never carries a dtResolved
  // pick-toast, so the card IDENTITY is never told to the opponent. (The generic
  // "god panel used" notice fired at the end announces THAT a card was summoned,
  // never which one.) Both seats do get a fresh dtState (masked for every view
  // but the granting seat) purely so the hidden-card slot lines up for a later
  // "use".
  private async adminGrant(ws: WebSocket, data: unknown) {
    const ctx = await this.draftContext(ws);
    if (!ctx) return;
    const { session, match, game } = ctx;
    if (!isGodPanelUser(session.username)) {
      return error(ws, "forbidden", "That tool is not available on this account.");
    }
    const id = String((data as { id?: unknown } | undefined)?.id ?? "").slice(0, 64);
    const def = BUFF_BY_ID[id];
    if (!def || !def.implemented) return error(ws, "bad_card", "Unknown card.");
    const color = session.color!;
    // Summon the card into the granting seat's hand — NO card-level gate any
    // more (only the account gate above). A hideable card sits face-down in
    // hand; a self-revealing card is allowed too, it just cannot stay secret
    // (handled below). Instants have no "sit in hand" engine state, so
    // acquireBuff resolves their effect on the board the instant they are
    // acquired — the same grant-and-immediately-resolve a normal instant draft
    // does (see acquireBuff / applyStoredDraftAction, which replay identically).
    acquireBuff(game, color, id, def.tier);
    // A summoned card can add/steal CLOCK time the instant it is acquired
    // (Overtime Whistle +30s, Buzzer Beater, casino/timefaustian/meta clock
    // instants — each calls api.adjustClock, which queues onto game.buffs.clockFx).
    // acquireBuff fires that effect but only QUEUES the delta; unless we drain it
    // here it is silently dropped (clockFx is transient and stripped on save), so
    // every clock-adding card summoned from the god panel was a no-op. Drain it
    // now — exactly as draftUse does — so the delta lands on match.clocks before
    // the save below, and remember whether a clock actually moved.
    const now = Date.now();
    const clockChanged = this.applyClockFx(match, game, now);
    // An instant just mutated the authoritative board inside acquireBuff, and
    // NEITHER a dtState frame nor a dropped grant action carries a board
    // mutation to the replicas — so route the instant through the very same
    // dtResolved channel a normal instant pick uses. Every client applies it as
    // a public "pick" (acquireBuff on their own replica → same board effect),
    // and publicDraftActions additionally surfaces this grant as a pick so a
    // late-joining spectator's replay reproduces it. The card identity goes
    // public here, exactly as it does for a normally-drafted instant — instants
    // are inherently un-hideable, which is why the old gate rejected them.
    const revealsInstant = def.kind === "instant";
    // An opponent-move-filtering passive needs no dtResolved: it mutates no
    // board square, and isBuffRevealed already forces it face-up in every
    // dtState (the opponent must know it to generate the same legal moves), so
    // the sendDraftState below keeps the boards in sync on its own.
    match.draftActions = [
      ...(match.draftActions ?? []),
      { ply: match.moves.length, color, a: "grant", id, tier: def.tier as number },
    ];
    // Keep the fast-replay checkpoint honest (the card is now in `game`), then
    // persist. A summoned instant CAN change the clock (Overtime Whistle,
    // Buzzer Beater, every addSelfSec/subOppSec instant), so the drained delta
    // above must persist here and be broadcast below.
    this.maybeCheckpoint(match, game);
    // An instant summon is a board-mutating card resolution: advance the public
    // revision and refresh the snapshot so the dtResolved envelope below carries
    // a fresh seq + post-event parity hash, not a stale one.
    this.bumpPublicSnapshot(match, game, { force: true });
    await this.saveMatch(match);
    // If the summon moved a clock, broadcast the authoritative clock frame so
    // both seats and every spectator see the new time (mirrors draftUse).
    if (clockChanged) {
      const c = this.currentClocks(match, now);
      const clockFrame = { wc: Math.round(c.w), bc: Math.round(c.b) };
      this.broadcast(match, "n", clockFrame);
      this.sendWatchers(match, "n", clockFrame, "clock");
    }
    // Instant only: publish the resolved effect so every LIVE client mutates its
    // own board (a spectator or the granting seat replaying later gets the same
    // effect via publicDraftActions surfacing this grant as a pick).
    if (revealsInstant) {
      const resolvedFrame = { color, kind: "picked" as const, cards: [{ id, tier: def.tier as number }] };
      this.broadcast(match, "dtResolved", resolvedFrame);
      this.sendWatchers(match, "dtResolved", resolvedFrame, "draftResolved");
    }
    // Resync BOTH seats and every spectator. The granting seat sees the real
    // card; a HIDEABLE card is masked by draftStateFor (a non-instant,
    // non-opponent-filtering card is never auto-revealed), so at most a
    // face-down slot appears. A self-revealing card (instant, or an
    // opponent-move-filtering passive) is forced face-up by isBuffRevealed, so
    // both seats already agree on it. This alignment matters: a later "use" of a
    // held card references its hand slot by index on every replica, so the
    // opponent's hand length must already match the server. For a HIDEABLE card
    // there is no dtResolved frame, so the opponent is never told WHICH card was
    // summoned; a self-revealing card is inherently public (the instant's effect
    // is on the board, an opponent-filter must be known to move-match) — the
    // generic god-panel notice below still announces THAT a summon happened.
    this.sendDraftState(match, game);
    this.sendWatcherDraftState(match, game);
    // Surface the summon to the table. For a hideable card the identity stays
    // masked in every non-owner dtState (only the fact of a summon is told); a
    // self-revealing card is already public through the frames above, but the
    // generic notice reads the same either way.
    this.announceGodPanel(match, this.seatName(match, color), "summoned a card");
  }

  // Owner "see opponent buffs": god-panel-only per-viewer reveal. Flips a
  // per-socket flag and re-sends the owner's own dtState, which draftStateFor
  // then builds with the opponent's held-buff identities UNMASKED (and re-masks
  // when toggled off). SERVER-verifies the account (the client gate is only UX).
  // The opponent's dtState is never touched, so the reveal itself changes no
  // other view; but turning it ON is now announced to the table (see below), so
  // the peek is no longer secret. Desync-safe: held buffs are display-only on
  // the client (their board effects flow through the synced effects/action
  // record, not the held list), so this reveals already-synced state without
  // changing the authoritative game or any other viewer's view.
  private async seeOppBuffs(ws: WebSocket, data: unknown) {
    const ctx = await this.draftContext(ws);
    if (!ctx) return;
    const { session, match, game } = ctx;
    if (!isGodPanelUser(session.username)) {
      return error(ws, "forbidden", "That tool is not available on this account.");
    }
    const wasOn = !!session.seeOppBuffs;
    session.seeOppBuffs = Boolean((data as { on?: unknown } | undefined)?.on);
    // Refresh only this socket's dtState; draftStateFor unmasks the opponent's
    // held buffs when the flag is on and re-masks them when off. No other seat's
    // dtState changes.
    const state = this.draftStateFor(game, match, session.color!, session.seeOppBuffs);
    if (state) send(ws, "dtState", { state });
    // Announce the peek to the table, but only on the off -> on edge (toggling
    // it back off is not a fresh "use").
    if (session.seeOppBuffs && !wasOn) {
      this.announceGodPanel(match, this.seatName(match, session.color!), "peeked at hidden cards");
    }
  }

  // Owner "infinite rerolls": god-panel-only per-socket flag. When on, the
  // owner's own dtState reports their rerollsLeft as INFINITE_REROLLS (so the
  // Reroll control never greys out) and draftReroll tops the real count back up
  // on every use, so a god-panel account can reroll a draft offer endlessly —
  // handy for scripting videos. SERVER-verifies the account (the client gate is
  // only UX). Only the owner's OWN frame changes; the opponent's dtState still
  // carries the seat's real count, so nothing authoritative changes and nothing
  // leaks. Announced to the table on the off -> on edge, like the other tools.
  private async godRerolls(ws: WebSocket, data: unknown) {
    const ctx = await this.draftContext(ws);
    if (!ctx) return;
    const { session, match, game } = ctx;
    if (!isGodPanelUser(session.username)) {
      return error(ws, "forbidden", "That tool is not available on this account.");
    }
    const wasOn = !!session.godRerolls;
    session.godRerolls = Boolean((data as { on?: unknown } | undefined)?.on);
    // Refresh only this socket's dtState so the inflated rerollsLeft (or the real
    // count once toggled off) reaches the owner's Reroll control immediately.
    const state = this.draftStateFor(
      game,
      match,
      session.color!,
      !!session.seeOppBuffs && isGodPanelUser(session.username),
      session.godRerolls,
    );
    if (state) send(ws, "dtState", { state });
    if (session.godRerolls && !wasOn) {
      this.announceGodPanel(match, this.seatName(match, session.color!), "unlocked infinite rerolls");
    }
  }

  private async draftUse(ws: WebSocket, data: unknown) {
    const ctx = await this.draftContext(ws);
    if (!ctx) return;
    const { session, match, game } = ctx;
    const color = session.color!;
    const ps = game.buffs!.players[color];
    if (ps.offer) return error(ws, "draft_pending", "Resolve your buff draft first.");
    // Same rule as moves: the opponent's open draft blocks activations too
    // (their pick can mutate the board this activation would target).
    if (game.buffs!.players[color === "w" ? "b" : "w"].offer) {
      return error(ws, "opp_draft_pending", "Wait for your opponent to finish drafting.");
    }
    if (game.board.turn !== color) return error(ws, "not_your_turn", "Buffs activate on your turn.");
    const request = (data || {}) as { buffIndex?: unknown; picks?: unknown };
    const buffIndex = Number(request.buffIndex);
    if (!Number.isInteger(buffIndex) || !ps.buffs[buffIndex]) {
      return error(ws, "bad_buff", "You do not hold that buff.");
    }
    const picks = this.parseBuffPicks(request.picks);
    if (!picks || !this.buffPicksComplete(game, color, buffIndex, picks)) {
      return error(ws, "bad_target", "Those targets are not valid for that buff.");
    }
    const inst = ps.buffs[buffIndex];
    const theirs = game.buffs!.players[color === "w" ? "b" : "w"];
    const mineBefore = ps.buffs.length;
    const theirsBefore = theirs.buffs.length;
    if (!activateBuff(game, color, buffIndex, picks)) {
      return error(ws, "bad_buff", "That buff cannot be used right now.");
    }
    // Using a card makes it public, along with anything the use created or
    // moved between the players (Mirror copies, stolen cards).
    this.markBuffRevealed(inst);
    for (const added of ps.buffs.slice(mineBefore)) this.markBuffRevealed(added);
    for (const added of theirs.buffs.slice(theirsBefore)) this.markBuffRevealed(added);
    match.draftActions = [
      ...(match.draftActions ?? []),
      { ply: match.moves.length, color, a: "use", buffIndex, picks },
    ];
    await this.settleDraftAction(match, game, null, {
      color,
      buffIndex,
      picks,
      card: { id: inst.id, tier: inst.tier as number },
    });
  }

  private async draftTarget(ws: WebSocket, data: unknown) {
    const ctx = await this.draftContext(ws);
    if (!ctx) return;
    const { session, game } = ctx;
    const color = session.color!;
    const request = (data || {}) as { buffIndex?: unknown; picks?: unknown };
    const buffIndex = Number(request.buffIndex);
    if (!Number.isInteger(buffIndex) || !game.buffs!.players[color].buffs[buffIndex]) {
      return error(ws, "bad_buff", "You do not hold that buff.");
    }
    const picks = this.parseBuffPicks(request.picks);
    const collected = picks ? this.walkBuffPicks(game, color, buffIndex, picks) : null;
    if (!collected) return error(ws, "bad_target", "Those targets are not valid for that buff.");
    send(ws, "dtTargetReq", { buffIndex, target: buffNextTarget(game, color, buffIndex, collected) });
  }

  // ---------------- draft mode (opening nerf draft) ----------------

  // Deal the opening nerf draft for a Draft match. Difficulty is always
  // identical for the two seats: one tier pair is rolled for the whole deal
  // (an anchor tier plus a partner tier within one of it, possibly the same
  // tier), and BOTH seats get one card of the anchor tier and one card of
  // the partner tier. All four cards are distinct. The deal comes from the
  // match seed RNG so a Durable Object restart re-deals the same options
  // (never Math.random).
  private dealNerfDraftOptions(match: StoredMatch): Record<Color, string[]> {
    const master = new RNG(match.setup.seed);
    master.fork(); // skip: white's nerf seed, already derived in startPayload
    master.fork(); // skip: black's nerf seed
    const rng = master.fork();

    // The deal draws from the capped opening pool (see MAX_OPENING_NERF_TIER
    // in the nerf library), minus any moderator-disabled nerfs
    // (card_overrides; beginNerfDraft warms the cached snapshot first). When
    // the disable list leaves no feasible tier pairing, the unfiltered pool
    // deals instead: a playable deal beats honoring the filter.
    const off = new Set(this.cardOverridesCache?.value.nerfOff ?? []);
    let pool: Nerf[] = openingNerfPool().filter((nerf) => !off.has(nerf.id));
    const ofTier = (tier: number) => pool.filter((nerf) => nerf.tier === tier);
    const takeOne = (tier: number, taken: Set<string>): string => {
      const candidates = ofTier(tier).filter((nerf) => !taken.has(nerf.id));
      const card = candidates[rng.int(candidates.length)];
      taken.add(card.id);
      return card.id;
    };
    // A tier pairing is feasible only if the pool supplies the four distinct
    // cards: four of the anchor tier when the partner tier matches it,
    // otherwise two of each.
    const feasible = (anchor: number, partner: number) =>
      partner === anchor
        ? ofTier(anchor).length >= 4
        : ofTier(anchor).length >= 2 && ofTier(partner).length >= 2;
    const tiersOf = () => [...new Set(pool.map((nerf) => nerf.tier))];
    const anchorsOf = (candidates: number[]) =>
      candidates.filter((anchor) =>
        candidates.some((partner) => Math.abs(partner - anchor) <= 1 && feasible(anchor, partner)),
      );
    let tiers = tiersOf();
    let anchorTiers = anchorsOf(tiers);
    if (anchorTiers.length === 0) {
      pool = openingNerfPool();
      tiers = tiersOf();
      anchorTiers = anchorsOf(tiers);
    }
    const anchorTier = anchorTiers[rng.int(anchorTiers.length)];
    const partnerTiers = tiers.filter(
      (partner) => Math.abs(partner - anchorTier) <= 1 && feasible(anchorTier, partner),
    );
    const partnerTier = partnerTiers[rng.int(partnerTiers.length)];
    const taken = new Set<string>();
    const first = [takeOne(anchorTier, taken), takeOne(partnerTier, taken)];
    const second = [takeOne(anchorTier, taken), takeOne(partnerTier, taken)];
    // Randomize each seat's card order and which seat gets which hand, so
    // neither the anchor card nor a specific hand always lands on one side.
    if (rng.int(2) === 1) first.reverse();
    if (rng.int(2) === 1) second.reverse();
    return rng.int(2) === 0 ? { w: first, b: second } : { w: second, b: first };
  }

  // Both seats of a Draft match are present: deal the opening nerf draft
  // instead of starting the game. The match stays un-started (clocks off,
  // moves and buff frames rejected with nerf_pending) until both picks land.
  private async beginNerfDraft(match: StoredMatch) {
    if (!match.nerfOptions) {
      // Warm the card-overrides snapshot so the (synchronous) deal below can
      // read the disabled-nerf list from the cache. The dealt options are
      // persisted, so a later snapshot refresh can never re-deal them.
      await this.cardOverridesSnapshot();
      match.nerfOptions = this.dealNerfDraftOptions(match);
      // 15 second lock-in: the pick auto-resolves at the deadline so a
      // stalling (or vanished) player cannot hold the table hostage.
      match.nerfDeadline = Date.now() + draftLockInMs;
    }
    // House seats pick their nerf after a human-like beat (2-8s), well
    // inside the lock-in window.
    this.armBotAction(match, null, Date.now());
    await this.saveMatch(match);
    this.sendStart(match, "w");
    this.sendStart(match, "b");
  }

  private async nerfDraftPick(ws: WebSocket, data: unknown) {
    const session = this.session(ws);
    const match = session.matchId ? await this.loadMatch(session.matchId) : null;
    if (!match || !session.color) return error(ws, "no_game", "Join a game before drafting.");
    if (!match.draft) return error(ws, "not_draft", "This game is not a Draft game.");
    if (match.result) return error(ws, "game_over", "This game is over.");
    if (!match.nerfOptions || match.startedAt) {
      return error(ws, "no_nerf_draft", "There is no nerf draft to pick from.");
    }
    const color = session.color;
    if (match.nerfPicks?.[color] != null) {
      return error(ws, "already_picked", "You already picked your nerf.");
    }
    // Index-only validation: clients choose between the two server-dealt
    // options and can never smuggle in a nerf id of their own.
    const index = Number((data as { index?: unknown } | undefined)?.index);
    if (index !== 0 && index !== 1) {
      return error(ws, "bad_pick", "That card is not part of your options.");
    }

    match.nerfPicks = { ...(match.nerfPicks ?? {}), [color]: index };
    const opp: Color = color === "w" ? "b" : "w";
    const oppPick = match.nerfPicks[opp];
    if (oppPick == null) {
      await this.saveMatch(match);
      // Progress only: both seats learn that this side picked, never which
      // card. Spectators learn nothing.
      this.broadcast(match, "dtNerfPicked", { color });
      return;
    }

    await this.finalizeNerfDraft(match);
  }

  // Both picks are in: lock the chosen rules and start the game proper.
  // Clocks only begin now, so neither side paid for choosing.
  private async finalizeNerfDraft(match: StoredMatch) {
    match.setup.whiteNerfId = match.nerfOptions!.w[match.nerfPicks!.w!];
    match.setup.blackNerfId = match.nerfOptions!.b[match.nerfPicks!.b!];
    // Visible-picks matches: both chosen rules are open from move one,
    // through the same reveal channel voluntary reveals use.
    if (match.picksVisible) match.revealed = { w: true, b: true };
    match.nerfDeadline = null;
    match.startedAt = Date.now();
    // The draft can finalize from the alarm (a house pick landing, or the
    // 15s lock-in auto-resolve) while a human seat is disconnected — during the
    // draft the game was not started, so detachSession could not pause the
    // clock. Start PAUSED in that case so the human's clock does not burn on a
    // board the guard-held bot cannot advance; reconnectMatch's house-resume
    // block resumes it and re-arms the bot when they return. A present human
    // (the normal accept) is byte-for-byte unchanged: runningSince = startedAt.
    const humanGone = (["w", "b"] as Color[]).some(
      (color) => !match.bots?.[color] && match.disconnectedAt[color] && !this.connectedSession(match.id, color),
    );
    match.runningSince = humanGone ? null : match.startedAt;
    // House seats: the game just started, so white's first move may be a
    // house action.
    match.botActAt = null;
    this.armBotAction(match, null, match.startedAt);
    await this.saveMatch(match);
    this.sendStart(match, "w");
    this.sendStart(match, "b");
  }

  // Lock-in deadline enforcement, run from the alarm. Overdue nerf picks
  // take the first option (the game cannot start without them). Overdue
  // buff offers are NOT auto-resolved anymore: the offer stays open, the
  // clock resumes, and the straggler pays for further deliberation with
  // their own time — their client shows the pick in a side panel.
  private async enforceDraftDeadlines(match: StoredMatch, now: number): Promise<boolean> {
    if (!match.draft || match.result) return false;
    if (match.nerfOptions && !match.startedAt) {
      if (!match.nerfDeadline || now < match.nerfDeadline + draftPickGraceMs) return false;
      match.nerfPicks = { ...(match.nerfPicks ?? {}) };
      for (const color of ["w", "b"] as Color[]) {
        if (match.nerfPicks[color] == null) match.nerfPicks[color] = 0;
      }
      await this.finalizeNerfDraft(match);
      return true;
    }
    if (!match.startedAt || !match.dtDeadline || now < match.dtDeadline) return false;
    const expiredAt = match.dtDeadline;
    // If some path left the clock RUNNING through the window (the backstop
    // case currentClocks guards), bank it before dropping dtWindowFrom: the
    // banked value still excludes the window, and re-anchoring runningSince to
    // the deadline means the window is never billed afterwards either. Dropping
    // the marker first would hand the whole window straight back onto the bill.
    if (!match.result && match.runningSince !== null) {
      this.bankClocks(match, expiredAt);
      match.runningSince = expiredAt;
    }
    match.dtDeadline = null;
    match.dtWindowFrom = null;
    // House games resume the clock from the moment the free window EXPIRED,
    // not from whenever this enforcement happened to run: under alarm backlog
    // the gap between the two is exactly the "bot got its time back" window —
    // the client resumed counting down at the deadline, then the next server
    // frame showed the bot's clock teleported back up by the enforcement lag.
    // Charging from the deadline matches what every client already displayed.
    // Purely-human games keep the old behavior byte-for-byte (owner rule:
    // human-vs-human is untouched); their enforcement lag is bounded by the
    // alarm anyway.
    if (!match.result && match.runningSince === null) {
      // A live disconnect-pause outranks the window resume (same rule as
      // settleDraftAction): restarting the clock here would end the absent
      // player's protection early and orphan pauseUntil (later swept as
      // stale, billing nothing). Leave it paused; releaseExpiredPause owns
      // the resume. An already-expired pause is billed before resuming.
      if (match.pauseUntil != null && now < match.pauseUntil) {
        // nothing to do: releaseExpiredPause owns the resume
      } else {
        if (match.pauseUntil != null) {
          const away = awaySeat(match);
          if (away) chargePauseBudget(match, away, now);
          else clearPause(match);
        }
        match.runningSince = match.bots ? expiredAt : now;
      }
    }
    // The lock-in window expiring resumes play; if a house seat is to move (or
    // still holds its own offer) and its think timer was lost while the clock
    // sat paused, nothing else re-arms it until the heartbeat sweep. Arm it
    // here so the bot resumes with the clock. Guarded on being unarmed so an
    // already-ticking timer is never disturbed.
    if (!match.result && !match.botActAt) this.armBotAction(match, null, now);
    await this.saveMatch(match, false);
    return true;
  }

  private parseBuffPicks(raw: unknown): BuffPick[] | null {
    if (raw === undefined) return [];
    // 32 bounds server work while leaving room for the longest pick chains
    // (Total Warp moves up to 15 pieces via alternating piece / destination
    // picks; Warp Sovereign runs up to 6).
    if (!Array.isArray(raw) || raw.length > 32) return null;
    const picks: BuffPick[] = [];
    for (const entry of raw) {
      const pick = (entry || {}) as { square?: unknown; buffIndex?: unknown };
      const next: BuffPick = {};
      if (Number.isInteger(pick.square)) next.square = Number(pick.square);
      if (Number.isInteger(pick.buffIndex)) next.buffIndex = Number(pick.buffIndex);
      if (next.square === undefined && next.buffIndex === undefined) return null;
      picks.push(next);
    }
    return picks;
  }

  // Walk the buff's own target chain: every pick must be one of the engine's
  // offered candidates. This keeps a client from smuggling arbitrary squares
  // or buff indexes into an effect.
  private walkBuffPicks(game: NerfGame, color: Color, buffIndex: number, picks: BuffPick[]): BuffPick[] | null {
    const collected: BuffPick[] = [];
    for (const pick of picks) {
      const target = buffNextTarget(game, color, buffIndex, collected);
      if (!target) return null;
      if (target.kind === "square") {
        if (pick.square === undefined || !target.squares.includes(pick.square)) return null;
        collected.push({ square: pick.square });
      } else {
        if (pick.buffIndex === undefined || !target.options.some((option) => option.index === pick.buffIndex)) {
          return null;
        }
        collected.push({ buffIndex: pick.buffIndex });
      }
    }
    return collected;
  }

  private buffPicksComplete(game: NerfGame, color: Color, buffIndex: number, picks: BuffPick[]): boolean {
    const collected = this.walkBuffPicks(game, color, buffIndex, picks);
    if (!collected) return false;
    const next = buffNextTarget(game, color, buffIndex, collected);
    // A finishable step means the picks so far already form a complete
    // effect (Warp Sovereign's "stop after any pair"), so an early stop is
    // as valid as walking the whole chain.
    return next === null || (next.kind === "square" && !!next.finishable);
  }

  // ---------------- spectating & lobby ----------------

  private async watchMatch(ws: WebSocket, data: unknown) {
    const session = this.session(ws);
    if (session.matchId) return error(ws, "already_joined", "This connection already belongs to a game.");
    const id = String((data as { id?: unknown } | undefined)?.id || "").trim().toUpperCase();

    // Arena (external) game (Tier 2 / M3): spectate via the replica if the arena
    // is already streaming it; otherwise register the watch and wait — the next
    // /arena/games sync puts this id in the watch set, the arena pushes a started
    // snapshot, and ingestExternalSnapshot flushes the wstart to this socket.
    if (this.externalGames.has(id) || this.externalMatches.has(id)) {
      const next = { ...session, watching: id };
      this.sessions.set(ws, next);
      ws.serializeAttachment(next);
      const replica = this.externalMatches.get(id);
      if (replica) {
        this.sendWstart(ws, replica);
      } else {
        // No replica yet: registering `watching` above is exactly what puts this
        // id into externalWatchedIds(), so the very next /arena/games poll tells
        // the arena to stream it and the snapshot flushes the wstart. The DO
        // can't pull that snapshot itself (the arena polls the DO, not the
        // reverse), so we send an immediate `wpending` ack — the client treats
        // it as progress and extends its watch deadline instead of stalling on
        // the base timeout while the arena's next poll lands.
        send(ws, "wpending", { id });
      }
      this.broadcastWatchers(id);
      return;
    }

    const match = await this.loadMatch(id);
    if (!match) return error(ws, "not_found", "No live game with that id.");
    await this.finishOnFlag(match);

    const next = { ...session, watching: id };
    this.sessions.set(ws, next);
    ws.serializeAttachment(next);

    this.sendWstart(ws, match);
    this.broadcastWatchers(id);
  }

  private watchLeave(ws: WebSocket) {
    const session = this.session(ws);
    if (!session.watching) return;
    const id = session.watching;
    const next = { ...session };
    delete next.watching;
    this.sessions.set(ws, next);
    ws.serializeAttachment(next);
    this.broadcastWatchers(id);
    this.dropExternalIfUnwatched(id);
  }

  // Drop a watched arena game's replica once its last spectator leaves — the
  // arena stops streaming it (it drops out of the watch set), so keeping the
  // replica would only let it go stale. A later re-watch rebuilds it from a
  // fresh snapshot.
  private dropExternalIfUnwatched(id: string) {
    if (this.externalMatches.has(id) && this.watcherCount(id) === 0) {
      this.externalMatches.delete(id);
      this.externalReplay.delete(id);
      this.externalFrameAt.delete(id);
    }
  }

  // One snapshot for the lobby page: who is online right now and which games
  // can be watched. Polled by the client every few seconds.
  private async lobbySnapshot(ws: WebSocket) {
    send(ws, "lobby", await this.buildLobbyPayload());
  }

  // Build (or reuse the cached) lobby snapshot. Shared by the WebSocket `lobby`
  // frame and the HTTP GET /lobby route so both transports serve identical data
  // off the same in-DO cache.
  private async buildLobbyPayload(): Promise<unknown> {
    const now = Date.now();
    // Serve the shared snapshot from cache when it is fresh. This skips the
    // full match scan and every other await on the hot path (flag checks, the
    // D1 rating lookup) for the burst of concurrent polls that land inside the
    // TTL window. The snapshot is public and identical for every viewer, so a
    // shared copy leaks no per-viewer private data.
    if (this.lobbyCache && now - this.lobbyCache.at < GameServer.LOBBY_CACHE_TTL_MS) {
      return this.lobbyCache.payload;
    }
    // Live matches only. The lobby only ever lists unfinished games (open
    // challenges and in-progress games); finished records were filtered out
    // below anyway. Reading them via the index avoids a full-table scan on
    // every lobby poll, the most frequent human-driven path into the DO.
    const matches = await this.loadLiveMatches();

    // House-bot presence is gated on the runtime on/off switch. When a moderator
    // turns the house bots OFF they must vanish from the lobby entirely — no
    // seeking bots, no idle "online" filler, and no presence-padded player count —
    // not merely stop starting new games. houseTick separately winds down active
    // seeks/games; gating the three presence injections below on this flag makes
    // the online list and the shown count agree with the switch immediately
    // (cached ~15s, so this adds no per-poll D1 work). Previously the presence
    // block ignored the flag, so ~210 bots stayed "online" after the off switch.
    const houseOn = await this.houseEnabled();

    const liveGames: Array<{
      id: string;
      origin?: "arena";
      players: ReturnType<GameServer["playersPayload"]>;
      rated: boolean;
      draft: boolean;
      mode?: DraftMode;
      timeSec: number;
      incrementSec: number;
      moves: number;
      watchers: number;
    }> = [];
    const playingUserIds = new Set<string>();
    // Friend games waiting for an opponent, shown in the lobby as open
    // challenges anyone can accept. Matchmade (autoStart) games waiting for
    // their paired players to arrive are not challenges.
    const challenges: Array<{
      id: string;
      host: { name: string; rating: number | null };
      rated: boolean;
      draft: boolean;
      mode?: DraftMode;
      timeSec: number;
      incrementSec: number;
      createdAt: number;
    }> = [];
    for (const match of matches) {
      // A dealt nerf draft means both seats are taken: not a challenge.
      if (!match.startedAt && !match.result && !match.autoStart && !match.nerfOptions) {
        // Only list codes whose host is still connected; otherwise the code
        // is a dead end for whoever clicks it. Direct challenges are reserved
        // for their invitee and never appear as open challenges.
        if (!match.invitedUsername && this.connectedSession(match.id, "w")) {
          const host = match.users?.w;
          // The seat snapshot was captured when the challenge was CREATED and
          // only refreshes when an opponent joins, so a code sitting in the
          // lobby shows a stale number while the host's rating moves in other
          // games — the reported "challenge shows the wrong rating". Read the
          // live rating from the SAME bucket this match would rate under
          // (matchRatingCategory, the value recordFinishedGame reads as
          // `before`); the snapshot stays the fallback on any read failure.
          // Bounded: one read per open challenge per lobby cache window
          // (LOBBY_CACHE_TTL_MS) — open challenges are rare and short-lived.
          let hostRating = host ? Math.round(host.rating) : null;
          if (host?.id) {
            const db = await this.db();
            const live = db
              ? await this.seatCategoryRating(db, host.id, this.matchRatingCategory(match))
              : null;
            if (live) hostRating = Math.round(live.rating);
          }
          challenges.push({
            id: match.id,
            host: host ? { name: host.name, rating: hostRating } : { name: "Anonymous", rating: null },
            rated: !!match.rated,
            draft: !!match.draft,
            ...(match.mode ? { mode: match.mode } : {}),
            timeSec: match.setup.timeSec,
            incrementSec: match.setup.incrementSec,
            createdAt: match.createdAt,
          });
        }
        continue;
      }
      if (!match.startedAt || match.result) continue;
      await this.finishOnFlag(match, now, false);
      if (match.result) continue;
      for (const color of ["w", "b"] as Color[]) {
        const id = match.users?.[color]?.id;
        if (id) playingUserIds.add(id);
      }
      liveGames.push({
        id: match.id,
        players: this.playersPayload(match),
        rated: !!match.rated,
        draft: !!match.draft,
        ...(match.mode ? { mode: match.mode } : {}),
        timeSec: match.setup.timeSec,
        incrementSec: match.setup.incrementSec,
        moves: match.moves.length,
        watchers: this.watcherCount(match.id),
      });
    }
    // Bot-vs-bot games simulated on the OCI arena (Tier 2 / M2) show alongside
    // real live games. Gated by ARENA_LOBBY_ENABLED; empty when off.
    //
    // Warm the house-ratings cache first: externalLiveGames reads it
    // synchronously to replace the arena's baked seat rating with the real one
    // (see arenaSeatIdentity). Without this the first payload from a fresh DO
    // instance would fall back to the stale constant until houseTick next ran.
    if (this.env.ARENA_LOBBY_ENABLED === "true") {
      await this.houseLiveInfo(await this.db());
    }
    for (const g of this.externalLiveGames(now)) liveGames.push(g);
    liveGames.sort((a, b) => b.watchers - a.watchers || b.moves - a.moves);
    challenges.sort((a, b) => b.createdAt - a.createdAt);

    // Who is queued for quick pairing right now. Each connected entry is also
    // surfaced as a joinable seek, so a player browsing the lobby can see and
    // answer someone waiting in a different pool instead of both idling.
    const queuedUserIds = new Set<string>();
    const seeks: Array<{
      pool: string;
      name: string;
      rating: number | null;
      mode: DraftMode;
      timeSec: number;
      incrementSec: number;
      at: number;
      // Stable identity so the client can answer a specific seek and the server
      // can pair with exactly that person (or bot), never a random pool waiter.
      // Deliberately NO house flag: house seeks are shaped exactly like human
      // seeks on the wire.
      userId: string;
    }> = [];
    for (const mode of QUEUE_MODES) {
      for (const [poolName, pool] of Object.entries(QUEUE_POOLS)) {
        const entries = (await this.ctx.storage.get<QueueEntry[]>(this.queueKey(mode, poolName))) ?? [];
        for (const entry of entries) {
          if (!this.socketForAttachment(entry.attachmentId)) continue;
          queuedUserIds.add(entry.userId);
          seeks.push({
            pool: poolName,
            name: entry.username,
            // The seeker's rating in this pool's mode bucket.
            rating: Math.round(entry.rating),
            mode,
            timeSec: pool.timeSec,
            incrementSec: pool.incrementSec,
            at: entry.at,
            userId: entry.userId,
          });
        }
      }
    }
    // House players seeking in a pool surface exactly like human seeks. Their
    // rows come from DO storage (no D1), and failures here degrade to "no
    // house seeks" without touching the human lobby.
    let houseSeeks: HouseSeekEntry[] = [];
    // Skip house seeks entirely when the bots are off, so none show as searching
    // in the lobby (houseTick also clears the stored rows, but gating here makes
    // the switch immediate rather than waiting a tick).
    if (houseOn) try {
      houseSeeks = (await this.ctx.storage.get<HouseSeekEntry[]>(houseSeeksKey)) ?? [];
      for (const seek of houseSeeks) {
        const pool = QUEUE_POOLS[seek.pool];
        if (!pool) continue;
        queuedUserIds.add(seek.userId);
        seeks.push({
          pool: seek.pool,
          name: seek.name,
          rating: Math.round(seek.rating),
          mode: seek.mode,
          timeSec: pool.timeSec,
          incrementSec: pool.incrementSec,
          at: seek.at,
          userId: seek.userId,
        });
      }
    } catch {
      houseSeeks = [];
    }
    seeks.sort((a, b) => a.at - b.at);

    // Every signed-in account with an open socket, deduped; anonymous sockets
    // are only counted.
    const seen = new Map<string, { name: string; rating: number | null; status: string; avatar: string | null }>();
    let anonymous = 0;
    for (const [socket, session] of this.sessions) {
      if (socket.readyState !== WebSocket.OPEN) continue;
      if (!session.userId || !session.username) {
        anonymous++;
        continue;
      }
      const status = playingUserIds.has(session.userId)
        ? "playing"
        : queuedUserIds.has(session.userId)
        ? "searching"
        : "online";
      const existing = seen.get(session.userId);
      // "playing" wins over "searching" wins over "online" across tabs.
      if (!existing || existing.status === "online" || (existing.status === "searching" && status === "playing")) {
        seen.set(session.userId, { name: session.username, rating: null, status, avatar: null });
      }
    }

    // House players appear in the online list too: seeking ones from the
    // seek rows. Ratings and avatars come from what is already in hand (seek
    // entries and match seats), so this adds no D1 work.
    try {
      for (const seek of houseSeeks) {
        if (!seen.has(seek.userId)) {
          seen.set(seek.userId, {
            name: seek.name,
            rating: Math.round(seek.rating),
            status: "searching",
            avatar: seek.avatar,
          });
        }
      }
      // EVERY seat of a live match counts as online-and-playing: humans too,
      // not just house bots. A player mid-game may have no identified lobby
      // socket at all (their game socket is a separate session), which used
      // to drop them from the online list entirely while they played.
      for (const match of matches) {
        if (!match.startedAt || match.result) continue;
        for (const color of ["w", "b"] as Color[]) {
          const user = match.users?.[color];
          if (!user) continue;
          const existing = seen.get(user.id);
          if (!existing) {
            seen.set(user.id, {
              name: user.name,
              rating: Math.round(user.rating),
              status: "playing",
              avatar: user.avatar ?? null,
            });
          } else if (existing.status !== "playing") {
            existing.status = "playing";
          }
        }
      }
      // Arena (OCI bot-vs-bot) games: every seated persona counts as an online
      // player exactly like a seat in a native house game above. These games
      // already show in the live-games list (externalLiveGames), so their
      // players must show in the online list too or the two panels disagree —
      // 19 bot games must read as at least 38 seated bot players. Same gate
      // and TTL as externalLiveGames so a paused/expired arena adds nobody.
      if (this.env.ARENA_LOBBY_ENABLED === "true") {
        for (const { meta, at } of this.externalGames.values()) {
          if (now - at > EXTERNAL_GAME_TTL_MS) continue;
          for (const color of ["w", "b"] as Color[]) {
            const seat = meta.seats[color];
            if (!seat?.userId) continue;
            const existing = seen.get(seat.userId);
            if (!existing) {
              seen.set(seat.userId, {
                name: seat.name,
                rating: Math.round(seat.rating),
                status: "playing",
                avatar: housePersona(seat.userId)?.avatar ?? null,
              });
            } else if (existing.status !== "playing") {
              existing.status = "playing";
            }
          }
        }
      }
      // Display presence: the house roster fills out the lobby so it never
      // looks dead. Personas already added above keep their REAL status
      // ("playing" from a live game, "searching" from a seek); those are never
      // touched here. Every remaining persona is genuinely idle and shows
      // "online" (never a fabricated "playing").
      //
      // We used to mark a rotating ~half of the idle personas "playing" for
      // optics, but that is exactly the reported "in game but not in live games"
      // bug: those personas were in NO real match, so they showed as playing in
      // the online list yet never appeared in the live-games / TV list (which is
      // built from real matches in the live index). A bot must only ever read as
      // "playing" when it is actually in a live house game, so its game is
      // always discoverable. The lobby still reads as busy because real
      // house-vs-house filler games run up to houseVsHouseCap (each puts two
      // personas on genuine "playing" AND lists a watchable game above).
      //
      // Presence uses the ONLINE window (up to 150), a superset of the active
      // window: the active bots already added above keep their real
      // playing/searching status; the extra online-only personas fill in as idle
      // "online" so the list is fuller than the set that actually plays.
      // Idle house presence fills out the lobby ONLY while the bots are enabled;
      // turned off, no persona is injected as "online".
      const idlePersonas = houseOn
        ? onlineHouseRoster(this.houseDayIndex()).filter((p) => !seen.has(p.userId))
        : [];
      // Idle bots get a placeholder seed here; the canonical most-played-bucket
      // query below (now shared with human rows) overwrites it for any bot that
      // has a rated bucket, so an idle bot shows the SAME number as its profile,
      // leaderboard, and seek. This replaces an older Math.max(nerf, buff) that
      // matched neither profile card and went stale when the active bucket lost
      // rating (the "a bot's rating differs on its profile" report).
      for (const persona of idlePersonas) {
        seen.set(persona.userId, {
          name: persona.name,
          rating: houseSeedRating(persona),
          status: "online",
          avatar: persona.avatar,
        });
      }
    } catch {}

    // Attach ratings for the online list in one query, for humans AND bots, so
    // an idle bot's displayed rating is the same per-mode-derived number its
    // profile / leaderboard / seek show (was Math.max above, which diverged).
    // The IN list is the online roster (bounded, ~the roster size), one query
    // per lobby cache window.
    const db = await this.db();
    const ratedIds = [...seen.keys()];
    if (db && ratedIds.length > 0) {
      try {
        // Chunked (chunkIds): with the full ~210-bot presence set online, one
        // IN() over every id exceeds D1's 100-bound-params cap, so this whole
        // canonicalization pass threw on EVERY lobby build and the catch below
        // swallowed it — the online list then showed baked usernames and seed
        // ratings forever (the reported "renamed an account / rating moved but
        // the online panel never updates, inconsistent with profiles").
        //
        // The player's ACTIVE bucket (most games played; ties broken by the
        // higher number), not MAX(nerf, buff): the max rule meant a player who
        // only plays one mode and loses kept displaying the other bucket's
        // untouched 1500 seed forever — the "online list shows the wrong elo
        // and never updates" report. Falls back to the legacy users.rating
        // only when neither mode bucket exists yet.
        const rowChunks = await Promise.all(
          chunkIds(ratedIds).map((chunk) =>
            db
              .prepare(
                `SELECT u.id, u.username,
                        COALESCE(
                          (SELECT r.rating FROM user_ratings r
                            WHERE r.user_id = u.id AND r.category IN ('nerf','buff')
                            ORDER BY r.games DESC, r.rating DESC LIMIT 1),
                          u.rating
                        ) AS rating,
                        u.avatar
                 FROM users u WHERE u.id IN (${chunk.map(() => "?").join(",")})`,
              )
              .bind(...chunk)
              .all<{ id: string; username: string; rating: number; avatar: string | null }>(),
          ),
        );
        for (const rows of rowChunks) {
          for (const row of rows.results) {
            const entry = seen.get(row.id);
            if (entry) {
              // The users row wins for the whole identity, not just rating and
              // avatar: for humans it's the same string the session carries, and
              // for house personas it's where an admin rename from /mod/house
              // lands — so an idle renamed bot never shows its baked name.
              entry.name = row.username;
              entry.rating = Math.round(row.rating);
              entry.avatar = row.avatar;
            }
          }
        }
      } catch {}
    }

    // Cap high enough to never clip the full ONLINE-presence LIST (up to
    // HOUSE_PRESENCE_LIST_MAX personas, added above) plus the humans online
    // alongside them; a lower cap would hide part of the presence set behind the
    // slice. Sorted by rating so the strongest personas and humans lead the list.
    // Note this bounds the LIST, not the shown COUNT: the count comes from
    // houseOnlineCount() via the padding below, which is what lets the site read
    // several hundred online without shipping several hundred rows per poll.
    const players = [...seen.values()]
      .sort((a, b) => (b.rating ?? 0) - (a.rating ?? 0))
      .slice(0, HOUSE_PRESENCE_LIST_MAX + 60);
    // ---- Online-count baseline: HONEST to the coded bot-presence model ----
    // Every surface derives its player count as players.length + anonymous
    // (home strip, lobby header), so the baseline is applied here, once, and
    // every surface agrees. The house-presence pass above already enumerates the
    // ONLINE-presence window (onlineHouseRoster — the full ~150-strong idle+
    // active set, NOT the smaller 60-120 active-only subset) into `players`, so
    // the shown total normally already reflects that whole set plus any real
    // humans; with dozens of live house games running it reads well past 80.
    //
    // This baseline is NOT an arbitrary floor: it is the coded presence model
    // (houseOnlineCount) so the shown number stays in step with the population
    // the site actually claims. It replaced a flat 280 plus a +-6 jitter, which
    // read the same at 04:00 and 20:00; the curve now troughs at
    // HOUSE_ONLINE_MIN in the small hours and peaks at HOUSE_ONLINE_MAX in the
    // evening, with a per-day scale so no two days peak identically. It is a
    // pure function of `now`, so every viewer polling at the same moment agrees
    // and nothing needs storing. Padding only ever ADDS to the anonymous count,
    // so the shown total can never fall below the real humans plus seated bots
    // counted above. It applies ONLY while the bots are enabled: with them off
    // the count reflects just real humans, so the off switch really does empty
    // the lobby.
    if (houseOn) {
      const shownReal = players.length + anonymous;
      const baseline = houseOnlineCount(now);
      if (shownReal < baseline) anonymous += baseline - shownReal;
    }
    const payload = {
      players,
      anonymous,
      // Cap high enough to surface the full house-vs-house filler set (up to
      // houseTotalGamesCap ~70) PLUS any server-merged arena games without
      // clipping. This is the ONE authoritative merged games number every client
      // sees: arena games are unioned server-side above (externalLiveGames,
      // gated ARENA_LOBBY_ENABLED), so the count must not be truncated below the
      // target here or the shared snapshot would under-report while a per-browser
      // arena merge (removed on the client) used to paper over the gap. A lower
      // cap (was 25) made the DO snapshot top out mid-ramp and forced each tab to
      // reach 40+ via its own uncapped arena union — the source of the cross-tab
      // desync. Keep it >= the filler ceiling so a true 40+ situation reads 40+
      // from the DO alone, identically for every viewer.
      games: liveGames.slice(0, Math.max(60, houseTotalGamesCapMax)),
      challenges: challenges.slice(0, 25),
      seeks: seeks.slice(0, 25),
    };
    // Refresh the shared cache so the rest of this poll burst is served without
    // rescanning. Set last, after any finishOnFlag writes above, so the cached
    // copy reflects the freshest state.
    this.lobbyCache = { at: now, payload };
    return payload;
  }

  private async sendClocks(ws: WebSocket) {
    const session = this.session(ws);
    const watchedId = session.matchId ?? session.watching;
    const match = watchedId ? await this.loadMatch(watchedId) : null;
    if (!match) return send(ws, "n");
    // A client heartbeat is also a chance to notice that a disconnect-pause has
    // outlived its grant, so the opponent's ping alone is enough to restart an
    // absent player's clock even if the alarm chain hiccuped.
    if (releaseExpiredPause(match, Date.now())) await this.saveMatch(match, false);
    if (await this.finishOnFlag(match)) return;
    // Self-heal from the client heartbeat (~every 10s): re-arm this game's own
    // alarm so a pending house-bot move or a clock deadline keeps firing even if
    // the global alarm chain died between deadlines (e.g. an isolate eviction
    // mid-tick left no next alarm). This is what lets a stuck bot game recover
    // on its own instead of freezing until the player refreshes. Cheap: a
    // getAlarm read, and a setAlarm only when this game actually needs an
    // earlier alarm than the one already stored (so a no-op in steady state).
    if (!match.result) {
      try {
        await this.scheduleAlarmForMatch(match);
      } catch {}
    }
    const clocks = this.currentClocks(match);
    send(ws, "n", { wc: Math.round(clocks.w), bc: Math.round(clocks.b) });
  }

  private candidateAlarm(match: StoredMatch, now = Date.now()): number | null {
    const candidates: number[] = [];
    if (match.setup.timeSec && match.startedAt && !match.result && match.runningSince !== null) {
      const active = this.chargedColor(match);
      const grace = this.movesByColor(match, active) === 0 ? firstMoveGraceMs : 0;
      candidates.push(match.runningSince + match.clocks[active] + grace);
    }
    // The end of a disconnect-pause. This candidate is what makes the pause
    // bounded at all: while runningSince is null the flag candidate above is
    // skipped, so without this nothing would ever wake up to restart the clock.
    if (!match.result && match.pauseUntil != null && match.runningSince === null) {
      candidates.push(match.pauseUntil);
    }
    // Draft lock-in deadlines: overdue picks auto-resolve from the alarm.
    if (!match.result) {
      if (match.nerfDeadline && match.nerfOptions && !match.startedAt) candidates.push(match.nerfDeadline + draftPickGraceMs);
      if (match.dtDeadline && match.startedAt) candidates.push(match.dtDeadline);
      // Pending house action (move or draft pick). An overdue timer clamps to
      // just past now so a missed alarm re-fires immediately instead of never —
      // UNLESS the bot is guard-held because the human seat is genuinely gone.
      // In that case houseTick will only skip it, so clamping to now+300 would
      // spin a ~3Hz alarm for the whole abandonment window (up to 30 min),
      // burning CPU on the single thread and helping tip it past its reset
      // limit. When guard-held, drop the pending-action candidate entirely: the
      // move re-arms the moment the human reconnects (reconnectMatch) or pings
      // (sendClocks), and the abandonment GC still fires via its own candidate.
      if (match.botActAt) {
        const guardHeld =
          !!match.startedAt &&
          !!match.bots &&
          (["w", "b"] as Color[]).some(
            (c) => !match.bots?.[c] && match.disconnectedAt[c] && !this.connectedSession(match.id, c),
          );
        if (!guardHeld) candidates.push(Math.max(match.botActAt, now + 300));
      }
    }
    for (const color of ["w", "b"] as Color[]) {
      const disconnectedAt = match.disconnectedAt[color];
      if (disconnectedAt && !match.opponentGoneNotified[color]) candidates.push(disconnectedAt + disconnectGraceMs);
    }
    const expiry = match.completedAt ?? match.createdAt;
    if (match.completedAt) candidates.push(expiry + finishedRetentionMs);
    else if (!match.startedAt) candidates.push(expiry + 30 * 60 * 1000);
    else if (this.connectedSessions(match.id).length === 0) {
      const latestDisconnect = Math.max(match.disconnectedAt.w ?? 0, match.disconnectedAt.b ?? 0);
      if (latestDisconnect) candidates.push(latestDisconnect + 30 * 60 * 1000);
    }

    const next = Math.min(...candidates.filter((candidate) => candidate > now));
    return Number.isFinite(next) ? next : null;
  }

  private async scheduleAlarmForMatch(match: StoredMatch) {
    const next = this.candidateAlarm(match);
    if (!next) return;
    const existing = await this.ctx.storage.getAlarm();
    if (!existing || next < existing) await this.ctx.storage.setAlarm(next);
  }

  private async scheduleNextAlarm(matches: StoredMatch[]) {
    const now = Date.now();
    // One corrupt match must not abort the whole reschedule (which would kill
    // the alarm chain): treat a candidate that throws as "no deadline".
    let next = Math.min(
      ...matches.map((match) => {
        try {
          return this.candidateAlarm(match) ?? Number.POSITIVE_INFINITY;
        } catch {
          return Number.POSITIVE_INFINITY;
        }
      }),
    );
    // Slow house heartbeat while anyone is on the site (a live socket or a
    // recent lobby fetch), so the house roster keeps its queue presence fresh.
    // With nobody online there is no heartbeat: the DO goes idle until the next
    // socket/save/lobby-fetch re-arms it via scheduleAlarmForMatch or the /lobby
    // route's reviveAlarmChain (live house games still wake it per move).
    if (this.sitePresence()) next = Math.min(next, now + houseHeartbeatMs);
    // No pending deadline means no alarm.
    if (!Number.isFinite(next)) return;
    let target = Math.max(next, now + 250);
    // Never push out an earlier still-future alarm someone armed mid-tick
    // (e.g. the house pickup's quick follow-up).
    const existing = await this.ctx.storage.getAlarm();
    if (existing && existing > now && existing < target) target = existing;
    await this.ctx.storage.setAlarm(target);
  }

  // Pull the stored alarm earlier when needed (never later).
  private async armAlarmBy(at: number) {
    const existing = await this.ctx.storage.getAlarm();
    if (!existing || at < existing) await this.ctx.storage.setAlarm(at);
  }

  private humanSocketCount(): number {
    let n = 0;
    for (const [ws] of this.sessions) {
      if (ws.readyState === WebSocket.OPEN) n++;
    }
    return n;
  }

  // True when anyone is on the site: a live socket (playing, watching, or
  // queued) OR a lurker who fetched the lobby over HTTP within sitePresenceTtlMs
  // but holds no socket. Gates house activity (seeks, the slow heartbeat) so the
  // roster fills the lobby while people browse, yet the DO still goes fully idle
  // when the site is truly empty. Replaces the old bare humanSocketCount() > 0
  // presence check now that browsing viewers no longer hold a WebSocket.
  private sitePresence(): boolean {
    return this.humanSocketCount() > 0 || Date.now() - this.lastLobbyHttpAt < sitePresenceTtlMs;
  }

  // Bounded GC sweep: walk the "match:" keyspace one page at a time (never the
  // whole table at once, which on a bloated table blows the DO CPU/storage limit
  // before it can delete anything). Deletes expired records and folds any live
  // ids it sees into the persisted index. Returns true if more pages remain, so
  // the caller can keep draining until the table is clean.
  private async sweepExpired(now = Date.now()): Promise<boolean> {
    const pageSize = 100;
    // start is inclusive; "match;" (';' is ':' + 1) bounds the "match:"
    // keyspace without touching other keys (queue:, house:, live:).
    const start = this.gcCursor ?? "match:";
    const page = await this.ctx.storage.list<StoredMatch>({ start, end: "match;", limit: pageSize });
    const entries = [...page.entries()];
    if (!entries.length) {
      this.gcCursor = null;
      return false;
    }
    await this.ensureLiveIndex();
    let indexChanged = false;
    for (const [key, match] of entries) {
      // The inclusive start re-lists the previous page's last key; skip it.
      if (key === this.gcCursor) continue;
      if (this.isExpired(match, now)) {
        await this.deleteMatch(match);
        indexChanged = true;
        continue;
      }
      if (!match.result && this.liveMatchIndex && !this.liveMatchIndex.has(match.id)) {
        this.liveMatchIndex.add(match.id);
        indexChanged = true;
      }
    }
    const more = entries.length === pageSize;
    this.gcCursor = more ? entries[entries.length - 1][0] : null;
    if (indexChanged) await this.persistLiveIndex();
    return more;
  }

  private isExpired(match: StoredMatch, now: number): boolean {
    if (match.completedAt && now - match.completedAt > finishedRetentionMs) return true;
    if (!match.startedAt && now - match.createdAt > 30 * 60 * 1000) return true;
    if (match.startedAt && this.connectedSessions(match.id).length === 0) {
      const latestDisconnect = Math.max(match.disconnectedAt.w ?? 0, match.disconnectedAt.b ?? 0);
      if (latestDisconnect && now - latestDisconnect > 30 * 60 * 1000) return true;
    }
    return false;
  }

  // /healthz revival hook: one bounded GC page. Cheap, and helps drain a bloated
  // table between alarms. Never a whole-table scan.
  private async cleanupExpired() {
    await this.sweepExpired();
  }

  private async maintenanceAll() {
    const now = Date.now();
    // Flag/deadline enforcement runs on live games only, read cheaply off the
    // persisted index (never a whole-table scan). Finished games need no
    // enforcement; the bounded sweep below is what removes them.
    const live = await this.loadLiveMatches();
    for (const match of live) {
      // One bad match (corrupt record, transient storage error) must not stop
      // flag enforcement for every other live game or break the alarm chain.
      try {
        await this.enforceDraftDeadlines(match, now);
        // Restart a disconnect-pause that has outlived its grant BEFORE the
        // flag check, so the clock the flag check reads is running again and an
        // absent player can actually time out.
        let changed = releaseExpiredPause(match, now);
        changed = (await this.finishOnFlag(match, now, false)) || changed;
        for (const color of ["w", "b"] as Color[]) {
          const disconnectedAt = match.disconnectedAt[color];
          const opponent = this.connectedSession(match.id, color === "w" ? "b" : "w");
          if (disconnectedAt && opponent && !match.opponentGoneNotified[color] && now - disconnectedAt > disconnectGraceMs) {
            send(opponent, "opponentGone");
            match.opponentGoneNotified[color] = true;
            changed = true;
          }
        }
        if (this.isExpired(match, now)) {
          await this.deleteMatch(match);
          continue;
        }
        if (changed) await this.saveMatch(match, false);
      } catch (err) {
        console.error("maintenance failed for match", match.id, err);
      }
    }
    // Watched arena replicas live outside the match table (never persisted, not
    // in the live index), so the flag enforcement above never sees them — sweep
    // them for stranded games on the same cadence.
    try {
      this.sweepExternalReplicas(now);
    } catch (err) {
      console.error("sweepExternalReplicas failed", err);
    }
    // Drain expired/finished records a bounded page at a time. Keep draining
    // fast (a quick follow-up alarm) until the table is clean, then fall back to
    // the normal per-move cadence.
    let more = false;
    try {
      more = await this.sweepExpired(now);
    } catch (err) {
      console.error("sweepExpired failed", err);
    }
    if (more) await this.armAlarmBy(Date.now() + 300);
    await this.scheduleNextAlarm(await this.loadLiveMatches());
  }
}

// Edge-cached lobby snapshot. The payload is public and identical for every
// viewer, so one cached copy per colo serves the whole browsing crowd and the DO
// sees ~1 request per cache window instead of a WebSocket poll per viewer.
// Fails soft: the DO's own error response passes through, so the client keeps
// its last snapshot either way.
//
// STALENESS IS BOUNDED BY THE CACHE KEY, NOT BY TTL HEADERS. The first cut
// stored one FIXED key with `s-maxage=3` and trusted expiry — and production
// served a DAYS-old copy of that key while the DO underneath held 70+ live
// games (verified side by side: /healthz `lobby.games: 72` vs an /api/lobby
// body whose ratings matched a screenshot from days earlier, with the DO's
// /lobby handler never invoked — `lastLobbyHttpAgoMs: null` across a 5-minute
// isolate while a browser polled every 10s). Whatever layer pinned it (an
// ambient Cache API TTL quirk, a zone-level cache rule in front of the
// worker), the lesson is the same: never let a cache's expiry policy be the
// only thing standing between viewers and a frozen lobby. So:
//   • The stored key rotates every LOBBY_EDGE_BUCKET_MS: once the bucket
//     rolls, the old entry is UNREACHABLE regardless of how long some layer
//     keeps it, so staleness is capped at one bucket even if TTLs are ignored.
//   • The response served to the client is `no-store`: browsers and any
//     CDN/zone cache in FRONT of the worker are told to never keep a copy, so
//     the only shared cache is the one under our key control right here.
const LOBBY_EDGE_BUCKET_MS = 3000;
async function handleLobbyEdge(url: URL, env: Env, ctx: ExecutionContext): Promise<Response> {
  // `caches.default` is a Workers-runtime global not present on the DOM
  // CacheStorage type this file is compiled against; cast to reach it.
  const cache = (caches as unknown as { default: Cache }).default;
  // Time-bucketed key: bounds staleness by construction (see header comment).
  // The bucket also absorbs client cache-busting query strings — whatever the
  // browser appends, every request in the same window maps to this one key,
  // so a crowd still costs the DO ~1 hit per bucket.
  const bucket = Math.floor(Date.now() / LOBBY_EDGE_BUCKET_MS);
  const cacheKey = new Request(`${url.origin}/api/lobby?bucket=${bucket}`, { method: "GET" });
  const clientHeaders = {
    "content-type": "application/json",
    // Downstream caches (browser, CDN, any zone rule in front of the worker)
    // must never hold this: the shared caching happens above, under our
    // rotating key, where staleness is provably bounded.
    "cache-control": "no-store",
  };
  const cached = await cache.match(cacheKey);
  if (cached) {
    // Re-wrap: the stored copy carries the cacheable header set; the client
    // must receive the no-store set.
    return new Response(await cached.arrayBuffer(), { status: 200, headers: clientHeaders });
  }
  let doResp: Response;
  try {
    const id = env.GAME_SERVER.idFromName(globalServerName);
    doResp = await env.GAME_SERVER.get(id).fetch(new Request(`${url.origin}/lobby`, { method: "GET" }));
  } catch (err) {
    console.error("lobby edge fetch failed", err);
    return new Response("lobby unavailable", { status: 503 });
  }
  if (!doResp.ok) return doResp;
  const body = await doResp.arrayBuffer();
  // Stored copy: cacheable so cache.put accepts it. The TTL is hygiene (lets
  // the runtime evict rolled-over buckets promptly); correctness comes from
  // the key rotation, which caps effective staleness at one bucket no matter
  // how long this entry actually lives.
  const stored = new Response(body, {
    status: 200,
    headers: { "content-type": "application/json", "cache-control": "public, s-maxage=5" },
  });
  ctx.waitUntil(cache.put(cacheKey, stored));
  return new Response(body, { status: 200, headers: clientHeaders });
}

// Canonical origin. Cloudflare's custom domains already terminate TLS and the
// HSTS header in next.config.mjs pins browsers to https, but a plain-http hit
// (an old bookmark, a pasted link) and the www alias both still reach here as
// distinct origins: crawlers index them separately and a session cookie set on
// one is invisible on the other. One 301 folds them onto https://nerfchess.com.
// Method-agnostic on purpose (a 308 would replay POST bodies onto the redirect
// target, which no caller wants); the health probe is exempt so uptime checks
// against the bare worker hostname keep answering.
const CANONICAL_HOST = "nerfchess.com";
const ALIAS_HOSTS = new Set([`www.${CANONICAL_HOST}`]);

function canonicalRedirect(url: URL): Response | null {
  if (url.pathname === "/healthz") return null;
  const alias = ALIAS_HOSTS.has(url.hostname);
  // Only the production hostnames are folded: localhost (`wrangler dev`,
  // `npm run preview`) and a *.workers.dev preview stay reachable over http.
  if (!alias && url.hostname !== CANONICAL_HOST) return null;
  const insecure = url.protocol === "http:";
  if (!insecure && !alias) return null;
  const target = new URL(url.toString());
  target.protocol = "https:";
  if (alias) target.hostname = CANONICAL_HOST;
  return Response.redirect(target.toString(), 301);
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const redirect = canonicalRedirect(url);
    if (redirect) return redirect;
    if (url.pathname === "/api/lobby" && request.method === "GET") {
      return await handleLobbyEdge(url, env, ctx);
    }
    if (url.pathname === socketPath || url.pathname === "/healthz" || url.pathname.startsWith("/arena/")) {
      try {
        const id = env.GAME_SERVER.idFromName(globalServerName);
        return await env.GAME_SERVER.get(id).fetch(request);
      } catch (err) {
        // The game server threw. Without this the platform returns an opaque
        // 1101 page with no detail. Surface the actual error on /healthz so it
        // can be read from a browser (there is no other log access here), and
        // fail the socket upgrade cleanly instead of crashing the request.
        const message = err instanceof Error ? `${err.name}: ${err.message}` : String(err);
        const stack = err instanceof Error ? err.stack : undefined;
        console.error("game server fetch threw", err);
        if (url.pathname === "/healthz") {
          return Response.json({ ok: false, version: buildVersion, error: message, stack }, { status: 200 });
        }
        return new Response("game server unavailable", { status: 503 });
      }
    }
    return handler.fetch(request, env, ctx);
  },
} satisfies ExportedHandler<Env>;

// @ts-ignore `.open-next/worker.js` is generated by `opennextjs-cloudflare build`.
export { BucketCachePurge, DOQueueHandler, DOShardedTagCache } from "./.open-next/worker.js";
